-- Morpheus Standalone: unsigned recovered-source test build.
-- Original licensed loader and license state are not modified or used.
-- Unload the original Morpheus before loading this script. F7 opens this menu.
local function fail(message)
 print("Morpheus Standalone: "..tostring(message))
 if notify and notify.push then pcall(notify.push,"SPACEx",tostring(message)) end
 return false
end
if not package or not package.preload or not package.loaded then return fail("Lua module support is unavailable") end
for _,name in ipairs({"util","game","paths","this","gui","input","file","dirs"}) do
 if _ENV[name]==nil then return fail("Required Lexis API is missing: "..name) end
end
local ok,edition,version=pcall(function() return game.build(),game.version() end)
if not ok or tostring(edition):lower()~="enhanced" or not tostring(version):find("1158.16",1,true) then
 return fail("This test build requires Enhanced 1158.16; detected "..tostring(edition).." "..tostring(version))
end
local running=package.loaded["MorpheusMouse.app"]
if running and running.started then return fail("This standalone instance is already started") end

package.preload["MorpheusMouse.changelog_modal"]=function(...)
local M={scroll=0,section=1}
local state=require("MorpheusMouse.state")
local theme=require("MorpheusMouse.theme")
local native=require("natives")
local opened=false
local previous_capture=false
local opened_at=0
local version=""
local sections={}
local function within(point,x,y,w,h)return point.x>=x and point.y>=y and point.x<=x+w and point.y<=y+h end
local function key(id)local ok,value=pcall(input.key,id);return ok and value and value.just_pressed==true end
local function pad(id)local ok,value=pcall(input.pad,id);return ok and value and value.just_pressed==true end
local function text(value,x,y,size,tint)theme.text(value):position(vec2(x,y)):scale(size):color(tint):draw()end
local function opaque(token,fallback)
 local values=theme.color_values
 local v=values[token]or values[fallback or "panel_background"]
 return color(v[1],v[2],v[3],255)
end
local function palette()
 local accent=theme.color_values.accent
 local settings=package.loaded["MorpheusMouse.controller_settings"]
 if settings and settings.values then local v=settings.values;accent={v.accent_r,v.accent_g,v.accent_b,255}end
 return{background=opaque("panel_background"),header=opaque("header_background"),sidebar=opaque("sidebar_background"),
 card=opaque("card_background"),border=opaque("border"),text=theme.colors.text,dim=theme.colors.text_dim,
 accent=color(accent[1],accent[2],accent[3],255),muted=theme.colors.text_muted or theme.colors.text_dim,
 selected=theme.colors.text_on_accent or theme.colors.text,backdrop=theme.colors.modal_backdrop}
end
local function wrap(body,limit)
 local lines={}
 for paragraph in (body.."\n"):gmatch("(.-)\n")do
  local line=""
  for token in paragraph:gmatch("%S+")do
   local word=token
   if #line>0 and #line+#word+1>limit then lines[#lines+1]=line;line=""end
   while #word>limit do
    if #line>0 then lines[#lines+1]=line;line=""end
    lines[#lines+1]=word:sub(1,limit);word=word:sub(limit+1)
   end
   line=line==""and word or line.." "..word
  end
  if line~=""then lines[#lines+1]=line end
 end
 return lines
end
local function headline(body,section)
 local value=body:lower()
 if value:find("masterminds",1,true)then return "Masterminds achievement"end
 if value:find("anniversary",1,true)then return "Weapon finishes, clothing & access"end
 if value:find("separate contract",1,true)then return "Five award groups"end
 if value:find("complete today's",1,true)then return "Today's Daily Objectives"end
 if value:find("verify new unlock",1,true)then return "Unlock verification"end
 if value:find("time played",1,true)then return "Playtime & number entry"end
 if value:find("badge",1,true)then return "Badges with breathing room"end
 if value:find("changelog",1,true)then return "Your release briefing"end
 local title=body:match("^([^%.!]+)")or body
 if #title>48 then title=title:sub(1,45):gsub("%s+%S*$","").."..."end
 return title~=""and title or section
end
local function parse(body)
 sections={{name="Added",eyebrow="CAPABILITY UPDATE",title="More within reach.",items={}},
 {name="Fixed",eyebrow="RELIABILITY UPDATE",title="Edits without the friction.",items={}},
 {name="Interface",eyebrow="INTERFACE UPDATE",title="Clearer signals.",items={}}}
 for raw_line in (tostring(body or "").."\n"):gmatch("(.-)\n")do
  local line=raw_line:gsub("^%s*[-*]%s*",""):gsub("^%s+",""):gsub("%s+$","")
  if line~=""then
   local lower=line:lower();local index=1
   if lower:match("^fixed")or lower:match("^repaired")or lower:match("^resolved")then index=2
   elseif lower:find("badge",1,true)or lower:find("changelog",1,true)or lower:match("^interface")then index=3 end
   local section=sections[index]
   section.items[#section.items+1]={title=headline(line,section.name),body=line}
  end
 end
 if #sections[1].items+#sections[2].items+#sections[3].items==0 then sections[1].items[1]={title="Release notes",body="No release notes are available for this version."}end
end
function M.is_open()return opened end
function M.open(release,body)
 if not opened then previous_capture=state.modal_input_capture end
 version=tostring(release or "");parse(body)
 M.scroll=0;M.section=1
 for i,section in ipairs(sections)do if #section.items>0 then M.section=i;break end end
 opened=true;opened_at=util.get_tick_count();state.modal_input_capture=true;input.show_cursor(true)
 return true
end
function M.close()
 if not opened then return end
 opened=false;state.modal_input_capture=previous_capture;input.show_cursor(state.is_open==true)
end
M.shutdown=M.close
local function select_section(index)
 index=math.max(1,math.min(#sections,index))
 if index~=M.section then M.section=index;M.scroll=0 end
end
function M.draw(resolution)
 if not opened then return false end
 local screen=resolution or game.resolution()
 local scale=math.max(0.65,math.min(1.25,screen.y/1080))
 local w=math.min(860*scale,screen.x-40*scale)
 local h=math.min(600*scale,screen.y-40*scale)
 local x,y=(screen.x-w)/2,(screen.y-h)/2
 local side=w<560*scale and 126*scale or 170*scale
 local padding=24*scale
 local top=y+103*scale
 local content_x=x+side+padding
 local content_w=w-side-padding*2
 local body_y=top+84*scale
 local body_h=h-260*scale
 local font=15*scale
 local line_height=24*scale
 local p=palette()
 local canvas=theme.color_values.canvas
 local galaxy_theme=canvas and canvas[1]+canvas[2]+canvas[3]<420
 if galaxy_theme then
  p.header=color(5,7,12,35);p.sidebar=color(5,7,12,65)
  p.card=color(5,7,12,165);p.border=color(82,119,239,65)
 end
 local point=input.mouse_position()
 local mouse=input.mouse(1)
 local close_x,close_y,close_w,close_h=x+w-padding-134*scale,y+h-52*scale,134*scale,32*scale
 local cross_x,cross_y=x+w-45*scale,y+17*scale
 local ready=util.get_tick_count()-opened_at>=150
 theme.begin_frame();native.disable_all_control_actions(0);native.disable_all_control_actions(1)
 if ready then
  if key(0x1B)or pad(202)or pad(201)then M.close();return false end
  if mouse.just_pressed then
   if not within(point,x,y,w,h)or within(point,close_x,close_y,close_w,close_h)or within(point,cross_x,cross_y,28*scale,28*scale)then M.close();return false end
   for i=1,3 do if within(point,x+12*scale,top+42*scale+(i-1)*48*scale,side-24*scale,40*scale)then select_section(i)end end
   if within(point,content_x,close_y,42*scale,close_h)then M.scroll=M.scroll-96*scale end
   if within(point,content_x+48*scale,close_y,42*scale,close_h)then M.scroll=M.scroll+96*scale end
  end
  if key(0x25)or pad(189)then select_section(M.section-1)end
  if key(0x27)or pad(190)then select_section(M.section+1)end
  if key(0x26)or pad(188)or native.is_disabled_control_just_pressed(0,241)then M.scroll=M.scroll-72*scale end
  if key(0x28)or pad(187)or native.is_disabled_control_just_pressed(0,242)then M.scroll=M.scroll+72*scale end
 end
 local section=sections[M.section]
 local layouts={};local total=0
 local limit=math.max(12,math.floor((content_w-42*scale)/(font*0.65)))
 for _,item in ipairs(section.items)do
  local lines=wrap(item.body,limit)
  local titles=wrap(item.title,math.max(10,math.floor((content_w-42*scale)/(17*scale*0.65))))
  local height=(#titles*24+#lines*24+34)*scale
  layouts[#layouts+1]={item=item,lines=lines,titles=titles,y=total,height=height}
  total=total+height+12*scale
 end
 local maximum=math.max(0,total-12*scale-body_h)
 M.scroll=math.max(0,math.min(maximum,M.scroll))
 theme.draw_rect(vec2(0,0),screen,p.backdrop,0)
 if galaxy_theme then
  theme.draw_glass_surface("shell_background",vec2(x,y),vec2(w,h),10*scale)
 else theme.draw_rect(vec2(x,y),vec2(w,h),p.background,10*scale)end
 theme.draw_outline(vec2(x,y),vec2(w,h),1*scale,p.accent,10*scale)
 theme.draw_rect(vec2(x+1,y+1),vec2(w-2,102*scale),p.header,9*scale)
 theme.draw_rect(vec2(x+padding,y+25*scale),vec2(4*scale,44*scale),p.accent,2*scale)
 text("S P A C E x",x+padding+16*scale,y+21*scale,25*scale,p.text)
 text("FLIGHT SOFTWARE / CHANGELOG",x+padding+16*scale,y+61*scale,11*scale,p.dim)
 text("X",cross_x+8*scale,cross_y+4*scale,16*scale,p.dim)
 theme.draw_rect(vec2(x+1,top),vec2(side-1,h-170*scale),p.sidebar,0)
 gui.line(vec2(x+side,top),vec2(x+side,y+h-68*scale),1*scale,p.border)
 text("LATEST UPDATE",x+20*scale,top+15*scale,10*scale,p.dim)
 for i,entry in ipairs(sections)do
  local nav_y=top+42*scale+(i-1)*48*scale
  local active=i==M.section
  if active then theme.draw_rect(vec2(x+12*scale,nav_y),vec2(side-24*scale,40*scale),p.accent,5*scale)end
  text(entry.name,x+24*scale,nav_y+11*scale,14*scale,active and p.selected or p.dim)
  text(tostring(#entry.items),x+side-38*scale,nav_y+12*scale,12*scale,active and p.selected or p.muted)
 end
 text(section.eyebrow,content_x,top+14*scale,10*scale,p.dim)
 local hero=wrap(section.title,math.max(12,math.floor(content_w/(24*scale*0.65))))
 text(hero[1]or section.name,content_x,top+36*scale,24*scale,p.text)
 gui.push_clip(vec2(content_x,body_y),vec2(content_w,body_h))
 for i,layout in ipairs(layouts)do
  local item_y=body_y+layout.y-M.scroll
  if item_y+layout.height>=body_y and item_y<body_y+body_h then
   theme.draw_rect(vec2(content_x,item_y),vec2(content_w-10*scale,layout.height),p.card,6*scale)
   text(string.format("%02d",i),content_x+12*scale,item_y+16*scale,11*scale,p.dim)
   local offset=14*scale
   for _,line in ipairs(layout.titles)do text(line,content_x+38*scale,item_y+offset,17*scale,p.text);offset=offset+24*scale end
   offset=offset+5*scale
   for _,line in ipairs(layout.lines)do text(line,content_x+38*scale,item_y+offset,font,p.dim);offset=offset+line_height end
  end
 end
 if #layouts==0 then text("No "..section.name:lower().." notes in this release.",content_x+12*scale,body_y+20*scale,14*scale,p.dim)end
 gui.pop_clip()
 if maximum>0 then
  local thumb=math.max(26*scale,body_h*body_h/total)
  theme.draw_rect(vec2(x+w-14*scale,body_y),vec2(3*scale,body_h),p.border,1)
  theme.draw_rect(vec2(x+w-14*scale,body_y+(body_h-thumb)*M.scroll/maximum),vec2(3*scale,thumb),p.accent,1)
 end
 gui.line(vec2(x+1,y+h-68*scale),vec2(x+w-1,y+h-68*scale),1*scale,p.border)
 text("VERSION",x+20*scale,y+h-53*scale,9*scale,p.muted)
 text(version,x+20*scale,y+h-36*scale,11*scale,p.dim)
 if maximum>0 then
  theme.draw_rect(vec2(content_x,close_y),vec2(42*scale,close_h),p.card,4*scale)
  theme.draw_rect(vec2(content_x+48*scale,close_y),vec2(42*scale,close_h),p.card,4*scale)
  text("Up",content_x+11*scale,close_y+9*scale,11*scale,p.text)
  text("Down",content_x+54*scale,close_y+9*scale,11*scale,p.text)
 end
 theme.draw_rect(vec2(close_x,close_y),vec2(close_w,close_h),p.accent,5*scale)
 text("Close briefing",close_x+17*scale,close_y+8*scale,13*scale,p.selected)
 require("MorpheusMouse.cursor").draw(point)
 return true
end
return M

end

