  if value then invoker.call(0x2C933ABF17A1DF41,"CS1_railwayB_tunnel")
  elseif M.active then invoker.call(0x0F07E7745A236711)end
 end)
 if not ok then return false,tostring(reason)end
 M.active=value==true;return true
end
function M.cleanup()return M.set(false)end
M.shutdown=M.cleanup
function M.row()return{label="Tunnel Haze Filter",value=function()return M.active and "On"or "Off"end,run=function()return M.set(not M.active)end,adjust=function()return M.set(not M.active)end}end
return M
end
