package.preload["MorpheusMouse.aircraft_carrier"]=function(...)
local M={busy=false}
local native=require("natives")
local ipls={"hei_carrier","hei_carrier_int1","hei_carrier_int2","hei_carrier_int3","hei_carrier_int4","hei_carrier_int5","hei_carrier_int6","hei_carrier_LODLights"}
function M.spawn()
 if M.busy then return false,"Aircraft carrier is already loading"end
 if type(native.request_ipl)~="function"or type(native.is_ipl_active)~="function"then return false,"Map loading API is unavailable"end
 M.busy=true
 local ok,reason=pcall(function()
  for _,name in ipairs(ipls)do native.request_ipl(name)end
  local ready=false
  for attempt=1,80 do
   ready=true
   for _,name in ipairs(ipls)do if not native.is_ipl_active(name)then ready=false;break end end
   if ready then break end
   require("MorpheusMouse.job_runtime").yield(100)
  end
  if not ready then error("Carrier map sections did not all load; try again",0)end
  local moved,detail=require("MorpheusMouse.controller_teleport").go({x=3088.4688,y=-4708.33,z=21.567},false)
  if not moved then error(detail or "Carrier teleport failed",0)end
 end)
 M.busy=false
 pcall(function()require("MorpheusMouse.diagnostics").event("spawn","aircraft_carrier",{success=ok,reason=not ok and tostring(reason)or nil})end)
 if not ok then return false,tostring(reason)end
 require("MorpheusMouse.state").notify_success("Aircraft carrier loaded; teleported aboard")
 return true
end
return M

end

package.preload["MorpheusMouse.glass_blur"]=function(...)
local M={owned=false,index=nil,attempted=false,strength=nil}
function M.shutdown()
 if M.owned then
  local ok=pcall(function()
   if invoker.call(0xFDF3D97C674AFB66).int==M.index then invoker.call(0x0F07E7745A236711)end
  end)
  if not ok then return false end
 end
 M.owned=false;M.index=nil;M.strength=nil;M.attempted=false
 return true
end
function M.update(open,ui)
 local strength=math.max(0,math.min(1,tonumber(ui.glass_blur_strength)or .65))
 if not open or ui.glass_blur_enabled~=true or strength<=0 then
  M.shutdown();return
 end
 if M.attempted and not M.owned then return end
 M.attempted=true
 local ok,message=pcall(function()
  local current=invoker.call(0xFDF3D97C674AFB66).int
  if M.owned and current~=M.index then
   M.owned=false;M.index=nil;M.strength=nil
   return 'Blur paused: another game effect is active.'
  end
  if not M.owned then
   if current~=-1 then return 'Blur paused: another game effect is active.'end
   invoker.call(0x2C933ABF17A1DF41,'hud_def_blur')
   M.index=invoker.call(0xFDF3D97C674AFB66).int
   if not M.index or M.index<0 then return 'Blur modifier did not load.'end
   M.owned=true
  end
  if M.strength~=strength then
   invoker.call(0x82E7FFCD5B2326B3,strength+0.0);M.strength=strength
  end
 end)
 if not ok then
  M.shutdown();M.attempted=true
  ui.glass_blur_status='Enable Natives permission; switch blur off/on to retry.'
  print('SPACEx optional blur: '..tostring(message))
 elseif message then ui.glass_blur_status=message
 else ui.glass_blur_status='Whole-scene blur while the menu is open.'end
end
return M
end

package.preload["MorpheusMouse.orbit_embedded"]=function(...)
local frames={
header={"","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","",""},
blur={"","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","",""},
}
local alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
local lookup={};for i=1,#alphabet do lookup[alphabet:sub(i,i)]=i-1 end
local function decode(s)
 local out={}
 for i=1,#s,4 do
  local a,b=lookup[s:sub(i,i)],lookup[s:sub(i+1,i+1)]
  local c,d=lookup[s:sub(i+2,i+2)],lookup[s:sub(i+3,i+3)]
  assert(a and b,'Invalid embedded animation')
  local n=a*262144+b*4096+(c or 0)*64+(d or 0)
  out[#out+1]=string.char(math.floor(n/65536)%256)
  if c then out[#out+1]=string.char(math.floor(n/256)%256)end
  if d then out[#out+1]=string.char(n%256)end
 end
 return table.concat(out)
end
return {write=function(kind,index)
 local source=frames[kind]and frames[kind][index+1]
 assert(source,'Missing embedded animation frame')
 local path=paths.game..'/scripts/spacex-nebula-'..kind..'-'..index..'.jpg'
 local bytes=decode(source)
 local handle=file.open(path,{create_if_not_exists=true})
 assert(handle and handle.valid,'Could not extract animation frame')
 handle.text=bytes
 assert(handle.text==bytes,'Animation frame readback failed')
 return path
end}
end
package.preload["MorpheusMouse.galaxy_background"]=function(...)
local M={frames={background={},header={},blur={}},failed={}}
