 gui.pop_clip()
 if not ok then error(err,0)end
end
function M.draw(pos,size,radius)
 M.bounds={pos=pos,size=size}
 if size.x<=0 or size.y<=0 then return false end
 local image=frame('header')
 if image then gui.image_rounded(image,pos,size,tint,radius or 0)else gui.rect(pos,size):filled():color(base):rounding(radius or 0):draw()end
 return true
end
function M.overlay(key,pos,size)
 if key~='header_background'and key~='panel_background'and key~='sidebar_background'and key~='hud_surface'then return end
