package.preload["MorpheusMouse.black_screen_recovery"]=function(...)
local M={}
local native=require("natives")
local function flag(name)
 local fn=native[name]
 if type(fn)~="function" then error("Recovery check unavailable: "..name,0)end
 local value=fn()
 if type(value)~="boolean" then error("Recovery check returned an invalid value: "..name,0)end
 return value
end
function M.run()
 local ok,reason=pcall(function()
  if flag("network_is_in_transition") or flag("is_player_switch_in_progress") then error("A session or character transition is still active; try again after it finishes",0)end
  for _,name in ipairs({"fm_mission_controller","fm_mission_controller_2020"})do
   if script.running(name)then error("The mission controller is still running; recovery cannot confirm the mission has ended",0)end
  end
  if not flag("network_is_game_in_progress")then error("Wait until GTA Online has returned to the session",0)end
  local loading=flag("get_is_loading_screen_active")
  local faded=flag("is_screen_faded_out") or flag("is_screen_fading_out")
  if not loading and not faded then error("No black loading screen or stuck fade is detected",0)end
  if type(native.do_screen_fade_in)~="function" or (loading and type(native.shutdown_loading_screen)~="function")then error("Screen recovery natives are unavailable",0)end
  if loading then native.shutdown_loading_screen()end
  native.do_screen_fade_in(500)
  require("MorpheusMouse.job_runtime").yield(700)
  if flag("get_is_loading_screen_active") or flag("is_screen_faded_out") or flag("is_screen_fading_out")then error("The game is still holding the black screen; recovery did not clear it",0)end
 end)
 pcall(function()require("MorpheusMouse.diagnostics").event("recovery","black_screen",{success=ok,reason=not ok and tostring(reason)or nil})end)
 if not ok then return false,tostring(reason)end
 require("MorpheusMouse.state").notify_success("Black screen cleared")
 return true
end
return M

end

