package.preload["MorpheusMouse.business_supply_recovery"]=function(...)
-- Researched against Enhanced 1158.16 / Online 1.73 freemode.
-- func_21959/21961 use seven purchase timestamps at Global_1673820.
-- Slot 5 is Bunker; slot 6 is Acid Lab; 0..4 are MC property slots.
-- This only shortens the wait for an existing paid supply order.
local M={status="Ready; purchase supplies before accelerating delivery",busy=false}
local native=require("natives")
local compat=require("MorpheusMouse.runtime_compat")
local PROFILE={edition="Enhanced",game_version="1158.16",online_version="1.73"}
local BASE=1673820
local function integer(value)
 return type(value)=="number" and value==math.floor(value) and value>=0 and value<2147483648
end
local function read(index)
 local ok,value=pcall(function()return script.globals(index).int32 end)
 if not ok or not integer(value)then return nil,"Cannot read supply receiver "..tostring(index)end
 return value
end
local function context()
 if not compat.matches(PROFILE,true)then return nil,"Requires Enhanced 1158.16 / Online 1.73"end
 if not script.running("freemode")then return nil,"Enter GTA Online Freemode first"end
 if native.network_is_session_started()~=true or native.network_is_activity_session()==true or native.network_is_in_transition()==true then
  return nil,"Use this in Freemode outside missions and session transitions"
 end
 local character=account.character()
 if character~=0 and character~=1 then return nil,"Active character is unavailable"end
 local size,reason=read(BASE)
 if size~=7 then return nil,reason or "The seven-slot supply receiver did not match this build"end
 local now=native.get_cloud_time_as_int()
 if not integer(now)or now<86400 then return nil,"Cloud time is unavailable"end
 local biker,why=read(262145+18857)
 local bunker,why2=read(262145+21367)
 if not biker or not bunker then return nil,why or why2 end
 if biker>86400 or bunker>86400 then return nil,"Supply delivery delays are outside the researched bounds"end
 return {character=character,now=now,biker=biker,bunker=bunker}
end
local scopes={mc={0,1,2,3,4},bunker={5},acid={6},all={0,1,2,3,4,5,6}}
local function expedite(scope)
 local slots=scopes[scope]
 if not slots then return false,"Unknown supply category"end
 local ctx,reason=context()
 if not ctx then return false,reason end
 local pending={};local ready=0
 -- Read and validate the full request before the first write.
 for _,slot in ipairs(slots)do
  local timestamp,why=read(BASE+1+slot)
  if timestamp==nil then return false,why end
  if timestamp>ctx.now then return false,"A supply timestamp is ahead of cloud time; no changes made"end
  if timestamp>0 then
   local delay=slot==5 and ctx.bunker or ctx.biker
   if ctx.now-timestamp>=delay then ready=ready+1
   else pending[#pending+1]={slot=slot,original=timestamp,target=math.max(1,ctx.now-delay-1)}end
  end
 end
 local changed=0
 for _,order in ipairs(pending)do
  local current,why=context()
  if not current or current.character~=ctx.character then
   return false,tostring(why or "Active character changed").."; timers changed: "..changed
  end
  local index=BASE+1+order.slot
  local value,why=read(index)
  if value==nil then return false,why.."; timers changed: "..changed end
  if value==order.original then
   script.globals(index).int32=order.target
   local observed,why=read(index)
   -- The game may consume an eligible order and clear its timestamp immediately.
   if observed~=order.target and observed~=0 then
    return false,tostring(why or "Supply timer readback changed").."; timers changed: "..changed
   end
   changed=changed+1
  elseif value~=0 then
   return false,"Supply order changed during the request; stopped after "..changed.." timer changes"
  end
 end
 return true,"Supply timers accelerated: "..changed.."; already eligible: "..ready..". "..
  (changed+ready==0 and "No purchased supplies are pending." or "GTA still processes delivery; check the business supply bar in Freemode.")
end
function M.expedite(scope)
 if M.busy then return false,"A supply request is already running"end
 M.busy=true
 local ok,result,detail=pcall(expedite,scope)
 M.busy=false
 if not ok then result,detail=false,"Supply request failed: "..tostring(result)end
 M.status=tostring(detail)
 local state=require("MorpheusMouse.state")
 if result then state.notify_info(M.status)end
 return result,M.status
end
function M.rows()
 local rows={}
 for _,item in ipairs({{"Accelerate Purchased MC Supplies","mc"},{"Accelerate Purchased Bunker Supplies","bunker"},{"Accelerate Purchased Acid Lab Supplies","acid"},{"Accelerate All Purchased Supplies","all"}})do
  local scope=item[2]
  rows[#rows+1]={label=item[1],run=function()return M.expedite(scope)end}
 end
 rows[#rows+1]={label="Show Supply Delivery Status",run=function()require("MorpheusMouse.state").notify_info(M.status);return true end}
 return rows
end
return M

end

package.preload["MorpheusMouse.nightclub_income"]=function(...)
-- Enhanced 1158.16 freemode func_22379: integer 7211 is income time left;
-- 7212 is safe cash; 6551 identifies the owned Nightclub property.
-- Safe capacity is tunable 23773. Income amounts are deliberately unchanged.
local M={status="Ready",active=false,worker=nil,character=nil,pending=nil,next_request=0,loop=false}
local native=require("natives")
local threads=require("MorpheusMouse.runtime_threads")
local compat=require("MorpheusMouse.runtime_compat")
local PROFILE={edition="Enhanced",game_version="1158.16",online_version="1.73"}
local function int(v)return type(v)=="number"and v==math.floor(v)and v>=0 and v<2147483648 end
local function read(index,character)
 local hash=native.get_stat_hash_for_character_stat(0,index,character)
 if type(hash)~="number"or hash==0 then return nil,"Cannot resolve Nightclub stat "..index end
 local output=pointer_int()
 output.value=0
 local ok,result=pcall(native.stat_get_int,hash,output,-1)
 local value=tonumber(output.value)
 output:free()
 local accepted=result==true or (tonumber(result)~=nil and tonumber(result)~=0)
 if not ok then return nil,"Nightclub stat "..index.." read error: "..tostring(result)end
 if not accepted then return nil,"Nightclub stat "..index.." read rejected (result "..tostring(result)..")"end
 if not int(value)then return nil,"Nightclub stat "..index.." returned invalid value "..tostring(value)end
 return value,hash
end
local function snapshot()
 if not compat.matches(PROFILE,true)then return nil,"Requires Enhanced 1158.16 / Online 1.73"end
 if not script.running("freemode")or native.network_is_session_started()~=true then return nil,"Enter Online Freemode first"end
 if native.network_is_activity_session()==true or native.network_is_in_transition()==true then return nil,"Stopped for a mission or session transition"end
 local character=account.character()
 if character~=0 and character~=1 then return nil,"Active character is unavailable"end
 local property,reason=read(6551,character)
 if property==nil then return nil,reason end
 if property==0 then return nil,"This character does not own a Nightclub"end
 local cash,reason=read(7212,character)
 if cash==nil then return nil,reason end
 local timer,hash=read(7211,character)
 if timer==nil then return nil,hash end
 local capacity=script.globals(262145+23773).int32
 if not int(capacity)or capacity<1 or capacity>1000000 then return nil,"Nightclub safe capacity is outside the researched bounds"end
 if cash>capacity then return nil,"Safe balance exceeds current capacity; no changes made"end
 if timer>2880000 then return nil,"Nightclub income countdown is outside the researched bounds"end
 return {character=character,property=property,cash=cash,capacity=capacity,timer=timer,timer_hash=hash}
end
local function tell(good,text)
 M.status=text
 local state=require("MorpheusMouse.state")
 if good then state.notify_info(text)else state.notify_warning(text)end
end
local function restore_pending()
 local p=M.pending
 if not p or not p.wrote then return end
 -- Restore only an unconsumed request on the same character. Never restore
 -- after GTA advances its countdown or after the character changes.
 pcall(function()
  if account.character()~=M.character then return end
  if not compat.matches(PROFILE,true)or not script.running("freemode")then return end
  if native.network_is_in_transition()then return end
  local timer,hash=read(7211,M.character)
  if timer==1 then native.stat_set_int(hash,p.previous_timer,true)end
 end)
end
function M.stop(reason,failed)
 if not M.active then return true end
 restore_pending()
 local worker=M.worker
 M.worker=nil;M.active=false;M.pending=nil;M.character=nil;M.property=nil
 if worker then threads.stop(worker,"nightclub_income_stop")end
 tell(not failed,reason or "Nightclub income loop stopped")
 return true
end
local function update()
 local ctx,reason=snapshot()
 if not ctx then M.stop(reason,true);return false end
 if ctx.character~=M.character or ctx.property~=M.property then M.stop("Stopped: character or Nightclub changed",true);return false end
 local now=util.get_tick_count()
 if M.pending then
  if ctx.cash>M.pending.cash then
   local gain=ctx.cash-M.pending.cash
   M.pending=nil
   M.next_request=now+10000
   tell(true,"Nightclub safe increased by $"..gain.."; balance $"..ctx.cash.." / $"..ctx.capacity..". Collect at your safe.")
   if not M.loop then M.stop("Nightclub income cycle verified; safe balance $"..ctx.cash);return false end
  elseif ctx.cash<M.pending.cash then
   M.stop("Safe balance changed during the request; stopped to avoid treating a collection as income",true);return false
  elseif now<M.pending.started or now-M.pending.started>=45000 then
   M.stop("No safe increase observed within 45 seconds. No payout was confirmed; stopped.",true);return false
