 if now<M.next_request then return true end
 if ctx.timer<=1 then
  M.pending={cash=ctx.cash,started=now,previous_timer=ctx.timer}
  M.status="Income is already due; waiting for GTA"
  return true
 end
 M.pending={cash=ctx.cash,started=now,previous_timer=ctx.timer}
 if native.stat_set_int(ctx.timer_hash,1,true)~=true then M.pending=nil;M.stop("Nightclub countdown write rejected",true);return false end
 M.pending.wrote=true
 local observed,why=read(7211,ctx.character)
 if observed==nil then M.stop(why,true);return false end
