end
function M.rows()
 return{
  {label="Start Nightclub Income Loop",run=function()return M.start(true)end},
  {label="Request One Income Cycle",run=function()return M.start(false)end},
  {label="Stop Nightclub Income Loop",run=function()return M.stop()end},
  {label="Show Nightclub Status",value=function()return M.active and "Running"or "Stopped"end,run=function()tell(true,M.status);return true end}
 }
end
function M.cleanup()if M.active then M.stop("Nightclub income stopped on unload")end end
return M

end

package.preload["MorpheusMouse.script_updater"]=function(...)
local M={busy=false,editing=false,status="Update address not configured."}
local state=require("MorpheusMouse.state")
local native=require("natives")
local BUILD=20261030123026 -- SPACEX_UPDATE_BUILD
local DEFAULT_FEED="https://raw.githubusercontent.com/OTBxSlime/SPACEx-Updates/main/update.json" -- SPACEX_UPDATE_FEED
local VARIANT="mouse" -- SPACEX_UPDATE_VARIANT
local FILENAME="SPACExMouse.lua" -- SPACEX_UPDATE_FILENAME
local root=paths.game.."\\scripts\\"
local target=root..FILENAME
local config=target..".updates.txt"
local url=DEFAULT_FEED
local auto=true
local RELEASE_NOTES="- Added blue nebula video playback to the mouse UI, including built-in animation frames for updates.\n- Added blurred control and section backgrounds, black star hover effects, and matching sidebar highlights.\n- Fixed six reproduced Lua issues in heist lookups, audit output, diagnostics, imports, and protection error reporting.\n- Preserved model-guard quarantine; live protection crashes remain under investigation." -- SPACEX_RELEASE_NOTES
local notes_version=tostring(BUILD)
local latest_notes=RELEASE_NOTES
local function capture_notes(release)
 if type(release.changelog)~="table"then return end
 local lines={}
 for i=1,math.min(#release.changelog,8)do
  local item=release.changelog[i]
  if type(item)=="string"then
   item=item:gsub("[%c]"," "):sub(1,220)
   if #item>0 then lines[#lines+1]="- "..item end
  end
 end
 if #lines>0 then latest_notes=table.concat(lines,"\n");notes_version=tostring(release.version or release.build)end
end
function M.show_changelog()
 return require("MorpheusMouse.changelog_modal").open(notes_version,latest_notes)
end

local function valid_url(value)
 return type(value)=="string"and #value<=1500 and value:match("^https://[%w%.%-]+/[^%s]*%.json$")~=nil
end
local function read(path)
 local handle=file.open(path,{})
 assert(handle and handle.valid,"Could not read "..path)
 assert(type(handle.text)=="string","File text unavailable")
 return handle.text
end
local function write(path,text)
 local handle=file.open(path,{create_if_not_exists=true})
 assert(handle and handle.valid,"Could not open "..path)
 handle.text=text
 assert(read(path)==text,"File readback did not match: "..path)
end
local function save_config()
 write(config,"auto="..(auto and "1"or "0").."\nurl="..url.."\n")
end
local function notice(text,quiet)
 M.status=text
 if not quiet then state.notify_info(text)end
end
local function digest(text)
 assert(type(openssl)=="table","This Lexis build lacks the SHA-256 API")
 local raw=openssl.hash("sha256",text)
 assert(openssl.success()and type(raw)=="string"and #raw==32,"SHA-256 calculation failed")
 local hex=openssl.hex_encode(raw)
 assert(openssl.success()and type(hex)=="string"and #hex==64,"SHA-256 encoding failed")
 return hex:lower()
end
local function install(text,release)
 assert(type(text)=="string"and #text>=1000 and #text<=8*1024*1024,"Invalid update file size")
 assert(digest(text)==release.sha256:lower(),"Update checksum mismatch; current script kept")
 local source=text:gsub("^\239\187\191","")
 local compiled,reason=load(source,"@"..FILENAME,"t",_ENV)
 assert(compiled,"Update syntax check failed: "..tostring(reason))
 local build=tonumber(source:match("local BUILD=(%d+) %-%- SPACEX_UPDATE_BUILD"))
 assert(build==release.build,"Update build number does not match its manifest")
 local variant=source:match('local VARIANT="([%w_]+)" %-%- SPACEX_UPDATE_VARIANT')
 assert(variant==VARIANT,"Update is for a different SPACEx script")
 -- Stage and validate before replacing only the script; settings/assets stay separate.
 write(target..".next",text)
 local previous=read(target)
 write(target..".previous",previous)
 local ok,reason=pcall(write,target,text)
 if not ok then
  local restored=pcall(write,target,previous)
  error(tostring(reason)..(restored and "; previous script restored"or "; restore the .previous backup before reloading"),0)
 end
 notice("SPACEx "..tostring(release.version or release.build).." downloaded. Reload the script to use it.",false)
end
function M.check(quiet)
 if M.busy then return false,"An update check is already running."end
 if not valid_url(url)then notice("Set the published update address in Settings > Updates first.",quiet);return true end
 if type(http)~="table"or type(http.fetch_async)~="function"then return false,"Enable HTTP access for this script in Lexis."end
 M.busy=true;M.status="Checking for SPACEx updates..."
 local function failure(reason)
  M.busy=false;M.status="Update check stopped: "..tostring(reason)
  if not quiet then state.notify_warning(M.status)end
 end
 local ok,queued=pcall(http.fetch_async,url,{method="GET",headers={}},function(result)
  local ok,reason=pcall(function()
   assert(result and result.success and result.status==200,"Update manifest download failed")
   local manifest=result.json
   assert(type(manifest)=="table"and manifest.schema==1 and type(manifest.releases)=="table","Invalid update manifest")
   local release=manifest.releases[VARIANT]
   assert(type(release)=="table"and type(release.build)=="number"and release.build==math.floor(release.build),"No valid release for "..VARIANT)
   if release.build>=BUILD then capture_notes(release)end
   if release.build<=BUILD then M.busy=false;notice("SPACEx is up to date.",quiet);return end
   assert(release.file==FILENAME,"Unexpected update filename")
   assert(type(release.sha256)=="string"and #release.sha256==64 and release.sha256:match("^%x+$"),"Invalid release checksum")
   local download=url:match("^(https://.*/)")..FILENAME
   local queued=http.fetch_async(download,{method="GET",headers={}},function(payload)
    local ok,reason=pcall(function()
     assert(payload and payload.success and payload.status==200,"Script download failed")
     install(payload.text,release)
    end)
    M.busy=false
    if not ok then failure(reason)end
   end)
   assert(queued,"Could not schedule script download")
  end)
  if not ok then failure(reason)end
 end)
 if not ok or not queued then failure(ok and "Could not schedule update check"or queued);return false,M.status end
 return true
end
function M.set_address(value)
 if M.busy then return false,"Wait for the current update check."end
 value=tostring(value or""):match("^%s*(.-)%s*$")
 if not valid_url(value)then return false,"Enter the HTTPS URL of the published update manifest (.json)."end
 local previous=url;url=value
 local ok,reason=pcall(save_config)
 if not ok then url=previous;return false,tostring(reason)end
 notice("Update address saved. Select Check for Updates.",false);return true
end
local function edit_address()
 if M.editing then return false,"Finish the current text entry first."end
 M.editing=true
 local ok,result,detail=pcall(function()
  native.display_onscreen_keyboard(0,"FMMC_KEY_TIP8","",url,"","","",1500)
  local status
  repeat require("MorpheusMouse.job_runtime").yield(0);status=native.update_onscreen_keyboard()until status~=0
  if status~=1 then return true end
  return M.set_address(invoker.call(0x8362B09B91893647).str)
 end)
 M.editing=false
 if not ok then return false,tostring(result)end
 return result,detail
end
function M.start()
 local exists=file.exists(config)
 if exists then
  local ok,text=pcall(read,config)
  if ok then
   auto=text:match("auto=(%d)")~="0"
   local saved=text:match("url=([^\r\n]+)")
   if valid_url(saved)then url=saved end
  end
 end
 if valid_url(url)then M.status="Ready to check for updates."end
 if auto and valid_url(url)then local ok,reason=pcall(M.check,true);if not ok then M.busy=false;M.status=tostring(reason)end end
end
function M.rows()
 return{
  {label="Check for Updates",run=function()return M.check(false)end},
  {label="View Changelog",run=M.show_changelog},
  {label="Automatic Updates",value=function()return auto and "On"or "Off"end,run=function()
   local previous=auto;auto=not auto;local ok,reason=pcall(save_config);if not ok then auto=previous;return false,tostring(reason)end;return true
  end},
  {label="Set Update Address",run=edit_address},
  {label="Update Status",value=function()return M.busy and "Checking..."or tostring(BUILD)end,run=function()state.notify_info(M.status);return true end},
 }
end
return M

end
