 if not script.running("freemode")or not success(native.network_is_session_started())or success(native.network_is_in_transition())or success(native.network_is_activity_session())then return false,"Use in Online Freemode outside activities and transitions"end
 return true
end
local function read(key)
 local float=key=="ratio"
 local getter=float and native.stat_get_float or native.stat_get_int
 if type(getter)~="function"then return nil,"Stat getter unavailable: "..key end
 local output=float and pointer_float()or pointer_int()
 output.value=0
 local ok,result=pcall(getter,native.get_hash_key(names[key]),output,-1)
 local value=tonumber(output.value);output:free()
 if not ok or not success(result)or not value or value~=value or value==math.huge or value==-math.huge then return nil,"Cannot read "..names[key]..": "..tostring(result)end
 return value
end
local function snapshot()
 local out={}
 for _,key in ipairs({"kills","deaths","suicides","ratio"})do
  local v,why=read(key);if v==nil then return nil,why end
  if key~="ratio"and(v<0 or v~=math.floor(v)or v>=2147483648)then return nil,"Invalid counter: "..key end
  out[key]=v
 end
 return out
end
local function write(key,value)
 local setter=key=="ratio"and native.stat_set_float or native.stat_set_int
 if type(setter)~="function"then return false,"Stat setter unavailable: "..key end
 local ok,result=pcall(setter,native.get_hash_key(names[key]),value,true)
 if not ok or not success(result)then return false,"Write rejected for "..names[key]..": "..tostring(result)end
 local observed,why=read(key)
 if observed==nil then return false,why end
 if key=="ratio"then
  if math.abs(observed-value)>math.max(0.0001,math.abs(value)*0.000001)then return false,"K/D float readback did not match"end
 elseif observed~=value then return false,"Counter readback did not match: "..key end
 return true
end
local function notify(text)M.status=text;require("MorpheusMouse.state").notify_info(text)end
function M.load()
 local ok,why=guard();if not ok then return false,why end
 local values,why=snapshot();if not values then return false,why end
 M.kills=values.kills;M.deaths=values.deaths;M.suicides=values.suicides;M.loaded=true
 notify("Loaded account K/D stats. Recorded ratio: "..string.format("%.4f",values.ratio))
 return true
end
local function ratio()
 -- Enhanced freemode func_24685 counts the suicide receiver twice when
 -- recomputing MPPLY_KILL_DEATH_RATIO. Preserve that source behavior.
 local denominator=M.deaths+2*M.suicides
 if denominator<=0 then return nil end
 return M.kills/denominator
end
function M.apply()
 if not M.loaded then return false,"Load Current Stats before editing"end
 local ok,why=guard();if not ok then return false,why end
 for _,key in ipairs({"kills","deaths","suicides"})do
  local value=M[key]
  if type(value)~="number"or value~=math.floor(value)or value<0 or value>1000000000 then return false,"Counters must be whole numbers from 0 to 1,000,000,000"end
 end
 local target=ratio();if not target then return false,"Deaths plus twice suicide deaths must be greater than zero"end
 if type(native.stat_set_float)~="function"then return false,"STAT_SET_FLOAT is unavailable; no changes made"end
 local previous,why=snapshot();if not previous then return false,why end
 local changed={}
 for _,key in ipairs({"deaths","suicides","kills","ratio"})do
  local value=key=="ratio"and target or M[key]
  if value~=previous[key]then
   changed[#changed+1]=key
   local ok,why=write(key,value)
   if not ok then
    local restored=true
    for i=#changed,1,-1 do local name=changed[i];local ok=write(name,previous[name]);restored=ok and restored end
    M.status=tostring(why)..(restored and "; previous values restored"or "; restoration incomplete; use Load Current Stats to inspect")
    return false,M.status
   end
  end
 end
 local final,why=snapshot()
 if not final or final.kills~=M.kills or final.deaths~=M.deaths or final.suicides~=M.suicides or math.abs(final.ratio-target)>math.max(0.0001,math.abs(target)*0.000001)then
  M.status="Final K/D readback changed: "..tostring(why or "game changed the counters; reload to inspect")
  return false,M.status
 end
 notify("K/D counters and ratio read back successfully: "..string.format("%.4f",target)..". Save writes accepted; rejoin and load stats again to check persistence.")
 return true
end
local function edit_value(key)
 if not M.loaded then return false,"Load Current Stats first"end
 native.display_onscreen_keyboard(0,"FMMC_KEY_TIP8","",tostring(M[key]),"","","",10)
 local status
 repeat require("MorpheusMouse.job_runtime").yield(0);status=native.update_onscreen_keyboard()until status~=0
 if status~=1 then return true end
 local text=type(native.get_onscreen_keyboard_result)=="function"and native.get_onscreen_keyboard_result()or invoker.call(0x8362B09B91893647).str
 local value=tonumber(text)
 if not value or value~=math.floor(value)or value<0 or value>1000000000 then return false,"Enter a whole number from 0 to 1,000,000,000"end
 M[key]=value
 return true
end
local function edit(key)
 local state=require("MorpheusMouse.state")
 local previous=state.modal_input_capture
 state.modal_input_capture=true
 M.editing=true
 local ok,result,detail=pcall(function()
  local result,detail=edit_value(key)
  -- Keep the close/accept key from reaching the menu on keyboard dismissal.
  local until_tick=util.get_tick_count()+200
  repeat require("MorpheusMouse.job_runtime").yield(0)until util.get_tick_count()>=until_tick
  return result,detail
 end)
 state.modal_input_capture=previous
 M.editing=false
 if not ok then return false,"K/D number entry failed: "..tostring(result)end
 return result,detail
end
function M.rows()
 local rows={{label="Load Current Stats",run=M.load}}
 for _,item in ipairs({{"Player Kills","kills"},{"Player Deaths","deaths"},{"Suicide Deaths","suicides"}})do
  local key=item[2]
  rows[#rows+1]={label=item[1],value=function()return M.loaded and tostring(M[key])or "Load first"end,run=function()return edit(key)end}
 end
 rows[#rows+1]={label="Calculated K/D",value=function()local value=ratio();return M.loaded and(value and string.format("%.4f",value)or "Undefined")or "Load first"end}
 rows[#rows+1]={label="Apply Account K/D Stats",run=M.apply}
 rows[#rows+1]={label="Show K/D Status",run=function()notify(M.status);return true end}
 return rows
end
return M

end

