  if not good then value="Unavailable"end
  if value~=nil then label=label..": "..tostring(value)end
  if type(row.run)=="function"then
   if M.busy then widgets.disabled_button(vec2(pos.x+padding,y),vec2(width,height),label)
   elseif widgets.button(vec2(pos.x+padding,y),vec2(width,height),label,nil,"feature:"..title..":"..row.label)and not state.background_input_blocked()then
    M.busy=true
