 local first=math.max(1,math.min(M.selection-5,#rows-visible+1))
 local header=70*scale
 theme.draw_rect(vec2(x,y),vec2(width,header),color(14,11,31,255),8)
 assets.draw_emblem(vec2(x+12*scale,y+14*scale),vec2(42*scale,42*scale),8)
 text("M O R P H E U S",x+68*scale,y+25*scale,18*scale,theme.colors.wordmark_text)
 y=y+header
 theme.draw_rect(vec2(x,y),vec2(width,30*scale),color(22,19,40,255),0)
 local title=modal and "CONFIRM ACTION"or(#M.path==0 and"MAIN MENU"or M.path[#M.path])
 text(title,x+12*scale,y+7*scale,13*scale,theme.colors.text)
 text(M.selection.." / "..#rows,x+width-12*scale,y+7*scale,13*scale,theme.colors.text_dim,true)
 y=y+30*scale
 for index=first,first+visible-1 do
  local row=rows[index]
  local selected=index==M.selection
  local cv=selected and theme.color_values.accent or theme.color_values.panel_background
  local background=color(cv[1],cv[2],cv[3],255)
  theme.draw_rect(vec2(x,y),vec2(width,row_height),background,0)
  if selected then theme.draw_rect(vec2(x,y),vec2(3*scale,row_height),theme.colors.accent,0)end
  local action=row.action
  local marker=require("MorpheusMouse.new_badge")
  local label,marked=marker.split(row.label)
  local max_label=(row.value or row.action)and 24 or 35
  if marked then max_label=math.max(8,math.floor((width-110*scale)/(14*scale*0.62)))end
  if #label>max_label then label=label:sub(1,max_label-3).."..."end
  local tint=action and(not action.wired or action.enabled==false)and theme.colors.text_disabled or theme.colors.text
  text(label,x+12*scale,y+8*scale,14*scale,tint)
  if marked then marker.draw(x+width-88*scale,y+(row_height-20*scale)/2,52*scale,20*scale,scale)end
  local checked=row.checked
  if type(checked)=="function"then local ok,result=pcall(checked);checked=ok and result==true or false end
  local value=(row.submenu or row.children)and">"or""
  if row.value then if type(row.value)=="function"then local ok,result=pcall(row.value);value=ok and tostring(result)or"Unavailable"else value=tostring(row.value)end end
  if action then
   if action.pending then value="..."
   elseif not action.wired then value="Initializing"
   elseif action.type=="toggle"then checked=action.value==true;value=""
   elseif action.type=="slider"then value=string.format("< %.2g >",tonumber(action.value)or 0)end
  end
  if #value>16 then value=value:sub(1,13).."..."end
  if checked~=nil and not(action and(action.pending or not action.wired))then
   local box=16*scale;local bx=x+width-12*scale-box;local by=y+(row_height-box)/2
   theme.draw_rect(vec2(bx,by),vec2(box,box),theme.colors.text_dim,2)
   theme.draw_rect(vec2(bx+2*scale,by+2*scale),vec2(box-4*scale,box-4*scale),background,1)
   if checked then text("X",bx+3*scale,by-1*scale,15*scale,theme.colors.text)end
  else text(value,x+width-12*scale,y+8*scale,13*scale,theme.colors.text_dim,true)end
  y=y+row_height
 end
 theme.draw_rect(vec2(x,y),vec2(width,55*scale),color(14,11,31,255),0)
 text("A Select   B Back   D-pad Navigate",x+12*scale,y+9*scale,12*scale,theme.colors.text_dim)
 text("RB + D-pad Left: Open / Close",x+12*scale,y+29*scale,12*scale,theme.colors.text_dim)
 if modal then theme.text(tostring(modal.text)):position(vec2(x,y+64*scale)):scale(14*scale):color(theme.colors.text):wrap(width):draw();M.selection=saved_selection;return end
 local help=require("MorpheusMouse.menu_help")
 local description=help.description(rows[M.selection],M.path)
 if description then
  local lines=help.lines(description,48)
  local top=y+55*scale
  theme.draw_rect(vec2(x,top),vec2(width,(16+#lines*16)*scale),color(14,11,31,255),0)
  for index,line in ipairs(lines)do text(line,x+12*scale,top+(8+(index-1)*16)*scale,12*scale,theme.colors.text_dim)end
 end
end
return M


end
