function M.rows(kind)
 local formats={}
 for _,entry in ipairs(entries)do if entry.kind==kind then
  formats[entry.format]=formats[entry.format]or{}
  local categories=formats[entry.format];categories[entry.category]=categories[entry.category]or{}
  categories[entry.category][#categories[entry.category]+1]=entry
 end end
 local function keys(t)local k={};for key in pairs(t)do k[#k+1]=key end;table.sort(k);return k end
 local rows={}
 for _,format in ipairs(keys(formats))do local groups=formats[format]
  rows[#rows+1]={label=format,children=function()
   local categories={}
   for _,category in ipairs(keys(groups))do local files=groups[category]
    categories[#categories+1]={label=category,children=function()
     local builds={}
     for _,entry in ipairs(files)do local selected=entry
      builds[#builds+1]={label=selected.name,value=unavailable[selected.path]and "Unsupported"or nil,description=unavailable[selected.path],run=function()
       if unavailable[selected.path]then return false,unavailable[selected.path]end
       local manager=require("MorpheusMouse.spawn_manager")
       if manager.busy then return false,"A spawn is already running"end
       local path=paths.game:gsub("[/\\]+$","").."\\scripts\\ClickUl\\"..selected.path:gsub("/","\\")
       if not file.exists(path)then return false,"Saved build file is missing: "..selected.name end
       return manager.spawn_import({path=path,name=selected.name,type=kind,format=selected.format})
      end}
     end
     return builds
    end}
   end
   return categories
  end}
 end
 return rows
end
return M

end

package.preload["MorpheusMouse.controller_session_controls"]=function(...)
local M={}
local function toggle(label,get,set)return{label=label,checked=get,run=function()set(not get());return true end}end
local function choice(label,values,get,set)
 return{label=label,value=function()return values()[get()]or "Unknown"end,children=function()
  local rows={};for i,name in ipairs(values())do local index=i;rows[#rows+1]={label=name,run=function()set(index);return true end}end;return rows
 end}
end
function M.repair(rows)
 local tools=require("MorpheusMouse.session_tools");local esp=require("MorpheusMouse.session_esp")
 local function option(label,key)return toggle(label,function()return esp.options[key]end,function(value)esp.set_option(key,value);if value then esp.set_enabled(true)end end)end
 local mapping={
 ['Clear Traffic']=toggle('Clear Traffic',function()return tools.traffic_active end,tools.set_clear_traffic),
 ['Player ESP']=toggle('Player ESP',esp.is_enabled,esp.set_enabled),
 ['ESP Names']=option('ESP Names','names'),['ESP Skeleton']=option('ESP Skeleton','skeleton'),['ESP Boxes']=option('ESP Boxes','boxes'),['ESP See Through Walls']=option('ESP See Through Walls','through_walls'),
 ['Distance']=choice('ESP Distance',esp.get_distance_presets,esp.get_distance_preset,esp.set_distance_preset),
 ['Name Tag Size']=choice('Name Tag Size',esp.get_name_size_presets,esp.get_name_size_preset,esp.set_name_size_preset),
 ['Name Color']=choice('Name Color',esp.get_color_presets,function()return esp.get_color_preset('name')end,function(v)esp.set_color_preset('name',v)end),
 ['Skeleton and Box']=choice('Skeleton and Box Color',esp.get_color_presets,function()return esp.get_color_preset('skeleton')end,function(v)esp.set_color_preset('skeleton',v)end),
 ['Player Magnet']=toggle('Player Magnet',function()return tools.magnet_active end,tools.set_player_magnet),
 ['Public Session Region']=choice('Public Session Region',tools.get_region_presets,tools.get_region_preset,tools.set_region_preset),
 ['JOIN PUBLIC SESSION']={label='Join Public Session',run=tools.join_public_session}
 }
 for _,entry in ipairs({{'NAT Type Spoof','MorpheusMouse.session_nat_spoof'},{'Position Spoof','MorpheusMouse.session_position_spoof'}})do
  local label,module=entry[1],require(entry[2]);mapping[label]=choice(label,module.get_presets,module.get_preset,module.set_preset)
 end
 local dev=require('MorpheusMouse.session_rockstar_dev_spoof');mapping['Spoof as R* Developer']=toggle('Spoof as R* Developer',dev.is_active,dev.set_enabled)
 local result={};local seen={}
 for _,row in ipairs(rows)do local label=row.label;local key=label:match('^([^:]+):')or label;local replacement=mapping[key];if replacement then if not seen[key]then result[#result+1]=replacement;seen[key]=true end else result[#result+1]=row end end
 result[#result+1]={label="Remove Black Screen",description="Clears a stuck loading overlay or screen fade after returning to the session. An active mission or session transition must finish first. This does not confirm a heist payout.",run=function()return require("MorpheusMouse.black_screen_recovery").run()end}
 return result
end
return M

end

package.preload["MorpheusMouse.controller_teleport"]=function(...)
local M={keep_vehicle=true,ground_waypoint=true,distance=10,saved={},loaded=false,last=nil}
local native=require("natives")
local runtime=require("MorpheusMouse.job_runtime")
local diagnostics=require("MorpheusMouse.diagnostics")
local function finite(v)return type(v)=="number"and v==v and math.abs(v)<50000 end
local function coords(v)if not v or not finite(tonumber(v.x))or not finite(tonumber(v.y))or not finite(tonumber(v.z))then return nil end return{x=tonumber(v.x)+0.0,y=tonumber(v.y)+0.0,z=tonumber(v.z)+0.0}end
local function me()local p=players.me();if not p then error("Local player unavailable")end return p end
local function entity_coords(entity)
 if type(native.get_entity_coords)=="function"then return native.get_entity_coords(entity,true)end
 return invoker.call(0x3FEF770D40960D5A,entity,true).scr_vec3
end
local function blip_coords(blip)
 if type(native.get_blip_info_id_coord)=="function"then return native.get_blip_info_id_coord(blip)end
 return invoker.call(0xFA7C7F0AADF25D09,blip).scr_vec3
end
local function current()local p=me();return coords(p.coords or entity_coords(p.ped))end
local function root()return paths.game.."\\scripts\\MorpheusMouse\\teleports.json"end
local function load()
 if M.loaded then return end
 local saved={}
 if file.exists(root())then
  local handle=file.open(root(),{append=false,create_if_not_exists=false})
  if not handle or not handle.valid then error("Saved locations could not be opened")end
  local data=json.decode(handle.json)
  if type(data)~="table"then error("Saved locations file is invalid")end
  for _,entry in ipairs(data.locations or{})do local point=coords(entry);if point and type(entry.name)=="string"then point.name=entry.name;saved[#saved+1]=point end end
 end
 M.saved=saved;M.loaded=true
end
local function persist(entries)
 local handle=file.open(root(),{append=false,create_if_not_exists=true})
 if not handle or not handle.valid then return false,"Could not save locations"end
 handle.json=json.encode({version=1,locations=entries});M.saved=entries;return true
end
local function ground(point)
 local ptr=pointer_float();local found
 local ok,reason=xpcall(function()
  native.set_focus_pos_and_vel(point.x,point.y,math.max(point.z,100.0),0.0,0.0,0.0)
  runtime.yield(250)
  for attempt=1,30 do
   native.request_collision_at_coord(point.x,point.y,point.z)
   for _,height in ipairs({1000,800,600,400,250,150,100,50,25,0,-50,point.z+50})do
    native.request_collision_at_coord(point.x,point.y,height+0.0)
    if native.get_ground_z_for_3d_coord(point.x,point.y,height+0.0,ptr,false)then found=tonumber(ptr.value);break end
   end
   if found then break end;runtime.yield(100)
  end
 end,debug.traceback)
 pcall(native.clear_focus)
 ptr:free()
 if not ok then return nil,reason end
 if not found then return nil,"Ground could not be resolved; teleport cancelled"end
 return{x=point.x,y=point.y,z=found+1}
end
function M.go(point,resolve)
 point=coords(point);if not point then return false,"Invalid coordinates"end
 if resolve then local detail;point,detail=ground(point);if not point then return false,detail end end
 local p=me();local entity=M.keep_vehicle and p.in_vehicle and p.vehicle or p.ped
 if not entity or entity==0 then return false,"Player entity unavailable"end
 local previous=current()
 local far=previous and((previous.x-point.x)^2+(previous.y-point.y)^2>10000)
 local ok,result,detail=xpcall(function()
 if far then native.set_focus_pos_and_vel(point.x,point.y,point.z,0.0,0.0,0.0);native.request_collision_at_coord(point.x,point.y,point.z);runtime.yield(250)end
 native.request_collision_at_coord(point.x,point.y,point.z)
 diagnostics.event("teleport","requested",{entity=tonumber(entity),x=point.x,y=point.y,z=point.z})
 native.set_entity_coords_no_offset(entity,point.x,point.y,point.z,true,true,true)
 runtime.yield(100)
 local function arrived()
  local actual=coords(entity_coords(entity))
  return actual and (actual.x-point.x)^2+(actual.y-point.y)^2+(actual.z-point.z)^2<100,actual
 end
 local success,actual=arrived()
 if not success then
  native.set_entity_coords(entity,point.x,point.y,point.z,false,false,false,false)
  runtime.yield(100);success,actual=arrived()
 end
 if success and far then
  local loaded=false
  for attempt=1,100 do
   native.request_collision_at_coord(point.x,point.y,point.z)
   if native.has_collision_loaded_around_entity(entity)then loaded=true;break end
   native.set_entity_coords_no_offset(entity,point.x,point.y,point.z,true,true,true)
   runtime.yield(50)
  end
  if not loaded then
   native.set_entity_coords_no_offset(entity,previous.x+0.0,previous.y+0.0,previous.z+0.0,true,true,true)
   pcall(native.clear_focus);return false,"Destination collision did not load; returned to previous position"
  end
 end
 if far then pcall(native.clear_focus)end
 diagnostics.event("teleport",success and"confirmed"or"not_moved",{entity=tonumber(entity),actual_x=actual and actual.x,actual_y=actual and actual.y,actual_z=actual and actual.z})
 if not success then return false,"The game did not move the selected entity; diagnostic recorded"end
 M.last=previous;require("MorpheusMouse.state").notify_success("Teleported")return true
 end,debug.traceback)
 if far then pcall(native.clear_focus)end
 if not ok then
  if previous then pcall(native.set_entity_coords_no_offset,entity,previous.x+0.0,previous.y+0.0,previous.z+0.0,true,true,true)end
  diagnostics.error("teleport",result);return false,"Teleport stopped; diagnostic recorded"
 end
 if detail==nil then return result end
 return result,detail
end
function M.blip_point(blip)return blip_coords(blip)end
