function M.blip_label(sprite,index,point)
 local name=blip_names[sprite]or("Map Marker "..sprite)
 local area
 if point then local ok,zone=pcall(function()return invoker.call(0xCD90657D4C30E1CA,point.x+0.0,point.y+0.0,point.z+0.0).str end);if ok then area=zone_names[zone]end end
 return name..(area and(" - "..area)or"").." / "..index
end
function M.rows()
 return{
 submenu("Settings",function()return{toggle("Keep Current Vehicle",function()return M.keep_vehicle end,function(v)M.keep_vehicle=v end),toggle("Resolve Waypoint Ground",function()return M.ground_waypoint end,function(v)M.ground_waypoint=v end)}end),
 submenu("Save/Load",function()
  load();local rows={keyboard("Save Current Location",function()return"My Location"end,function(name)
   name=tostring(name):sub(1,60);if name==""then return false,"Name is empty"end
   local point=current();if not point then return false,"Position unavailable"end;point.name=name
   local entries={}for _,entry in ipairs(M.saved)do entries[#entries+1]=entry end;entries[#entries+1]=point;return persist(entries)
  end)}
  for index,entry in ipairs(M.saved)do rows[#rows+1]=submenu(entry.name,function()return{button("Teleport",function()return M.go(entry,false)end),button("Delete Saved Location",function()local entries={}for i,v in ipairs(M.saved)do if v~=entry then entries[#entries+1]=v end end return persist(entries)end)}end)end
  return rows
 end),
 keyboard("Input",function()local p=current();return p and string.format("%.2f, %.2f, %.2f",p.x,p.y,p.z)or""end,M.parse),
 submenu("Directional",function()
  local rows={{label="Distance",value=function()return M.distance.." m"end,adjust=function(d)M.distance=math.max(1,math.min(1000,M.distance+d));return true end}}
  for _,direction in ipairs({"Forward","Backward","Left","Right","Up","Down"})do rows[#rows+1]=button(direction,function()
   local p=me();local point=current();if not point then return false,"Position unavailable"end
   local heading=math.rad(tonumber(p.heading)or 0);local distance=M.distance
   if direction=="Up"then point.z=point.z+distance elseif direction=="Down"then point.z=point.z-distance
   else if direction=="Backward"then heading=heading+math.pi elseif direction=="Left"then heading=heading+math.pi/2 elseif direction=="Right"then heading=heading-math.pi/2 end
    point.x=point.x-math.sin(heading)*distance;point.y=point.y+math.cos(heading)*distance
   end
   return M.go(point,false)
  end)end return rows
 end),
 submenu("Locations & Facilities",function()local rows={}for _,location in ipairs(locations)do rows[#rows+1]=button(location[1],function()return M.go({x=location[2],y=location[3],z=location[4]},false)end)end return rows end),
 submenu("Navigation & Transport",function()
  local rows={button("Waypoint",M.waypoint),button("Return to Previous Position",function()if not M.last then return false,"No previous position"end return M.go(M.last,false)end),submenu("Players",function()
   local rows={}for id=0,31 do local p=players.get(id);if p and p.connected~=false and p.exists~=false and p.id~=me().id then
    local rid=p.rockstar_id;rows[#rows+1]=button(p.name,function()local current=players.get(id);if not current or current.connected==false or current.rockstar_id~=rid then return false,"Selected player changed"end return require("MorpheusMouse.player_actions").teleport_to(current)end)
   end end return rows
  end)}return rows
 end),
 submenu("Blips",function()
  local rows,seen={},{}for sprite=1,1000 do
   local blip=native.get_first_blip_info_id(sprite);local count=0
   while blip and blip~=0 and native.does_blip_exist(blip)and not seen[blip]and count<128 do
    seen[blip]=true;count=count+1;local current_blip=blip;local point=coords(blip_coords(blip))
    if point then rows[#rows+1]=button(M.blip_label(sprite,count,point),function()if not native.does_blip_exist(current_blip)then return false,"Blip no longer exists"end return M.go(blip_coords(current_blip),M.ground_waypoint)end)end
    if #rows>=256 then return rows end;blip=native.get_next_blip_info_id(sprite)
   end
   if sprite%50==0 then runtime.yield(0)end
  end return rows
 end)}
end
return M

end

