 for i,entry in ipairs(entries)do local handle=script.tunables(entry[1]);local success=pcall(function()handle.int32=entry[2]end)
  if not success or handle.int32~=entry[2]then for _,saved in ipairs(before)do pcall(function()script.tunables(saved[1]).int32=saved[2]end)end return false,"Tunable change failed; restoration attempted"end
 end
 for _,entry in ipairs(before)do if original[entry[1]]==nil then original[entry[1]]=entry[2]end end
 notify("Settings applied and read back. Reopen the board to check the displayed payout.")
 return true
end
function M.cleanup()for name,value in pairs(original)do pcall(function()script.tunables(name).int32=value end)end original={}end
local function planning(kind,index,value)
 local ok,reason=guard();if not ok then return false,reason end
 local name=kind=="auto"and"tuner_planning"or"vehrob_planning"
 if not script.running(name)then return false,"Enter the property and open its planning board first"end
 script.locals(name,index).int32=value
 if script.locals(name,index).int32~=value then return false,"Planning control rejected the change"end
 notify("Planning board update requested")return true
end
local function entrance(sprite)
 local blip=native.get_first_blip_info_id(sprite);if not native.does_blip_exist(blip)then return false,"Property entrance blip is unavailable"end
 local api=require("MorpheusMouse.controller_teleport");return api.go(api.blip_point(blip),false)
end
local function inside(kind)
 local name=kind=="auto"and"tuner_planning"or"vehrob_planning"
 if not script.running(name)then return false,"Enter the property normally before teleporting to its board"end
 local point=kind=="auto"and{x=-1349.024,y=138.381,z=-95.121}or{x=1074.720,y=-2275.502,z=-48.999}
 return require("MorpheusMouse.controller_teleport").go(point,false)
end
local function select_row(label,options,get,set)return{label=label,value=function()return options[get()][1]end,children=function()local rows={}for i,entry in ipairs(options)do local index=i;rows[#rows+1]={label=entry[1],run=function()set(index);return true end}end return rows end}end
function M.auto_rows(reset)return{
 {label="Payout Amount",fast_adjust=true,value=function()return tostring(M.payout)end,adjust=function(direction)M.payout=math.max(0,math.min(2200000,M.payout+direction*10000));return true end},
 {label="Max Payout",run=function()M.payout=2200000;return true end},
 {label="Apply Payout",run=function()local entries={}for i=0,7 do entries[#entries+1]={"TUNER_ROBBERY_LEADER_CASH_REWARD"..i,M.payout}end return tunables(entries)end},
 {label="Reset Preps",run=reset},
 {label="Redraw Board",run=function()return planning("auto",418,2)end},
 {label="Kill Cooldown",run=function()return tunables({{"TUNER_ROBBERY_COOLDOWN",0}})end},
 {label="Teleport to Entrance",run=function()return entrance(779)end},
 {label="Teleport to Contract Board",run=function()return inside("auto")end},
 {label="Restore Session Settings",run=function()M.cleanup();notify("Session settings restored");return true end}}
end
function M.salvage_rows()
 local rows={}
 for i,config in ipairs(slots)do local slot=i
  rows[#rows+1]={label="Slot "..slot,children=function()return{
   select_row("Robbery",robberies,function()return config.robbery end,function(v)config.robbery=v end),
   select_row("Vehicle",vehicles,function()return config.vehicle end,function(v)config.vehicle=v end),
   {label="Claimable",checked=function()return config.keep end,run=function()config.keep=not config.keep;return true end},
   {label="Apply Slot "..slot,run=function()return tunables({{robbery_hash[slot],robberies[config.robbery][2]},{vehicle_hash[slot],vehicles[config.vehicle][2]},{keep_hash[slot],config.keep and 1 or 0}})end}}
  end}
 end
 rows[#rows+1]={label="Kill Cooldown",run=function()return tunables({{"SALV23_VEH_ROB_COOLDOWN_TIME",0},{"SALV23_CFR_COOLDOWN_TIME",0}})end}
 rows[#rows+1]={label="Reload Board",run=function()return planning("salvage",547,2)end}
 rows[#rows+1]={label="Force Start Planning Board",run=function()if not script.running("vehrob_planning")then return false,"Enter the Salvage Yard first"end local phase=script.locals("vehrob_planning",440).int32;if phase~=0 then return false,"Planning board interaction is already active"end return planning("salvage",440,1)end}
 rows[#rows+1]={label="Teleport to Entrance",run=function()return entrance(867)end}
 rows[#rows+1]={label="Teleport Inside",run=function()return inside("salvage")end}
 rows[#rows+1]={label="Restore Session Settings",run=function()M.cleanup();notify("Session settings restored");return true end}
 return rows
end
return M

end

