 if control_cache.index and control_cache.tick and now>=control_cache.tick and now-control_cache.tick<5000 then return control_cache.index end
 local tree=menu.iter()
 if type(tree)~="table"then error("The documented Lexis menu tree is unavailable",0)end
 local index={}
 local function visit(nodes,parent)
  for _,node in ipairs(nodes or{})do
   local path=parent==""and tostring(node.name or"")or(parent.." > "..tostring(node.name or""))
   if node.handle then local key=canonical(path);if index[key]~=nil then index[key]=false else index[key]=node.handle end end
   if type(node.options)=="table"then visit(node.options,path)end
  end
 end
 visit(tree,"")
 control_cache={tick=now,index=index}
