end
function a.refresh_control_snapshot()
 control_cache={tick=nil,index=nil}
 return control_index()
end
function a.resolve_control(path)
 local key=canonical(path)
 if type(menu.iter)=="function"then
  local ok,index=pcall(control_index)
  if ok then
   local handle=index[key]
   if handle==false then return nil,"Ambiguous exact protection path: "..path end
   if handle~=nil then return handle,"menu.iter exact path"end
  end
 end
 -- A snapshot may omit controls loaded later. Always try the documented direct lookup.
 if type(menu.find)=="function"then
  local ok,handle=pcall(menu.find,path)
  if ok and handle~=nil and handle~=false then return handle,"menu.find exact path"end
 end
 return nil,"Exact protection path unavailable: "..path
end
