  local path=canonical(entry.path)
  if path=="network > protections" or path:sub(1,24)=="network > protections > " then
   rows[#rows+1]=entry.path.." | "..tostring(entry.option_type).." | "..tostring(entry.value_type).." | "..tostring(entry.option_toggle_type)
  end
 end
 local path=paths.game.."\\scripts\\MorpheusMouse\\Diagnostics\\lexis_protection_controls.txt"
