  local rows=original_controls(category);local seen={};for _,row in ipairs(rows)do seen[row.label]=true end
  for _,row in ipairs(require("MorpheusMouse.controller_apartment_heists").rows())do if not seen[row.label]then rows[#rows+1]=row;seen[row.label]=true end end
  for _,row in ipairs(require("MorpheusMouse.controller_extra_heists").rows())do if not seen[row.label]then rows[#rows+1]=row;seen[row.label]=true end end
  if not seen["Apartment Setups"]then rows[#rows+1]=submenu("Apartment Setups",function()return{{label="Script Host Required",value="Yes"},button("Instant Finish Active Setup",function()local ok,reason=require("MorpheusMouse.heist_suite").instant_finish("apartment_setup");if ok then state.notify_info(reason)end return ok,reason end)}end)end
  return rows
 end
 return original_controls(category)
end
