return M

end

package.preload["MorpheusMouse.menu_help"]=function(...)
local M={}
local notes={
 ['player magnet']='Tries to attract players through Lexis matchmaking. Enable before hosting a new public session; it does not teleport players.',
 ['nat type spoof']='Changes the NAT type advertised by the game. It does not change your router or repair your connection.',
 ['position spoof']='Changes the position information advertised to other players. It does not move your character.',
 ['spoof as r developer']='Attempts to advertise developer status. This does not grant real Rockstar permissions.',
 ['public session region']='Chooses the matchmaking region used by Join Public Session. It does not move the current session.',
 ['player esp']='Shows selected player overlays on your screen. Players must be streamed into your game to appear.',
 ['esp see through walls']='Keeps ESP overlays visible when players are behind obstacles. This only affects your screen.',
 ['esp distance']='Limits how far away ESP is drawn. Players outside the game streaming range cannot be drawn.',
 ['esp skeleton']='Draws lines over streamed player body joints. Enabling this also enables Player ESP.',
 ['esp boxes']='Draws a box around streamed players. Enabling this also enables Player ESP.',
 ['clear traffic']='Suppresses nearby ambient traffic. Player and mission vehicles are excluded from cleanup.',
 ['arm 10m cmm bonus']='Arms Criminal Mastermind progress stats. Hard difficulty is required; this is not a confirmed $10M payment.',
 ['instant finish']='Requests completion of the active mission. Script host and the correct mission are required. Confirm the result and payout in game.',
 ['instant finish active setup']='Attempts to finish the current apartment setup. Script host is required; this test has not been confirmed to pass the setup.',
 ['complete all preps']='Applies preparation progress for this heist or contract. Reopen its planning board to check the result before launching.',
 ['solo launch']='Attempts to bypass lobby player-count checks. Some jobs still end when crew members are missing; success is not guaranteed.',
 ['host cut']='Sets the host payout percentage. This field alone does not apply the cut; use Apply Cut after editing.',
 ['player 2 cut']='Sets Player 2 payout percentage. Apply the cuts in the active lobby and verify the displayed result.',
 ['player 3 cut']='Sets Player 3 payout percentage. Apply the cuts in the active lobby and verify the displayed result.',
 ['player 4 cut']='Sets Player 4 payout percentage. Apply the cuts in the active lobby and verify the displayed result.',
 ['cut percentage']='Edits one crew payout percentage. Tap left/right for 1%; hold for faster changes. Use Apply Cut to apply it.',
 ['apply cut']='Writes the selected payout cuts to the active heist lobby. A successful write does not confirm the final payout.',
 ['vault target']='Selects the intended Casino vault loot. Apply preparations, then reopen the board to verify the target.',
 ['approach']='Selects the Casino approach used when applying preparations. Verify the planning board before launching.',
 ['semi god mode']='Attempts to protect the selected player from damage through the available remote action. It is not full invincibility.',
 ['off radar']='Attempts to hide the selected player radar blip temporarily. Remote effects depend on the current game and receiver.',
 ['enter interior']='Attempts to enter an interior associated with the selected player. It can fail if the interior is unavailable.',
 ['join ceo mc']='Attempts to join the selected player organization. Their organization and session must allow the join.',
 ['money drop']='Creates a cash pickup near the selected player. Visibility on your screen does not confirm they receive money.',
 ['drop once']='Requests one cash pickup. Remote money credit is unresolved; check the recipient rather than the local pickup.',
 ['drops']='Native Lexis collectible controls and an independent test. Remote money or RP delivery is not confirmed.',
 ['inspect lexis drops']='Records which native Drops controls the Lua API exposes. This inspection does not award collectibles or money.',
 ['refresh drop controls']='Checks again for usable native Lexis Drops controls. This does not repair or send a reward.',
 ['independent collectible test']='Sends a direct collectible request without opening Lexis Drops. Ask the recipient to check their collectible count.',
 ['send treasure chest once test']='Sends one Treasure Chest request for the selected index. Already collected chests may give no reward. Ask the recipient to check their reward.',
 ['chest']='Selects Treasure Chest 1 or 2 for the test request. This does not reset collected-chest progress.',
 ['force start planning board']='Starts the Salvage Yard planning-board interaction. It does not directly launch a robbery.',
 ['restore session settings']='Restores the original tunable values saved before applying these Auto Shop or Salvage Yard changes.',
 ['claimable']='Requests claimable status for this Salvage Yard slot. Check vehicle eligibility and the claim option at the yard.',
 ['kill cooldown']='Attempts to remove the relevant activity cooldown. Server rules or session state may still prevent a new activity.',
 ['redraw board']='Requests a refresh of the active planning board after changing its preparation settings.',
 ['reload board']='Requests a refresh of the active planning board. Reopen it to verify the displayed result.',
 ['reset preps']='Changes preparation progress back to the reset state. Refresh the board to see the result.',
 ['apply payout']='Writes the selected Auto Shop payout tuning. The final reward is not confirmed until the game pays it.',
 ['payout amount']='Sets the requested Auto Shop payout value. Use Apply Payout; the game may limit the actual reward.',
 ['god mode']='Protects your character through the enabled local feature. It does not protect teammates.',
 ['never wanted']='Keeps your local wanted level cleared while enabled. This is different from hiding on the radar.',
 ['no ragdoll']='Stops your character from entering the normal ragdoll state while enabled.',
 ['teleport to waypoint']='Moves you to your map waypoint. Ground and collision loading can affect where you arrive.',
 ['bodyguard type']='Chooses the model used for spawned bodyguards. Existing bodyguards are not necessarily changed.',
 ['blips']='Lists map markers as teleport targets. Duplicate names can represent separate markers of the same type.'
}
local basic={['god mode']=true,['never wanted']=true,['no ragdoll']=true,['back']=true,['name color']=true,['name tag size']=true,['skeleton and box color']=true,['hard mode']=true,['invisible']=true,['health']=true,['armor']=true,['teleport to']=true,['teleport here']=true}
local function key(label)return tostring(label or ''):gsub(':.*$',''):lower():gsub('[^a-z0-9]+',' '):gsub('^%s+',''):gsub('%s+$','')end
function M.description(row,path)
 if not row then return nil end
 local label=key(row.label);if basic[label]then return nil end
 if notes[label]then return notes[label]end
 if label:match('^apply slot %d')then return 'Applies robbery, vehicle and claimable choices to this Salvage Yard slot. Reopen the board to check the result.'end
 if row.description then return tostring(row.description)end
 local action=row.action
 if action and type(action.tooltip)=='string' and action.tooltip~=''then return action.tooltip end
 return nil
end
function M.lines(text,width)
 local lines={};local current='';width=width or 48
 for word in tostring(text or ''):gmatch('%S+')do
  if current~='' and #current+#word+1>width then lines[#lines+1]=current;current=word else current=current=='' and word or(current..' '..word)end
 end
 if current~=''then lines[#lines+1]=current end
 return lines
end
return M

