}
local function safe(fn,...)
 if type(fn)~='function'then return nil end
 local ok,value=pcall(fn,...)
 if ok then return value end
end
local function exists(entity)
 return type(entity)=='number'and entity~=0 and safe(native.does_entity_exist,entity)==true
end
local function identity(player)
 return tostring(player.id)..':'..tostring(player.rockstar_id)..':'..tostring(player.name)
end
local function same_player(player,record)
 if not player or tonumber(player.id)~=tonumber(record.id)then return false end
 local a,b=tonumber(player.rockstar_id),tonumber(record.rid)
 if a and a>0 and b and b>0 then return a==b end
 return tostring(player.name)==tostring(record.name)
end
local function trace(event,record,reason)
 print('SPACEx prop test | '..event..' | model='..tostring(record and record.preset and record.preset.model)..' | '..tostring(reason or''))
end
local function current(record)
 local player=safe(players.get,record.id)
 if not player or player.connected==false or player.exists==false or not same_player(player,record)then return nil end
 if tonumber(player.ped)~=record.ped or not exists(record.ped)or safe(native.is_entity_dead,record.ped,false)then return nil end
 return player
end
local function target(selected)
 if M.stopped then return nil,'Attachment tests are unloaded'end
 if not selected or selected.id==nil then return nil,'Select an online player first'end
 local player=safe(players.get,selected.id)
 local me=safe(players.me)
 if not player or player.connected==false or player.exists==false or identity(player)~=identity(selected)then return nil,'Selected player changed or left'end
 if not me or tonumber(player.id)==tonumber(me.id)then return nil,'Select another online player'end
 local ped=tonumber(player.ped)
 if not exists(ped)or safe(native.is_entity_dead,ped,false)then return nil,'Selected player is not streamed or is respawning'end
 return {id=player.id,identity=identity(player),rid=player.rockstar_id,name=player.name,ped=ped},player
end
local function wait_for(ready,request,validate)
 for _=1,120 do
  if M.stopped or not validate()then return false end
  if ready()then return true end
  request();jobs.yield(25)
 end
 return false
end
local function entity_model(entity)
 if type(native.get_entity_model)=='function'then return safe(native.get_entity_model,entity)end
 local ok,value=pcall(function()return invoker.call(0x9F47B058362C84B5,entity).int end)
 return ok and value or nil
end
local function own_object(record)
 if not exists(record.handle)then return false,'entity disappeared outside test cleanup'end
 local model=entity_model(record.handle)
 if model==nil then return nil,'model temporarily unavailable'end
 if (model & 0xffffffff)~=(record.model & 0xffffffff)then return false,'entity handle reused by another model'end
 if record.networked~=false then
  local id=tonumber(safe(native.network_get_network_id_from_entity,record.handle))
  if id and id>0 then
   if record.net_id and record.net_id>0 and id~=record.net_id then return false,'entity network identity changed'end
   record.net_id=id
  end
 end
 return true
end
local function release_prop_model(record)
 if record.model_released then return end
 record.model_released=true
 if record.handle then safe(context.release_entity,record.handle,'player_attachment_test')end
 for _,other in ipairs(M.props)do
  if other~=record and other.model==record.model and not other.model_released then return end
 end
 safe(native.set_model_as_no_longer_needed,record.model)
end
local function delete_prop(record)
 local owned,why=own_object(record)
 if owned==false then release_prop_model(record);trace('tracking ended',record,why);return true end
 if owned==nil then return false end
 if record.networked~=false then
  safe(native.network_request_control_of_entity,record.handle)
  if safe(native.network_has_control_of_entity,record.handle)~=true then return false end
 end
 safe(native.detach_entity,record.handle,true,true)
 local ptr=safe(pointer_int)
 if not ptr then return false end
 ptr.value=record.handle
 local ok=pcall(native.delete_entity,ptr)
 pcall(function()ptr:free()end)
 local deleted=ok and not exists(record.handle)
 if deleted then release_prop_model(record);trace('removed by script',record,record.remove_reason or'explicit cleanup')end
 return deleted
end
function M.detach_self(force)
 local record=M.self_attachment
 local me=safe(players.me)
 local ped=me and tonumber(me.ped)
 if not record and not force then return true,'You are detached'end
 if not exists(ped)then
  M.self_attachment=nil;M.status='Your character is unavailable'
  return false,M.status
 end
 local owned=record and record.ped==ped and record or nil
 if not owned and not force then M.self_attachment=nil;return true,'Previous character attachment cleared'end
 -- Manual detach also recovers attachments whose bookkeeping was lost.
 -- Never gate DETACH_ENTITY on the potentially stale parent comparison.
 local ok,why=pcall(native.detach_entity,ped,true,true)
 if not ok then M.status='Detach failed: '..tostring(why);return false,M.status end
 if owned and owned.emote then
  safe(native.stop_anim_task,ped,owned.emote.dict,owned.emote.name,2.0)
  safe(native.remove_anim_dict,owned.emote.dict)
 end
 if force or owned then safe(native.clear_ped_secondary_task,ped)end
 safe(native.process_entity_attachments,ped)
 if owned then safe(native.set_entity_collision,ped,not owned.collision_disabled,true)
 elseif force then safe(native.set_entity_collision,ped,true,true)end
 if safe(native.is_entity_attached,ped)==true then
  if owned then owned.detaching=true end
  M.status='Detach pending; checking again'
  return false,M.status
 end
 M.self_attachment=nil
 M.status='Detached from player'
 return true,M.status
end
function M.remove_props()
 local pending={}
 for _,record in ipairs(M.props)do record.remove=true;record.remove_reason='user cleanup or script unload';if not delete_prop(record)then pending[#pending+1]=record end end
 M.props=pending
 M.status=#pending==0 and 'Props removed'or 'Waiting for control to remove props'
 return #pending==0,M.status
end
function M.cleanup(force)
 local detached,message=M.detach_self(force==true)
 local removed,why=M.remove_props()
 if not detached then M.status=message;return false,message end
 return removed,why
end
local function attach_prop(prop)
 local preset=prop.preset
 local bone=native.get_ped_bone_index(prop.target.ped,preset.bone)
 native.attach_entity_to_entity(prop.handle,prop.target.ped,bone,preset.x,preset.y,preset.z,preset.rx or 0.0,preset.ry or 0.0,preset.rz or 0.0,false,false,false,false,2,true,false)
end
function M.tick()
 if M.stopped then return false end
 local record=M.self_attachment
 if record then
  local me=safe(players.me)
  local player=current(record.target)
  if record.detaching or not me or tonumber(me.ped)~=record.ped or not exists(record.ped)or safe(native.is_entity_dead,record.ped,false)or not player or not exists(record.parent)
   or(record.vehicle and tonumber(player.vehicle)~=record.parent)
   or safe(native.is_entity_attached_to_entity,record.ped,record.parent)~=true then M.detach_self()end
 end
 for index=#M.props,1,-1 do
  local prop=M.props[index]
  local owned,ownership_reason=own_object(prop)
  if owned==false then
   M.status='Prop lost: '..ownership_reason;trace('lost without deletion',prop,ownership_reason);release_prop_model(prop);table.remove(M.props,index)
  elseif owned==nil then
   M.status='Waiting for prop entity data'
  elseif prop.remove then
   if delete_prop(prop)then table.remove(M.props,index)end
  elseif not current(prop.target)then
   local fresh=safe(players.get,prop.target.id)
   local replaced=fresh and not same_player(fresh,prop.target)
   local dead=exists(prop.target.ped)and safe(native.is_entity_dead,prop.target.ped,false)==true
   prop.missing_ticks=(prop.missing_ticks or 0)+1
   local left=not fresh or fresh.connected==false
   if replaced or dead or(left and prop.missing_ticks>=12)then
    prop.remove=true
    prop.remove_reason=replaced and'player slot changed'or(dead and'target died'or'target left session')
    M.status='Removing prop: '..prop.remove_reason
    if delete_prop(prop)then table.remove(M.props,index)end
   elseif fresh and same_player(fresh,prop.target)and tonumber(fresh.ped)and tonumber(fresh.ped)~=0 and exists(tonumber(fresh.ped))then
    -- Streaming can replace a ped handle while the same player remains connected.
    prop.target.ped=tonumber(fresh.ped);prop.retried=false;prop.settle_ticks=0
    if safe(native.network_has_control_of_entity,prop.handle)==true or prop.networked==false then pcall(attach_prop,prop)end
   end
  else
   prop.missing_ticks=0
   prop.settle_ticks=(prop.settle_ticks or 0)+1
   if prop.settle_ticks>=4 then
    if safe(native.is_entity_attached_to_entity,prop.handle,prop.target.ped)==true then
     if not prop.verified then M.status='Prop attached: '..prop.preset.label;trace('attachment confirmed',prop,prop.networked and'networked'or'local preview')end
     prop.verified=true
    elseif not prop.retried then
     prop.retried=true;prop.settle_ticks=0
     local ok=pcall(attach_prop,prop)
     if not ok then M.status='Prop attachment retry failed; use Remove Test Props to clean up'end
    elseif not prop.sync_notice then
     prop.sync_notice=true
     M.status='Attachment sync unconfirmed; prop kept until cleanup'
    end
   end
  end
 end
 if not M.self_attachment and #M.props==0 then M.worker=nil;return false end
 return true
end
local function monitor()
 if M.worker and threads.is_active(M.worker)then return true end
 M.worker=threads.start('selected_player_attachment_test',M.tick,{interval_ms=250,on_error=function()M.cleanup();M.worker=nil end})
 return M.worker~=nil
end
function M.attach_self(selected,emote_index,position_index,to_vehicle,custom_emote)
 local record,player=target(selected)
 if not record then return false,player end
 local me=safe(players.me)
 local ped=me and tonumber(me.ped)
 if not exists(ped)or safe(native.is_entity_dead,ped,false)then return false,'Your character is unavailable'end
 if safe(native.is_ped_in_any_vehicle,ped,false)then return false,'Exit your vehicle first'end
 if safe(native.is_entity_attached,ped)==true and not M.self_attachment then return false,'Detach your character from its existing attachment first'end
 local parent=to_vehicle and tonumber(player.vehicle)or record.ped
 if not exists(parent)then return false,'Selected player has no streamed vehicle'end
 local emote=custom_emote or emotes[emote_index]or emotes[1]
 local position=positions[position_index]or positions[1]
 M.detach_self()
 local function valid()
  local mine=safe(players.me)
  return current(record)~=nil and mine and tonumber(mine.ped)==ped and exists(ped)and safe(native.is_entity_dead,ped,false)~=true and safe(native.is_ped_in_any_vehicle,ped,false)~=true and(not to_vehicle or tonumber((current(record)or{}).vehicle)==parent)
 end
 if not wait_for(function()return safe(native.has_anim_dict_loaded,emote.dict)==true end,function()native.request_anim_dict(emote.dict)end,valid)then
  safe(native.remove_anim_dict,emote.dict);return false,'Emote could not load or player changed'
 end
 if not valid()then safe(native.remove_anim_dict,emote.dict);return false,'Selected player changed'end
 local collision_disabled=safe(native.get_entity_collision_disabled,ped)==true
 M.self_attachment={target=record,ped=ped,parent=parent,vehicle=to_vehicle==true,emote=emote,collision_disabled=collision_disabled}
 local ok,why=pcall(function()
  native.set_entity_collision(ped,false,true)
  native.attach_entity_to_entity(ped,parent,0,position.x,position.y,to_vehicle and position.z+1.2 or position.z,0.0,0.0,position.rz,true,false,false,not to_vehicle,2,true,false)
  native.task_play_anim(ped,emote.dict,emote.name,4.0,-4.0,-1,emote.flags or 49,0.0,false,0,false)
 end)
 if not ok or safe(native.is_entity_attached_to_entity,ped,parent)~=true then M.detach_self();return false,'Attachment failed: '..tostring(why or 'game rejected attachment')end
 if not monitor()then M.detach_self();return false,'Attachment cleanup monitor could not start'end
 M.status='Attached with '..emote.label
 return true,M.status
end
function M.add_prop(selected,prop_index,custom_preset)
 if #M.props>=3 then return false,'Remove existing props first (limit: 3)'end
 local record,player=target(selected)
 if not record then return false,player end
 local preset=custom_preset or prop_types[prop_index]or prop_types[1]
 local hash=native.get_hash_key(preset.model)
 if not native.is_model_valid(hash)or not native.is_model_in_cdimage(hash)then return false,'Prop is unavailable on this game build'end
 if not wait_for(function()return native.has_model_loaded(hash)end,function()native.request_model(hash)end,function()return current(record)~=nil end)then
  release_prop_model({model=hash});return false,'Prop could not load or player changed'
 end
 local fresh=current(record)
 if not fresh or M.stopped then release_prop_model({model=hash});return false,'Selected player changed'end
 local coords=fresh.coords
 local networked=preset.networked~=false
 local handle=safe(native.create_object_no_offset,hash,coords.x,coords.y,coords.z,networked,true,false)
 if not exists(handle)then release_prop_model({model=hash});return false,'Prop could not be created'end
 local net_id=networked and tonumber(safe(native.network_get_network_id_from_entity,handle))or nil
 if net_id and net_id<=0 then net_id=nil end
 local prop={handle=handle,model=hash,net_id=net_id,target=record,preset=preset,settle_ticks=0,networked=networked}
 M.props[#M.props+1]=prop
 safe(context.claim_entity,handle,'player_attachment_test',net_id or 0)
 local ok,why=pcall(function()
  native.set_entity_as_mission_entity(handle,true,true)
  if net_id and net_id~=0 then native.set_network_id_can_migrate(net_id,false)end
  native.set_entity_collision(handle,false,false)
  attach_prop(prop)
 end)
 trace('created',prop,networked and'networked; model retained'or'local preview; model retained')
 if not ok then
  prop.remove=true;delete_prop(prop);monitor();return false,'Prop attachment failed: '..tostring(why or 'game rejected attachment')
 end
 if not monitor()then prop.remove=true;delete_prop(prop);return false,'Prop cleanup monitor could not start'end
 M.status=preset.label..' attached (checking sync)'
 return true,M.status
end
function M.shutdown()
 M.stopped=true
 if M.worker then threads.stop(M.worker,'attachment_test_unload');M.worker=nil end
 M.cleanup()
end
function M.draw(pos,width,selected,submit)
 selected={id=selected.id,name=selected.name,rockstar_id=selected.rockstar_id}
 local widgets=require('MorpheusMouse.widgets')
 local theme=require('MorpheusMouse.theme')
 local height=theme.control_height and theme.control_height(28,22)or 28
 local gap=6
 local y=pos.y
 widgets.section(vec2(pos.x,y),'PLAYER ATTACHMENT TESTS');y=y+26
 M.emote_index=M.emote_index or 1;M.position_index=M.position_index or 1;M.prop_index=M.prop_index or 1
 local emote_labels,position_labels,prop_labels={},{},{}
 for i,preset in ipairs(emotes)do emote_labels[i]=preset.label end
 for i,preset in ipairs(positions)do position_labels[i]=preset.label end
 for i,preset in ipairs(prop_types)do prop_labels[i]=preset.label end
 local used
 M.emote_index,used=widgets.dropdown(vec2(pos.x,y),width,'attachment_test_emote','Your emote',emote_labels,M.emote_index);y=y+used+gap
 M.position_index,used=widgets.dropdown(vec2(pos.x,y),width,'attachment_test_position','Attach position',position_labels,M.position_index);y=y+used+gap
 if widgets.button(vec2(pos.x,y),vec2(width,height),'ATTACH ME TO PLAYER + EMOTE')then
  local e,p=M.emote_index,M.position_index;submit(function()return M.attach_self(selected,e,p,false)end)
 end;y=y+height+gap
 if widgets.button(vec2(pos.x,y),vec2(width,height),'ATTACH ME TO THEIR VEHICLE + EMOTE')then
  local e,p=M.emote_index,M.position_index;submit(function()return M.attach_self(selected,e,p,true)end)
 end;y=y+height+gap
 if widgets.button(vec2(pos.x,y),vec2(width,height),'DETACH ME')then submit(function()return M.detach_self(true)end)end;y=y+height+gap
 M.prop_index,used=widgets.dropdown(vec2(pos.x,y),width,'attachment_test_prop','Prop attachment',prop_labels,M.prop_index);y=y+used+gap
 if widgets.button(vec2(pos.x,y),vec2(width,height),'ATTACH PROP TO SELECTED PLAYER')then
  local prop=M.prop_index;submit(function()return M.add_prop(selected,prop)end)
 end;y=y+height+gap
 if widgets.button(vec2(pos.x,y),vec2(width,height),'DETACH ME + REMOVE TEST PROPS')then submit(function()return M.cleanup(true)end)end;y=y+height+gap
 widgets.row_label(vec2(pos.x,y),M.status,width,nil,true,theme.colors.text_dim)
 return y+height+12
end
return M

end
