package.preload["MorpheusMouse.extras_preset_tests"]=function(...)
local M={query='',choice=1,status='Choose a preset',props={}}
local data=require('MorpheusMouse.extras_preset_catalog')
local native=require('natives')
local threads=require('MorpheusMouse.runtime_threads')
local function safe(fn,...)if type(fn)=='function'then local ok,v=pcall(fn,...);if ok then return v end end end
local function model_of(handle)
 if type(native.get_entity_model)=='function'then return safe(native.get_entity_model,handle)end
 local ok,v=pcall(function()return invoker.call(0x9F47B058362C84B5,handle).int end)
 if ok and v then return math.floor(v)%4294967296 end
end
local function delete_owned(p)
 if safe(native.does_entity_exist,p.handle)==true and model_of(p.handle)==p.model then
  safe(native.detach_entity,p.handle,true,true)
  local ptr=safe(pointer_int)
  if ptr then ptr.value=p.handle;safe(native.delete_entity,ptr);pcall(function()ptr:free()end)end
 end
end
function M.cleanup()
 if M.worker then threads.stop(M.worker,'preset_cleanup');M.worker=nil end
 for _,p in ipairs(M.props)do
  delete_owned(p)
  safe(native.set_model_as_no_longer_needed,p.model)
 end
 M.props={}
 for _,p in ipairs(M.pending or{})do safe(native.set_model_as_no_longer_needed,p.model)end
 M.pending=nil
end
function M.play(selected,entry,attach)
 M.cleanup()
 local actions=require('MorpheusMouse.paradise_tests')
 local ok,message=actions.test_animation(selected,entry.dict,entry.anim,1,attach,math.floor(entry.flag or 1))
 if not ok then M.status=message;return false,message end
 local me=safe(players.me);local ped=me and me.ped
 if not ped then return false,'Your character is unavailable'end
 local pending={}
 for i=1,2 do
  local model=tonumber(entry['prop'..i])or 0
  if model~=0 then
   model=math.floor(model)%4294967296
   if safe(native.is_model_valid,model)~=true or safe(native.is_model_in_cdimage,model)~=true then M.cleanup();actions.stop_animation();return false,'Preset prop unavailable on this build'end
   pending[#pending+1]={model=model,index=i}
  end
 end
 if #pending==0 then M.status='Playing '..entry.name;return true,M.status end
 M.pending=pending
 local started=util.get_tick_count()
 for _,p in ipairs(pending)do safe(native.request_model,p.model)end
 M.status='Playing animation; loading props for '..entry.name
 local function update()
  local mine=safe(players.me)
  if not mine or mine.ped~=ped or safe(native.does_entity_exist,ped)~=true then M.cleanup();M.status='Preset stopped: character changed';return false end
  if M.pending then
   local loaded=true
   for _,p in ipairs(M.pending)do if safe(native.has_model_loaded,p.model)~=true then loaded=false;safe(native.request_model,p.model)end end
   if not loaded then
    local now=util.get_tick_count()
    if now<started or now-started>=3000 then M.cleanup();M.status='Animation playing; preset props could not load';return false end
    return
   end
   local coords=safe(native.get_entity_coords,ped,true)or mine.coords
   if not coords then M.cleanup();M.status='Preset position unavailable';return false end
   for _,p in ipairs(M.pending)do
    local h=safe(native.create_object_no_offset,p.model,coords.x,coords.y,coords.z,false,true,false)
    if not h or h==0 then M.cleanup();M.status='Preset prop could not spawn';return false end
    M.props[#M.props+1]={handle=h,model=p.model}
    native.set_entity_as_mission_entity(h,true,true)
    native.set_entity_collision(h,false,false)
    local second=p.index==2;local suffix=second and '2'or ''
    local bone=second and entry.bone2 or entry.boneID
    native.attach_entity_to_entity(h,ped,native.get_ped_bone_index(ped,math.floor(bone or 57005)),entry['posx'..suffix]or 0,entry['posy'..suffix]or 0,entry['posz'..suffix]or 0,entry['rotx'..suffix]or 0,entry['roty'..suffix]or 0,entry['rotz'..suffix]or 0,false,false,false,false,2,true,false)
   end
   M.pending=nil;M.status='Playing '..entry.name..' (props visible only to you)'
  end
  local playing=safe(native.is_entity_playing_anim,ped,entry.dict,entry.anim,3)
  if playing==false then M.cleanup();M.status='Preset animation ended; props removed';return false end
 end
 M.worker=threads.start('extras_preset_props',function()
  local ok,why=pcall(update)
  if not ok then M.cleanup();M.status='Preset stopped: '..tostring(why);return false end
  return why
 end,{interval_ms=100})
 if not M.worker then M.cleanup();return false,'Preset prop loader could not start'end
 return true,M.status
end
function M.draw(pos,width,selected,submit)
 local w=require('MorpheusMouse.widgets');local theme=require('MorpheusMouse.theme');local y=pos.y
 local height=theme.control_height and theme.control_height(28,22)or 28
 local function note(text)w.row_label(vec2(pos.x,y),text,width,nil,true,theme.colors.text_dim);y=y+height+6 end
 w.section(vec2(pos.x,y),'EXTRAS PRESET TESTS');y=y+26
 w.search_input(vec2(pos.x,y),vec2(width,height),'extras-preset-search',M.query,function(v)M.query=tostring(v or'');M.choice=1 end,'Search preset names');y=y+height+6
 local rows,labels={},{};local query=M.query:lower()
 for _,entry in ipairs(data)do if query==''or entry.name:lower():find(query,1,true)then rows[#rows+1]=entry;labels[#labels+1]=entry.name end end
 if #rows==0 then note('No matching presets');return y end
 local used;M.choice,used=w.dropdown(vec2(pos.x,y),width,'extras-preset','Preset',labels,M.choice);y=y+used+6
 local entry=rows[M.choice]or rows[1]
 note('Animates you; preset props are local preview')
 note('Extra actors and particle effects are not included')
 local function button(label,fn)
  if w.button(vec2(pos.x,y),vec2(width,height),label)then submit(function()local ok,why=fn();M.status=why or M.status;return ok,why end)end
  y=y+height+6
 end
 button('TEST PRESET ON ME',function()return M.play(selected,entry,false)end)
 button('ATTACH ME + TEST PRESET',function()return M.play(selected,entry,true)end)
 button('STOP PRESET / REMOVE ITS PROPS',function()M.cleanup();return require('MorpheusMouse.paradise_tests').stop_animation()end)
 note(M.status)
 return y
end
return M

end

