local function safe(fn,...)
 if type(fn)~='function'then return nil end
 local ok,value=pcall(fn,...);if ok then return value end
end
local function target(selected)
 if M.stopped then return nil,'Player options are unloaded'end
 local p=safe(players.get,selected.id)
 if not p or p.connected==false or p.exists==false or tostring(p.rockstar_id)~=tostring(selected.rockstar_id)or p.name~=selected.name then return nil,'Selected player changed or left'end
 local me=safe(players.me)
 if not me or tonumber(me.id)==tonumber(p.id)then return nil,'Select another online player'end
 if not p.ped or p.ped==0 or safe(native.does_entity_exist,p.ped)~=true then return nil,'Selected player is not streamed'end
 return p
end
local function load_asset(ready,request,valid)
 for _=1,120 do
  if M.stopped or not valid()then return false end
  if ready()then return true end
  request();jobs.yield(25)
 end
 return false
end
