 if name:find('drunk',1,true)or name:find('injured',1,true)then return 3 end
 if name:find('flee',1,true)or name:find('hurry',1,true)or name:find('runner',1,true)or name:find('@jog',1,true)or name:find('@quick',1,true)or name:find('@fire',1,true)then return 2 end
 if name:find('move_characters',1,true)or name:find('handbag',1,true)or name:find('clipboard',1,true)or name:find('leaf_blower',1,true)or name:find('tool_belt',1,true)or name:find('intimidation',1,true)or name:find('film_reel',1,true)or name:find('move_cop',1,true)then return 4 end
 return 1
end
