local function filtered()
 local key=keys[M.mode]
 if M.filter_mode==key and M.filter_query==M.query and M.filter_group==M.movement_group then return M.rows,M.labels end
 local rows,labels={},{}
 local query=string.lower(M.query)
 for _,item in ipairs(catalog[key]or{})do
  local label=type(item)=='string'and item or item.dict or(item.effect..' ['..item.asset..']')
  local display=key=='props'and(prop_names[item]or label)or label
  local search=string.lower(display..' '..label)
  local ready=(key~='animations'or #item.clips>0)and(key~='movements'or movement_group(item)==M.movement_group)
  if ready and(query==''or string.find(search,query,1,true))then rows[#rows+1]=item;labels[#labels+1]=key=='movements'and movement_label(item)or display end
 end
 if key=='props'then
  local sorted={};for i,model in ipairs(rows)do sorted[#sorted+1]={model=model,label=labels[i]}end
  table.sort(sorted,function(a,b)return a.label:lower()<b.label:lower()end)
  for i,row in ipairs(sorted)do rows[i]=row.model;labels[i]=row.label end
 end
 M.filter_mode=key;M.filter_query=M.query;M.filter_group=M.movement_group;M.rows=rows;M.labels=labels;M.choice=1;M.clip_index=1;M.custom_clip=''
 return rows,labels
end
function M.test_prop(selected,model,preset)
 local p,why=target(selected);if not p then return false,why end
 local ok,message=attachment.add_prop(selected,1,{label=prop_names[model]or model,model=model,bone=preset.bone,x=preset.x,y=preset.y,z=preset.z,rx=preset.rx,ry=preset.ry,rz=preset.rz,networked=preset.networked})
