  local me=safe(players.me)
  if me and me.ped==record.ped then safe(native.stop_anim_task,record.ped,record.dict,record.clip,2.0);safe(native.clear_ped_secondary_task,record.ped)end
  safe(native.remove_anim_dict,record.dict);M.animation=nil
