end
function M.test_animation(selected,dict,clip,position,attach,flags)
 if M.stopped then return false,'Player options are unloaded'end
 if type(clip)~='string'or clip==''then return false,'Choose or enter a clip name first'end
 if safe(native.does_anim_dict_exist,dict)==false then return false,'This recovered identifier is not an animation dictionary on this build'end
