 end
 local me=safe(players.me);local ped=me and me.ped
 if not ped or safe(native.does_entity_exist,ped)~=true then return false,'Your character is unavailable'end
 if safe(native.is_ped_in_any_vehicle,ped,false)==true then return false,'Exit your vehicle before testing an emote on yourself'end
 M.stop_animation()
 if not load_asset(function()return native.has_anim_dict_loaded(dict)end,function()native.request_anim_dict(dict)end,function()
  local mine=safe(players.me);return mine and mine.ped==ped and safe(native.does_entity_exist,ped)==true
 end)then safe(native.remove_anim_dict,dict);return false,'Animation dictionary could not load'end
