local function movement_clock()
 return util.get_tick_count()
end
local function release_movement_set(name)
 safe(native.remove_clip_set or native.remove_anim_set,name)
end
function M.reset_movement()
 if M.movement_worker then threads.stop(M.movement_worker,'movement_reset');M.movement_worker=nil end
 if M.movement_pending then release_movement_set(M.movement_pending);M.movement_pending=nil end
