end
function M.test_movement(selected,clipset)
 if M.stopped then return false,'Player options are unloaded'end
 local me=safe(players.me);local ped=me and me.ped
 if not ped or ped==0 or safe(native.does_entity_exist,ped)~=true then return false,'Your character is unavailable'end
 if safe(native.is_ped_in_any_vehicle,ped,false)==true then return false,'Exit your vehicle to test a movement style'end
 M.reset_movement()
 local ready=native.has_clip_set_loaded or native.has_anim_set_loaded
 local request=native.request_clip_set or native.request_anim_set
 local started=movement_clock()
 M.movement_pending=clipset
 local function poll()
  local mine=safe(players.me)
  local function finish(ok,message)
   M.movement_pending=nil;M.movement_worker=nil;M.status=message
   if not ok then release_movement_set(clipset)end
   return false
  end
  if M.stopped or not mine or mine.ped~=ped or safe(native.does_entity_exist,ped)~=true then return finish(false,'Movement cancelled: your character changed')end
  if safe(native.is_ped_in_any_vehicle,ped,false)==true then return finish(false,'Movement cancelled: exit your vehicle')end
  if safe(ready,clipset)==true then
   local ok,err=pcall(native.set_ped_movement_clipset,ped,clipset,0.25)
   if not ok then return finish(false,'Movement could not apply: '..tostring(err))end
   M.movement_ped=ped;M.movement_set=clipset
