  safe(request,clipset)
 end
 safe(request,clipset)
 if poll()==false then return M.movement_set==clipset,M.status end
 M.status='Loading movement: '..clipset
 M.movement_worker=threads.start('paradise_movement_load',poll,{interval_ms=50})
 if not M.movement_worker then M.movement_pending=nil;release_movement_set(clipset);M.status='Movement loader could not start';return false,M.status end
 return true,M.status
end
local function clock()
 return type(util)=='table'and type(util.get_tick_count)=='function'and util.get_tick_count()or math.floor(os.clock()*1000)
end
function M.stop_particle()
 if M.particle_owner then effects.stop(M.particle_owner);M.particle_owner=nil end
 if M.particle_worker then threads.stop(M.particle_worker,'paradise_particle_stop');M.particle_worker=nil end
