function M.test_particle(selected,preset,on_me,networked,mode)
 if M.stopped then return false,'Player options are unloaded'end
 local p,why
 if on_me then p=safe(players.me)else p,why=target(selected)end
 if not p then return false,why or'Your character is unavailable'end
 local ped=p.ped
 if not ped or safe(native.does_entity_exist,ped)~=true then return false,'Target is not streamed'end
 M.stop_particle()
 local coords=p.coords
 if not coords then return false,'Target coordinates are unavailable'end
 local function valid()
  local fresh=on_me and safe(players.me)or target(selected)
  return fresh and fresh.ped==ped and safe(native.does_entity_exist,ped)==true
 end
 local function request(asset)
  return load_asset(function()return native.has_named_ptfx_asset_loaded(asset)end,function()native.request_named_ptfx_asset(asset)end,valid)
 end
 local capability=effects.capability(preset.asset,preset.effect)
 local selected_mode=mode=='Loop (3 seconds)'and'native_looped'or(mode=='Burst'and'one_shot'or(capability.mode=='native_looped'and'native_looped'or'one_shot'))
 local function start(effect_mode)
  if not valid()then return false,'Target changed'end
  return effects.start({owner_key=effects.next_owner('paradise_test'),target_key='paradise_test:'..ped,asset=preset.asset,effect=preset.effect,mode=effect_mode,
   target_mode=effect_mode=='one_shot'and'coord'or'entity',entity=ped,x=coords.x,y=coords.y,z=coords.z+0.5,oz=0.5,scale=0.5,networked=networked==true,
   request_particle=request,asset_yield=jobs.yield})
 end
 local ok,message,owner=start(selected_mode)
 if not ok and not mode then selected_mode='native_looped';ok,message,owner=start(selected_mode)end
 print('SPACEx Paradise particle | '..preset.asset..' | '..preset.effect..' | '..selected_mode..' | '..tostring(ok)..' | '..tostring(message))
 if not ok then return false,'Particle unavailable: '..tostring(message)end
 if selected_mode=='native_looped'then
  M.particle_owner=owner;local deadline=clock()+3000
  M.particle_worker=threads.start('paradise_particle_timeout',function()
   if M.stopped or clock()>=deadline or not valid()then M.stop_particle();return false end
   return true
  end,{interval_ms=100,on_error=M.stop_particle})
  if not M.particle_worker then M.stop_particle();return false,'Particle timeout could not start'end
