  if enabled==false then widgets.disabled_button(vec2(pos.x,y),vec2(width,height),label,'Choose an animation with a matched clip name first')
  elseif widgets.button(vec2(pos.x,y),vec2(width,height),label)then submit(function()
   local ok,message=fn();M.status=tostring(message or(ok and 'Done'or 'Action failed'));return ok,message
  end)end
  y=y+height+6
 end
 widgets.section(vec2(pos.x,y),'PLAYER OPTIONS');y=y+26
