 selected={id=selected.id,name=selected.name,rockstar_id=selected.rockstar_id}
 if widgets.button(vec2(pos.x,y),vec2(width,height),'CLEAR ATTACHMENTS / STOP ACTIONS')then submit(function()return M.cleanup()end)end;y=y+height+6
 local used,changed
 M.mode,used,changed=widgets.dropdown(vec2(pos.x,y),width,'paradise-mode','Category',modes,M.mode);y=y+used+6
 if changed then M.query='';M.filter_mode=nil end
 if M.mode==5 then return require('MorpheusMouse.extras_preset_tests').draw(vec2(pos.x,y),width,selected,submit)end
 widgets.search_input(vec2(pos.x,y),vec2(width,height),'paradise-filter',M.query,function(value)M.query=tostring(value or'')end,'Search options');y=y+height+6
 if M.mode==3 then
  M.movement_group,used=widgets.dropdown(vec2(pos.x,y),width,'paradise-movement-group','Movement group',movement_groups,M.movement_group);y=y+used+6
  if M.movement_group==5 then note('Idle / partial sets may not change walking; experimental')
