  M.visibility=M.visibility or 1
  M.visibility,used=widgets.dropdown(vec2(pos.x,y),width,'paradise-prop-visibility','Prop visibility',{'Networked','Local preview (only you)'},M.visibility);y=y+used+6
  local names={};for i,bone in ipairs(bones)do names[i]=bone.label end
