  if widgets.button(vec2(pos.x,y),vec2(width,height),M.show_prop_position and 'HIDE PROP POSITION' or 'ADJUST PROP POSITION')then M.show_prop_position=not M.show_prop_position end;y=y+height+6
  M.axis_dragging=M.axis_dragging or {}
  if M.show_prop_position then
  for _,axis in ipairs({'x','y','z','rx','ry','rz'})do
   local rotation=#axis==2
   M[axis],M.axis_dragging[axis]=widgets.compact_value_slider(vec2(pos.x,y),width,(rotation and 'Rotation 'or 'Offset ')..axis:sub(-1):upper(),M[axis],rotation and -180 or -2,rotation and 180 or 2,M.axis_dragging[axis],function(value)return string.format(rotation and '%.0f deg'or '%.2f m',value)end)
   y=y+height+6
  end
  end
  local preset={bone=bones[M.bone].id,x=M.x,y=M.y,z=M.z,rx=M.rx,ry=M.ry,rz=M.rz,networked=M.visibility==1}
