  M.particle_target,used=widgets.dropdown(vec2(pos.x,y),width,'paradise-fx-target','Particle target',{'On me','Selected player'},M.particle_target);y=y+used+6
  M.particle_visibility,used=widgets.dropdown(vec2(pos.x,y),width,'paradise-fx-visible','Particle visibility',{'Local preview (only you)','Networked'},M.particle_visibility);y=y+used+6
  M.particle_mode,used=widgets.dropdown(vec2(pos.x,y),width,'paradise-fx-mode','Effect type',{'Auto','Burst','Loop (3 seconds)'},M.particle_mode);y=y+used+6
