end

package.preload["MorpheusMouse.player_notes"]=function(...)
local M={entries={},running=true}
local function key(target)
 local value=target and target.rockstar_id
 if type(value)~="number"and type(value)~="string"then return nil end
 local id=tostring(value)
 if not id:match("^%d+$")or id:match("^0+$")or #id>20 then return nil end
 return id
end
local function path(id)return paths.game.."\\scripts\\MorpheusMouse\\player-note-"..id..".json"end
local function text(value)
 return tostring(value or""):gsub("[%z\1-\31\127]"," "):sub(1,512)
end
local function read_file(filename)
 local handle=file.open(filename,{})
 assert(handle and handle.valid and type(handle.text)=="string","Cannot read note file")
 return handle.text,handle
end
local function write_file(filename,body)
 local handle=file.open(filename,{append=false,create_if_not_exists=true})
 assert(handle and handle.valid,"Cannot open note file for writing")
 handle.text=body
 assert(read_file(filename)==body,"Note write verification failed")
end
function M.load(target)
 local id=key(target);if not id then return false,"Rockstar ID unavailable; notes are disabled"end
 local entry=M.entries[id]or{draft="",saved=""};M.entries[id]=entry
 local ok,note=pcall(function()
  if not file.exists(path(id))then return ""end
  local _,handle=read_file(path(id))
  local data=json.decode(handle.json)
  assert(type(data)=="table"and data.version==1 and data.rockstar_id==id and type(data.note)=="string"and #data.note<=512,"Invalid note file; original preserved")
  return data.note
 end)
 entry.loaded=true;entry.error=not ok and tostring(note)or nil
 if ok then entry.saved=note;entry.draft=note;entry.status=note==""and"No saved note"or"Saved locally"end
 return ok,ok and entry.status or entry.error
end
function M.set_draft(target,value)
 local id=key(target);local entry=id and M.entries[id]
 if not entry or not entry.loaded or entry.error or entry.busy then return false end
 entry.draft=text(value);return true
end
function M.save(target)
 local id=key(target);local entry=id and M.entries[id]
 if not entry or not entry.loaded then return false,"Load this player's note first"end
 if entry.error then return false,entry.error end
 local filename=path(id);local body=json.encode({version=1,rockstar_id=id,player_name=text(target.name),note=entry.draft}):dump(2)
 local existed=file.exists(filename);local previous
 if existed then previous=read_file(filename)end
 local staged,err=pcall(function()
  write_file(filename..".next",body)
  if existed then write_file(filename..".backup",previous)end
 end)
 if not staged then return false,"Note staging failed: "..tostring(err)end
 local written,write_error=pcall(write_file,filename,body)
 if not written then
  local restored,restore_error=pcall(function()
   if existed then write_file(filename,previous)
   else assert(file.remove(filename)and not file.exists(filename),"Cannot remove incomplete note")end
  end)
  return false,"Note save failed: "..tostring(write_error)..(restored and"; previous file preserved"or"; rollback failed: "..tostring(restore_error))
 end
 pcall(file.remove,filename..".next")
 entry.saved=entry.draft;entry.status="Saved locally"
 return true,"Player note saved"
end
local function queue(target,operation)
 local id=key(target);if not id then return end
 local entry=M.entries[id]or{draft="",saved=""};M.entries[id]=entry
 if entry.busy then return end
 entry.busy=true
 local captured={rockstar_id=id,name=tostring(target.name or"")}
 local queued,queue_error=pcall(util.create_job,function()
  if not M.running then entry.busy=false;return end
  local ok,success,detail=pcall(operation,captured)
  entry.busy=false
  if not ok or success~=true then entry.status=tostring(ok and detail or success)end
  if operation==M.save then
   local state=require("MorpheusMouse.state")
   local notify=ok and success and state.notify_success or state.notify_error
   if type(notify)=="function"then pcall(notify,ok and detail or tostring(success))end
  end
 end)
 if not queued then entry.busy=false;entry.loaded=true;entry.error=tostring(queue_error);entry.status=entry.error end
end
function M.draw(pos,width,target)
 local widgets=require("MorpheusMouse.widgets")
 local theme=require("MorpheusMouse.theme")
 local state=require("MorpheusMouse.state")
 local height=type(theme.control_height)=="function"and theme.control_height(30,24)or 30
 local gap=type(theme.scale_metric)=="function"and theme.scale_metric(8,4)or 8
 local y=pos.y
 widgets.section(vec2(pos.x,y),"PLAYER NOTES");y=y+height
 if state.ui.clean_mode==true then widgets.empty_state(vec2(pos.x,y),width,"Player notes hidden in Clean Mode");return y+height end
 local id=key(target)
 if not id then widgets.empty_state(vec2(pos.x,y),width,"Rockstar ID unavailable");return y+height end
 local entry=M.entries[id]
 if not entry then queue(target,M.load);entry=M.entries[id]end
 if not entry.loaded then widgets.empty_state(vec2(pos.x,y),width,"Loading player note...");return y+height end
 if not entry.error and not entry.busy then
  widgets.text_input(vec2(pos.x,y),vec2(width,height),"player_notes."..id,entry.draft,"Click to type a player note",function(value)M.set_draft({rockstar_id=id},value)end,"Local note, up to 512 bytes. Click Save Note to keep changes.")
  y=y+height+gap
  local half=(width-gap)/2
  if widgets.button(vec2(pos.x,y),vec2(half,height),"SAVE NOTE","Save this note locally for the selected Rockstar ID.")then queue(target,M.save)end
  if widgets.button(vec2(pos.x+half+gap,y),vec2(half,height),"RELOAD NOTE","Discard unsaved edits and reload the local note file.")then queue(target,M.load)end
  y=y+height+gap
 elseif entry.error then
  if widgets.button(vec2(pos.x,y),vec2(width,height),"RETRY LOADING NOTE","Retry reading the note; invalid files are never overwritten.")then queue(target,M.load)end
  y=y+height+gap
 end
 local status=entry.busy and"Working..."or entry.error or(entry.draft~=entry.saved and"Unsaved changes"or entry.status or"Saved locally")
 widgets.empty_state(vec2(pos.x,y),width,status)
 return y+height+gap
end
function M.cleanup()M.running=false end
return M
end


package.preload["MorpheusMouse.session_summary"]=function(...)
local M={}
function M.snapshot(roster,me,session_host,script_host,clean)
 local by_id={};local total,friends=0,0
 local me_id=me and tonumber(me.id)
 for _,player in ipairs(roster or{})do
  local id=tonumber(player.id)
  if id and id>=0 and id<=31 and id==math.floor(id)and player.connected~=false and player.exists~=false and not by_id[id]then
   by_id[id]=player;total=total+1
   if id~=me_id and player.friend==true then friends=friends+1 end
  end
 end
 local function host_name(host)
  local id=host and tonumber(host.id)
  local player=id and by_id[id]
  if not player then return "Unavailable"end
  if host.rockstar_id~=nil and player.rockstar_id~=nil and tostring(host.rockstar_id)~=tostring(player.rockstar_id)then return "Unavailable"end
  if clean then return id==me_id and"You"or("Player "..tostring(id))end
  local name=tostring(player.name or("Player "..id))
  return name..(id==me_id and" (you)"or"")
 end
 return {players=total,friends=friends,session_host=host_name(session_host),script_host=host_name(script_host)}
end
function M.draw(pos,width,row,roster,me,session_host,script_host)
 local widgets=require("MorpheusMouse.widgets")
 local theme=require("MorpheusMouse.theme")
 local state=require("MorpheusMouse.state")
 local scale=type(theme.scale_metric)=="function"and theme.scale_metric or function(n)return n end
 local section_height=(type(theme.effective_text_scale)=="function"and theme.effective_text_scale(theme.small_scale)or theme.small_scale or 12)+scale(8,5)
 local y=pos.y
 widgets.section(vec2(pos.x,y),"SESSION SUMMARY");y=y+section_height
 local ok,loaded=pcall(game.in_game)
 if not ok or loaded~=true then
  widgets.empty_state(vec2(pos.x,y),width,"Waiting for a loaded game")
  return y+section_height+scale(8,4)
 end
 local summary=M.snapshot(roster,me,session_host,script_host,state.ui.clean_mode==true)
 y=row(vec2(pos.x,y),width,"Players (includes you)",summary.players)
 y=row(vec2(pos.x,y),width,"Friends (excludes you)",summary.friends)
 y=row(vec2(pos.x,y),width,"Session Host",summary.session_host)
 y=row(vec2(pos.x,y),width,"Freemode Script Host",summary.script_host)
 return y+scale(12,6)
end
return M
end


