package.preload["MorpheusMouse.session_migration_watch"]=function(...)
local M={running=false,subscription=nil,worker=nil,pending=0,first_warning=nil,last_warning=nil,last_sample=nil,incident=nil}
local PREFIX="Session Migration Watch | "
local function log(text)print(PREFIX..text)end
local function sample()
 local tick=util.get_tick_count()
 local ok,loaded=pcall(game.in_game)
 if not ok or not loaded then return {key="unavailable",description="unavailable",tick=tick}end
 local success,host=pcall(game.host)
 if not success or not host then return {key="unavailable",description="unavailable",tick=tick}end
 local id=tonumber(host.id)
 if not id or id<0 or id>31 then return {key="unavailable",description="unavailable",tick=tick}end
 local player_ok,player=pcall(players.get,id)
 if not player_ok or not player or player.connected==false or player.exists==false then return {key="unavailable",description="unavailable",tick=tick}end
 local me_ok,me=pcall(players.me)
 local mine=me_ok and me and tonumber(me.id)==id or false
 return {key=tostring(player.rockstar_id or"unknown")..":"..id,description="slot="..id..",is_you="..tostring(mine),tick=tick}
end
function M.on_log(data)
 if not M.running then return end
 local text=tostring(data and data.text or"")
 local prefix=tostring(data and data.prefix or"")
 -- Ignore script-generated output, including this observer's own log messages.
 if text:find(PREFIX,1,true)or prefix:find("SPACEx",1,true)or text:find("Morpheus Mouse",1,true)then return end
 if not text:lower():find("attempted to desync",1,true)then return end
 local tick=util.get_tick_count()
 M.first_warning=M.first_warning or tick;M.last_warning=tick
 M.pending=math.min(100000,M.pending+1)
end
function M.poll()
 if not M.running then return false end
 local current=sample();local tick=current.tick
 if M.pending>0 then
  if not M.incident then
   local before=M.last_sample
   M.incident={started=tick,count=0,last_key=current.key}
   log("warning_window_started | warning_tick="..tostring(M.first_warning).." | previous_observation="..(before and before.description or"unavailable").." | previous_tick="..tostring(before and before.tick or"unavailable").." | current="..current.description)
  end
  M.incident.count=M.incident.count+M.pending
  log("warning_batch | count="..M.pending.." | last_warning_tick="..tostring(M.last_warning).." | current="..current.description)
  M.pending=0;M.first_warning=nil;M.last_warning=nil
 end
 local incident=M.incident
 if incident then
  if current.key~=incident.last_key then
   log("host_observation_changed | elapsed_ms="..tostring(tick-incident.started).." | current="..current.description)
   incident.last_key=current.key
  end
  if tick<incident.started or tick-incident.started>=30000 then
   log("warning_window_finished | warning_count="..incident.count.." | final="..current.description.." | correlation_does_not_establish_cause=true")
   M.incident=nil
  end
 end
 M.last_sample=current
end
function M.start()
 if M.running then return true end
 if type(events)~="table"or type(events.event)~="table"or events.event.log==nil or type(events.subscribe)~="function"then log("unavailable | Lexis log subscription API missing");return false end
 M.running=true
 local ok,id=pcall(events.subscribe,events.event.log,M.on_log)
 if not ok or id==nil then M.running=false;log("unavailable | Log subscription failed");return false end
 M.subscription=id
 M.worker=require("MorpheusMouse.runtime_threads").start("session_migration_watch",M.poll,{interval_ms=1000})
 if not M.worker then M.cleanup();log("unavailable | Worker could not start");return false end
 log("started | read_only=true | observation_window_ms=30000")
 return true
end
function M.cleanup()
 M.running=false
 if M.subscription~=nil then pcall(events.unsubscribe,M.subscription);M.subscription=nil end
 if M.worker then require("MorpheusMouse.runtime_threads").stop(M.worker,"watch_cleanup");M.worker=nil end
 M.pending=0;M.first_warning=nil;M.last_warning=nil;M.incident=nil;M.last_sample=nil
end
return M
end


package.preload["MorpheusMouse.host_change_alerts"]=function(...)
local M={enabled=true,worker=nil,channels={}}
local function identity(host)
 if not host then return nil end
 local id=tonumber(host.id)
 if not id or id<0 or id>31 or id~=math.floor(id)then return nil end
 local player=players.get(id)
 if not player or player.connected==false or player.exists==false then return nil end
 local rid=player.rockstar_id
 if rid==nil or tostring(rid):match("^0+$")then return nil end
 if host.rockstar_id~=nil and tostring(host.rockstar_id)~=tostring(rid)then return nil end
 return {key=tostring(rid),id=id,name=tostring(player.name or("Player "..id))}
end
local function label(player)
 local state=require("MorpheusMouse.state")
 if state.ui.clean_mode then
  local me=players.me()
  return me and tonumber(me.id)==player.id and"You"or("Player "..player.id)
 end
 return player.name
end
function M.observe(kind,current)
