 for _,action in ipairs(actions.all())do
  if action.protection_edition then
   total=total+1
   if action.protection_edition==compat.edition and action.value==true and action.protection_kind~="preset"then selected=selected+1 end
   rows[#rows+1]=table.concat({clean(action.id),clean(action.protection_edition),tostring(action.enabled==true),tostring(action.wired==true),clean(action.value),clean(action.status)}," | ")
  end
 end
 rows[#rows+1]="";rows[#rows+1]="LEXIS CONTROL READ CHECKS"
