 end
 for _,entry in ipairs(catalog.event_limits)do
  local base="Network > Protections > Limitations > "..entry.name
  probe(base.." > Toggle","toggle");probe(base.." > Max Count","number")
 end
 rows[#rows+1]="";rows[#rows+1]="LOADED GUARD CAPABILITIES (no new hooks installed by this audit)"
 local names={}
 for name,loaded in pairs(package.loaded)do
  if type(name)=="string"and name:sub(1,14)=="MorpheusMouse."and type(loaded)=="table"and type(loaded.capabilities)=="function"then names[#names+1]=name end
