    local failed=tonumber(data.skipped_hooks)or 0
    local pending=math.max(0,data.total_hooks-data.installed_hooks-failed)
    local status=data.active==false and"INACTIVE (not evidence of failure)"or failed>0 and"INSTALLATION_FAILURES"or data.installation_complete==false and"INSTALLATION_PENDING"or"REGISTRATION_COMPLETE (effectiveness untested)"
    rows[#rows+1]=name..".audit_status="..status
    rows[#rows+1]=name..".not_yet_installed="..pending
    if type(guard.install_failures)=="table"then append_table(rows,name..".installation_failures",guard.install_failures,{},0)end
   end
  else rows[#rows+1]=name.." | CAPABILITY_ERROR | "..clean(data)end
 end
 rows[#rows+1]=""
 rows[#rows+1]="SUMMARY actions="..total..", selected_nonpreset_toggles_current_edition="..selected..", readable_controls="..found..", unavailable_controls="..missing..", read_errors="..failed
 rows[#rows+1]="ATTACK EFFECTIVENESS: NOT TESTED. Readable or selected does not establish prevention."
 assert(M.running,"Audit cancelled")
 local path=paths.game.."\\scripts\\MorpheusMouse\\Diagnostics\\protection-audit-"..tostring(util.get_tick_count())..".txt"
