package.preload["MorpheusMouse.weapon_customization"]=function(...)
local M={page=1,query='',choice=1,status='Choose an option',hidden={},color={r=40,g=210,b=145,a=210},drag={}}
local n=require('natives')
local catalog=require('MorpheusMouse.weapon_catalog')
local styles=require('MorpheusMouse.weapon_style_catalog')
local function safe(fn,...)if type(fn)=='function'then local ok,v=pcall(fn,...);if ok then return v end end end
local function me()local p=safe(players.me);if p and p.ped and safe(n.does_entity_exist,p.ped)==true then return p.ped end end
local function u32(v)return math.floor(tonumber(v)or 0)%4294967296 end
local function i32(v)v=u32(v);return v>=2147483648 and v-4294967296 or v end
local function owned(ped,weapon)return safe(n.has_ped_got_weapon,ped,i32(weapon),false)==true end
local function comp(ped,weapon,hash)return safe(n.has_ped_got_weapon_component,ped,i32(weapon),i32(hash))==true end
local function compatible(weapon,hash)return safe(n.does_weapon_take_weapon_component,i32(weapon),i32(hash))==true end
function M.invalidate()M.scan_tick=nil;M.rows=nil end
function M.entries()
 local ped=me();if not ped then return {} end
 local now=util.get_tick_count()
 if M.rows and M.scan_ped==ped and M.scan_query==M.query and now>=M.scan_tick and now-M.scan_tick<750 then return M.rows end
 local rows={};local query=M.query:lower()
 for _,entry in ipairs(catalog.entries())do
  if catalog.is_usable(entry)and(query==''or(entry.label..' '..entry.model):lower():find(query,1,true))then
   local hidden=M.hidden[entry.hash_uint32]
   if owned(ped,entry.canonical_hash)or(hidden and hidden.ped==ped)then rows[#rows+1]=entry end
  end
 end
 table.sort(rows,function(a,b)return a.label:lower()<b.label:lower()end)
 M.rows=rows;M.scan_tick=now;M.scan_ped=ped;M.scan_query=M.query
 return rows
end
function M.hide(entry)
 local ped=me();if not ped or not entry or not owned(ped,entry.canonical_hash)then return false,'Choose a carried weapon'end
 local key=entry.hash_uint32
 if M.hidden[key]then return false,'This weapon already has a saved loadout record'end
 local data=styles[entry.model]or{};local components={}
 for _,hash in ipairs(data.components or{})do if comp(ped,key,hash)then components[#components+1]=hash end end
 local ammo=safe(n.get_ammo_in_ped_weapon,ped,entry.canonical_hash)
 local tint=safe(n.get_ped_weapon_tint_index,ped,entry.canonical_hash)
 if type(ammo)~='number'or type(tint)~='number'then return false,'Could not save this weapon before removing it'end
 local record={ped=ped,entry=entry,ammo=ammo,tint=tint,components=components,component_colors={}}
 for _,hash in ipairs(components)do
  local ok,v=pcall(function()return invoker.call(0xF0A60040BE558F2D,ped,entry.canonical_hash,i32(hash)).int end)
  if ok and type(v)=='number'and v>=0 and v<=31 then record.component_colors[hash]=v end
 end
 M.hidden[key]=record
 n.remove_weapon_from_ped(ped,entry.canonical_hash)
 M.invalidate()
 if owned(ped,entry.canonical_hash)then M.hidden[key]=nil;return false,'Game did not remove this weapon'end
 return true,entry.label..' removed from carried loadout; Restore brings it back'
end
function M.restore(entry)
 local key=entry and entry.hash_uint32;local record=key and M.hidden[key]
 if not record then return false,'No saved weapon to restore'end
 local ped=me();if ped~=record.ped then return false,'Character changed; cannot restore the previous character loadout'end
 local hash=record.entry.canonical_hash
 local already=owned(ped,hash)
 if not already then n.give_weapon_to_ped(ped,hash,0,false,false)end
 if not owned(ped,hash)then return false,'Game did not restore this weapon'end
 for _,c in ipairs(record.components)do if compatible(hash,c)then n.give_weapon_component_to_ped(ped,hash,i32(c))end end
 n.set_ped_weapon_tint_index(ped,hash,record.tint)
 for c,color in pairs(record.component_colors)do invoker.call(0x9FE5633880ECD8ED,ped,hash,i32(c),color)end
 local current=safe(n.get_ammo_in_ped_weapon,ped,hash)or 0
 if not already then n.set_ped_ammo(ped,hash,math.max(current,record.ammo),0)end
 M.hidden[key]=nil;M.invalidate()
 return true,record.entry.label..' restored'
end
function M.restore_all()
 local entries={};for _,r in pairs(M.hidden)do entries[#entries+1]=r.entry end
 local failed=0
 for _,entry in ipairs(entries)do local ok=M.restore(entry);if not ok then failed=failed+1 end end
 return failed==0,failed==0 and 'Removed weapons restored'or tostring(failed)..' weapons could not be restored to the current character'
end
function M.finishes(entry)
 local result={};if not entry then return result end
 for _,f in ipairs((styles[entry.model]or{}).finishes or{})do if compatible(entry.canonical_hash,f.hash)then result[#result+1]=f end end
 return result
end
function M.tint(entry,index)
 local ped=me();if not ped or not entry or not owned(ped,entry.canonical_hash)then return false,'Restore or equip a carried weapon first'end
 local count=safe(n.get_weapon_tint_count,entry.canonical_hash)or 0
 if type(index)~='number'or index<0 or index>=count or index~=math.floor(index)then return false,'Tint unavailable for this weapon'end
 n.set_ped_weapon_tint_index(ped,entry.canonical_hash,index)
 return safe(n.get_ped_weapon_tint_index,ped,entry.canonical_hash)==index,'Weapon tint updated'
end
function M.finish(entry,finish,color)
 local ped=me();if not ped or not entry or not owned(ped,entry.canonical_hash)then return false,'Restore or equip a carried weapon first'end
 local choices=M.finishes(entry);local wanted
 for _,f in ipairs(choices)do if finish and f.hash==finish.hash then wanted=f end end
 if finish and not wanted then return false,'Finish unavailable for this weapon'end
 local previous={}
 for _,f in ipairs(choices)do
  if comp(ped,entry.canonical_hash,f.hash)then previous[#previous+1]=f.hash end
  if f.pair~=0 and comp(ped,entry.canonical_hash,f.pair)then previous[#previous+1]=f.pair end
 end
 -- Only remove cosmetic components; preserve magazines, sights and other upgrades.
 for _,f in ipairs(choices)do
  if not wanted or f.hash~=wanted.hash then
   if comp(ped,entry.canonical_hash,f.hash)then n.remove_weapon_component_from_ped(ped,entry.canonical_hash,i32(f.hash))end
   if f.pair~=0 and comp(ped,entry.canonical_hash,f.pair)then n.remove_weapon_component_from_ped(ped,entry.canonical_hash,i32(f.pair))end
  end
 end
 if not wanted then return true,'Factory finish restored'end
 n.give_weapon_component_to_ped(ped,entry.canonical_hash,i32(wanted.hash))
 if not comp(ped,entry.canonical_hash,wanted.hash)then
  for _,hash in ipairs(previous)do n.give_weapon_component_to_ped(ped,entry.canonical_hash,i32(hash))end
  return false,'Game rejected this finish; previous components restored'
 end
 if wanted.pair~=0 and compatible(entry.canonical_hash,wanted.pair)then n.give_weapon_component_to_ped(ped,entry.canonical_hash,i32(wanted.pair))end
 if entry.model:find('_MK2',1,true)and color~=nil then
  color=math.max(0,math.min(31,math.floor(color)))
  invoker.call(0x9FE5633880ECD8ED,ped,entry.canonical_hash,i32(wanted.hash),color)
  if wanted.pair~=0 and comp(ped,entry.canonical_hash,wanted.pair)then invoker.call(0x9FE5633880ECD8ED,ped,entry.canonical_hash,i32(wanted.pair),color)end
 end
 return true,wanted.label..' applied'
end
local function read_hud()
 local ptrs={};local ok,values=pcall(function()
  for i=1,4 do ptrs[i]=pointer_int()end
  n.get_hud_colour(116,ptrs[1],ptrs[2],ptrs[3],ptrs[4])
  return {r=ptrs[1].value,g=ptrs[2].value,b=ptrs[3].value,a=ptrs[4].value}
 end)
 for _,ptr in ipairs(ptrs)do pcall(function()ptr:free()end)end
 if ok then return values end
end
function M.apply_color()
 if not M.original_color then M.original_color=read_hud();if not M.original_color then return false,'Could not save the original HUD color'end end
 local c=M.color;n.replace_hud_colour_with_rgba(116,c.r,c.g,c.b,c.a);M.applied_color={r=c.r,g=c.g,b=c.b,a=c.a}
 return true,'Wheel / shared HUD highlight color applied'
end
function M.reset_color()
 if M.original_color then
  local original=M.original_color;local current=read_hud();local last=M.applied_color
  -- Do not overwrite a later change made by another script.
  if current and last and current.r==last.r and current.g==last.g and current.b==last.b and current.a==last.a then n.replace_hud_colour_with_rgba(116,original.r,original.g,original.b,original.a)end
 end
 M.original_color=nil;M.applied_color=nil
 return true,'SPACEx wheel color override cleared'
end
function M.shutdown()M.reset_color();M.restore_all()end
function M.draw(pos,width)
 local w=require('MorpheusMouse.widgets');local theme=require('MorpheusMouse.theme')
 local y=pos.y;local h=theme.control_height and theme.control_height(28,22)or 28
 local function note(text)w.row_label(vec2(pos.x,y),text,width,nil,true,theme.colors.text_dim);y=y+h+6 end
 local function button(label,fn)
  if w.button(vec2(pos.x,y),vec2(width,h),label)then local context=require('MorpheusMouse.protection_context');context.enter_feature_call();local ok,success,msg=pcall(fn);context.leave_feature_call();M.status=ok and(msg or(success and 'Done'or 'Action failed'))or tostring(success);M.invalidate()end
  y=y+h+6
 end
 local function dropdown(id,label,options,index)local value,used=w.dropdown(vec2(pos.x,y),width,id,label,options,index);y=y+used+6;return value end
 if M.page==2 then
  w.section(vec2(pos.x,y),'WEAPON WHEEL');y=y+26
  note('Wheel colors share a HUD color with some map highlights')
  M.preset=dropdown('wheel-color-preset','Color preset',{'Emerald','Red','Purple','Cyan','Gold','Platinum','Custom'},M.preset or 1)
  local presets={{40,210,145},{215,60,70},{165,90,230},{40,205,225},{225,180,60},{175,185,200}}
  if M.preset~=M.last_preset and presets[M.preset]then local p=presets[M.preset];M.color.r=p[1];M.color.g=p[2];M.color.b=p[3]end;M.last_preset=M.preset
  for _,axis in ipairs({'r','g','b','a'})do
   M.color[axis],M.drag[axis]=w.compact_value_slider(vec2(pos.x,y),width,({r='Red',g='Green',b='Blue',a='Opacity'})[axis],M.color[axis],0,255,M.drag[axis],function(v)return tostring(math.floor(v))end)
   M.color[axis]=math.floor(M.color[axis]);y=y+h+6
  end
  button('APPLY WHEEL COLOR',M.apply_color);button('RESTORE ORIGINAL COLOR',M.reset_color)
  w.section(vec2(pos.x,y),'CARRIED WEAPONS');y=y+26
  note('Remove temporarily takes a weapon out of your loadout')
 else w.section(vec2(pos.x,y),'GUN CAMOS / FINISHES');y=y+26 end
 w.search_input(vec2(pos.x,y),vec2(width,h),'weapon-style-search',M.query,function(v)M.query=tostring(v or'');M.choice=1;M.invalidate()end,'Search your weapons');y=y+h+6
 local rows=M.entries();local labels={}
 for i,entry in ipairs(rows)do labels[i]=entry.label..(M.hidden[entry.hash_uint32]and ' (removed)'or '')end
 if #rows==0 then
  note('No matching carried weapons')
 else
  M.choice=math.min(M.choice,#rows);M.choice=dropdown('weapon-style-choice','Weapon',labels,M.choice)
  local entry=rows[M.choice]
  if M.last_weapon~=entry.hash_uint32 then M.last_weapon=entry.hash_uint32;M.tint_choice=1;M.finish_choice=1 end
  if M.page==2 then
   if M.hidden[entry.hash_uint32]then button('RESTORE WEAPON TO WHEEL',function()return M.restore(entry)end)
   else
    button('REMOVE WEAPON FROM WHEEL',function()return M.hide(entry)end)
    button('SET AS PREFERRED IN ITS WHEEL SLOT',function()n.hud_set_weapon_wheel_top_slot(entry.canonical_hash);return true,'Preferred weapon set in its existing game slot'end)
   end
  elseif M.hidden[entry.hash_uint32]then note('Restore this weapon on the Weapon Wheel page first')
  else
   local count=safe(n.get_weapon_tint_count,entry.canonical_hash)or 0
   local tints={};local metadata=styles[entry.model]or{}
   for i=0,math.min(count,64)-1 do
    local label='Tint '..i
    for _,t in ipairs(metadata.tints or{})do if t.index==i then label=t.label;break end end
    tints[#tints+1]=label
   end
   if #tints>0 then M.tint_choice=dropdown('gun-tint','Weapon tint',tints,math.min(M.tint_choice or 1,#tints));button('APPLY TINT',function()return M.tint(entry,M.tint_choice-1)end)end
   local finishes=M.finishes(entry);local names={'Factory / no cosmetic component'}
   for _,f in ipairs(finishes)do names[#names+1]=f.label end
   if #finishes>0 then
    M.finish_choice=dropdown('gun-finish','Camo / finish',names,math.min(M.finish_choice or 1,#names))
    if entry.model:find('_MK2',1,true)then
     M.camo_color,M.drag.camo=w.compact_value_slider(vec2(pos.x,y),width,'Camo color',M.camo_color or 0,0,31,M.drag.camo,function(v)return tostring(math.floor(v))end);M.camo_color=math.floor(M.camo_color);y=y+h+6
    end
    button('APPLY CAMO / FINISH',function()return M.finish(entry,finishes[(M.finish_choice or 1)-1],M.camo_color or 0)end)
   else note('This weapon has no supported cosmetic components')end
  end
 end
 if M.page==2 then button('RESTORE ALL REMOVED WEAPONS',M.restore_all)end
 note(M.status)
 return y-pos.y
end
return M

