local function later(fn)require("MorpheusMouse.frame_runtime").defer(fn)end
local function browser(key,provider)
 if states[key]then return states[key]end
 local b={path={},rows=provider(),stack={},page=1}
 function b.open_custom(label,rows)
  b.stack[#b.stack+1]={rows=b.rows,page=b.page};b.path[#b.path+1]=label;b.rows=rows;b.page=1
 end
 states[key]=b;return b
end
local function execute(b,row,direction)
 require("MorpheusMouse.menu_editors").execute(row,direction or 1,b)
end
function M.draw_rows(key,provider,pos,size)
 local b=browser(key,provider);local x,y=pos.x+12,pos.y+12;local width=size.x-24
 local height=theme.control_height and theme.control_height(36,28)or 36
 if #b.stack>0 then
  if widgets.button(vec2(x,y),vec2(95,height),"Back",nil,key.."-back")then later(function()local prev=table.remove(b.stack);table.remove(b.path);b.rows=prev.rows;b.page=prev.page end)end
  theme.text(table.concat(b.path," / ")):position(vec2(x+108,y+10)):scale(13):color(theme.colors.text_dim):wrap(width-110):draw();y=y+height+12
 end
 local rows=b.rows;local columns=width>560 and 2 or 1
 local count=math.max(2,math.floor((size.y-(y-pos.y)-70)/(height+8)))
 local page_size=columns*count;local pages=math.max(1,math.ceil(#rows/page_size));b.page=math.min(pages,b.page)
 local first=(b.page-1)*page_size+1;local column_width=(width-(columns-1)*18)/columns
 local held
 for index=first,math.min(#rows,first+page_size-1)do
  local row=rows[index];local column=math.floor((index-first)/count);local line=(index-first)%count
  local point=vec2(x+column*(column_width+18),y+line*(height+8));local checked=row.checked
  if type(checked)=="function"then local ok,v=pcall(checked);checked=ok and v or false end
  local value=row.value;if type(value)=="function"then local ok,v=pcall(value);value=ok and tostring(v)or"Unavailable"end
  local label=row.label;if row.children then label=label.."   >"end
  if value~=nil and checked==nil then label=label.."   "..tostring(value)end
  local tooltip=require("MorpheusMouse.menu_help").description(row,b.path)
  if checked~=nil then
   widgets.row_label(point,label,column_width-50)
   local clicked=widgets.toggle(vec2(point.x+column_width-38,point.y+8),18,checked,tooltip,key..index)
   if clicked then later(function()execute(b,row)end)end
  elseif row.adjust then
   widgets.row_label(point,label,column_width-90)
   for _,direction in ipairs({-1,1})do
    if widgets.button(vec2(point.x+column_width-(direction==-1 and 82 or 38),point.y),vec2(34,height),direction==-1 and"Ã¢Ë†â€™"or"+",tooltip,key..index..direction)then later(function()execute(b,row,direction)end)end
   end
  else
   if widgets.button(point,vec2(column_width,height),label,tooltip,key..index)and not row.hold then later(function()execute(b,row)end)end
  end
  if row.hold and widgets.is_mouse_within(point,vec2(column_width,height))and widgets.mouse().pressed then held=row end
 end
 if held then
  if b.held~=held or util.get_tick_count()>=(b.next_hold or 0)then b.held=held;b.next_hold=util.get_tick_count()+100;later(function()execute(b,held)end)end
 elseif b.held then if b.held.run_release then b.held.run_release()end;b.held=nil end
 y=y+count*(height+8)+8
 if pages>1 then
  if widgets.button(vec2(x,y),vec2(95,height),"Previous",nil,key.."-prev")then later(function()b.page=math.max(1,b.page-1)end)end
  theme.text(b.page.." / "..pages):position(vec2(x+110,y+10)):scale(12):color(theme.colors.text_dim):draw()
  if widgets.button(vec2(x+width-95,y),vec2(95,height),"Next",nil,key.."-next")then later(function()b.page=math.min(pages,b.page+1)end)end
 end
 return size.y
end
local function behavior_browser()
 return browser('Self/General/Behavior',function()
  local categories=require('MorpheusMouse.character_tools').rows()
  local rows=categories[2].children()
  rows[#rows+1]=categories[3]
  rows[#rows+1]=categories[4]
  return rows
 end)
end
function M.behavior_height()
 local b=behavior_browser()
 local height=theme.control_height and theme.control_height(28,22)or 28
 local gap=theme.scale_metric and theme.scale_metric(3,2)or 3
 return (#b.rows+(#b.stack>0 and 1 or 0))*(height+gap)
end
function M.draw_behavior(pos,width)
 local b=behavior_browser()
 local height=theme.control_height and theme.control_height(28,22)or 28
 local gap=theme.scale_metric and theme.scale_metric(3,2)or 3
 local y=pos.y
 if #b.stack>0 then
  if widgets.button(vec2(pos.x,y),vec2(width,height),'Back: '..table.concat(b.path,' / '),nil,'behavior-back')then
   later(function()
    local previous=table.remove(b.stack)
    table.remove(b.path)
    b.rows=previous.rows;b.page=previous.page
   end)
  end
  y=y+height+gap
 end
 for index,row in ipairs(b.rows)do
  local point=vec2(pos.x,y)
  if type(theme.is_visible)~='function'or theme.is_visible(point,vec2(width,height))then
   local checked=row.checked
   if type(checked)=='function'then local ok,value=pcall(checked);checked=ok and value or false end
   local tooltip=require('MorpheusMouse.menu_help').description(row,b.path)
   local selected=row
   if checked~=nil then
    local value=widgets.toggle_row(point,width,row.label,checked,tooltip)
    if value~=checked then later(function()execute(b,selected)end)end
   else
    local label=row.label..(row.children and '  >'or '')
    if widgets.button(point,vec2(width,height),label,tooltip,'behavior-'..index)then
     later(function()execute(b,selected)end)
    end
   end
  end
  y=y+height+gap
 end
 return y-pos.y
end

local function money_tabs()
 local tabs={{name="Apartment Heists",rows=function()return require("MorpheusMouse.controller_apartment_heists").rows()end}}
 for _,entry in ipairs(require("MorpheusMouse.controller_extra_heists").rows())do tabs[#tabs+1]={name=entry.label,rows=entry.children}end
 tabs[#tabs+1]={name="Apartment Setups",rows=function()return{{label="Instant Finish Active Setup",run=function()local ok,reason=require("MorpheusMouse.heist_suite").instant_finish("apartment_setup");if ok then require("MorpheusMouse.state").notify_info(reason)end;return ok,reason end}}end}
 return tabs
end
function M.attach(shell)
 for _,page in ipairs(shell.pages or{})do
  local panel=page.panel
  if require("MorpheusMouse.panels").loaded_title(page.title)and not panel.mouse_additions_ready then
   local additions={};local original=panel.content_draw
   if page.title=="Self"then additions={}
   elseif page.title=="Money"then additions=money_tabs()
   elseif page.title=="Session"then additions={{name="Teleport",rows=function()
 local rows=require("MorpheusMouse.controller_teleport").rows()
 for _,row in ipairs(rows)do if row.label=="Navigation & Transport"then local original=row.children;row.children=function()local filtered={};for _,entry in ipairs(original())do if entry.label~="Waypoint"and entry.label~="Players"then filtered[#filtered+1]=entry end end;return filtered end end end
 return rows end}}
   elseif page.title=="Spawning"then additions={}end
   local providers={};local existing={};for _,name in ipairs(panel.tabs or{})do existing[name]=true end
   panel.tabs=panel.tabs or{}
   for _,entry in ipairs(additions)do if not existing[entry.name]then panel.tabs[#panel.tabs+1]=entry.name;providers[entry.name]=entry.rows;existing[entry.name]=true end end
   panel.content_draw=function(self,pos,size)
    local title=self.tabs and self.tabs[self.active_tab]
    if providers[title]then return M.draw_rows(self.title.."/"..title,providers[title],pos,size)end
    if self.title=="Session"and self.active_tab==1 or self.title=="Spawning"and self.active_tab==1 then
     local carrier=self.title=="Spawning";local label=carrier and"Spawn Aircraft Carrier"or"Remove Black Screen"
     local height=theme.control_height and theme.control_height(34,28)or 34
     if widgets.button(vec2(pos.x+12,pos.y+8),vec2(math.min(size.x-24,270),height),label,nil,"mouse-addon-"..self.title)then
      later(function()require("MorpheusMouse.menu_editors").execute({label=label,run=function()if carrier then return require("MorpheusMouse.aircraft_carrier").spawn()end;return require("MorpheusMouse.black_screen_recovery").run()end},1,{})end)
     end
     local offset=height+22;local used=original(self,vec2(pos.x,pos.y+offset),vec2(size.x,math.max(1,size.y-offset)))
     return offset+(used or size.y-offset)
    end
    return original(self,pos,size)
   end
   panel.mouse_additions_ready=true
  end
 end
end
function M.player_rewards(target,pos,width)
 local id,rid=target.id,target.rockstar_id
 local function selected()
  local current=players.get(id)
  if not current or current.connected==false or current.exists==false or current.rockstar_id~=rid then error("Selected player changed",0)end
  return current
 end
 local provider=function()
  local baseline={};for _,label in ipairs({"Teleport To","Teleport Here","TP TO PLAYER","TP PLAYER TO ME","Spectate","STOP SPECTATE","Give Auto Heal To Player","Auto Heal","Semi God Mode","Off Radar","Enter Interior","JOIN CEO / MC","COPY OUTFIT","COPY VEHICLE","REPAIR VEHICLE","UPGRADE VEHICLE"})do baseline[#baseline+1]={label=label}end
  local rows=require("MorpheusMouse.player_reward_bridge").rows(selected,baseline)
  rows[#rows+1]={label="Money Drop",children=function()
   local drop=require("MorpheusMouse.player_money_drop")
   return{{label="Amount",value=function()return tostring(drop.amount)end,adjust=function(direction)drop.amount=math.max(100,math.min(2000,drop.amount+direction*100));return true end},{label="Drop Once",run=function()return drop.drop(selected(),drop.amount)end}}
  end}
  rows[#rows+1]=require("MorpheusMouse.player_reward_bridge").drops(selected)
  return rows
 end
 widgets.section(pos,"REMOTE REWARDS")
 local height=M.draw_rows("player-rewards-"..id.."-"..tostring(rid),provider,vec2(pos.x,pos.y+24),vec2(width,500))
 return pos.y+24+height
end
function M.cleanup()
 local tools=package.loaded["MorpheusMouse.character_tools"];if tools then tools.shutdown()end
 for _,b in pairs(states)do if b.held and b.held.run_release then pcall(b.held.run_release)end end
 states={}
end
return M

end
