local M={index=0}
local native=require("natives")
local last={}
-- Enhanced 1158.16 freemode: event 968269233 -> func_24811 (8 slots)
-- -> func_8498(type,index,collected,notification,false). Type 2 has two chests.
function M.send(player)
 local profile=require("MorpheusMouse.heist_profiles").current();if not profile or profile.edition~="Enhanced"then return false,"Collectible test requires the verified Enhanced build"end
 local id=player and tonumber(player.id)
 if not id or id~=math.floor(id) or id<0 or id>31 or player.connected==false or player.exists==false then return false,"Selected player is unavailable"end
 if type(players.get)~="function"then return false,"Player identity check is unavailable"end
 local ok,current=pcall(players.get,id)
 if not ok or not current or current.rockstar_id~=player.rockstar_id or current.connected==false or current.exists==false then return false,"Selected player changed or disconnected"end
 if M.index~=0 and M.index~=1 then return false,"Chest index must be 0 or 1"end
 if type(pointer_scr_value)~="function" or type(native.trigger_script_event)~="function"then return false,"Native script event API is unavailable"end
 local tick=util.get_tick_count();local key=tostring(id)..":"..tostring(player.rockstar_id)
 if last[key] and tick-last[key]<5000 then return false,"Wait five seconds between collectible requests"end
 local mask=1<<id;local payload={968269233,id,mask,2,M.index,1,0,1}
 local buffer=pointer_scr_value(8)
 if not buffer then return false,"Event buffer allocation failed"end
 local sent,err=pcall(function()
  local address=buffer:address()
  for i,value in ipairs(payload)do address:add((i-1)*8).int64=value end
  native.trigger_script_event(1,buffer,8,mask)
 end)
 pcall(function()buffer:free()end)
 require("MorpheusMouse.diagnostics").event("remote_reward",sent and "treasure_event_requested" or "treasure_event_failed",{recipient=require("MorpheusMouse.diagnostics").player_token(player),index=M.index,event_hash=968269233,slots=8,reason=sent and "Request sent; check the recipient's reward" or tostring(err)})
 if not sent then return false,"Collectible event failed; diagnostic recorded"end
 last[key]=tick
 require("MorpheusMouse.state").notify_info("Treasure Chest request sent. Ask the recipient to check their reward.")
 return true
end
function M.rows(get_player)
 return {
 {label="Chest",value=function()return tostring(M.index+1).." / 2"end,adjust=function(direction)M.index=(M.index+(direction<0 and -1 or 1))%2;return true end},
 {label="Send Treasure Chest Once (Test)",run=function()return M.send(get_player())end}
 }
end
return M

end

