local owner="player_money_drop"
local pickup=joaat("PICKUP_MONEY_VARIABLE")
local model=joaat("prop_money_bag_01")
local function same_hash(value)return tonumber(value)~=nil and tonumber(value)%4294967296==tonumber(pickup)%4294967296 end
local function exists(handle)return handle and handle~=0 and n.does_entity_exist(handle)end
local function remove(handle,entry)
 if entry and entry.replica_slot then pcall(function()local slot=entry.replica_slot;if same_hash(script.globals(slot).int32) and script.globals(slot+4).int32==handle then script.globals(slot).int32=123 end end)end
