 if entry and entry.pickup_handle and n.does_pickup_exist(entry.pickup_handle)then pcall(n.remove_pickup,entry.pickup_handle)end
 if exists(handle)then
  pcall(n.set_entity_as_mission_entity,handle,true,true)
  pcall(n.network_request_control_of_entity,handle)
  local ptr=pointer_int();ptr.value=handle;pcall(n.delete_entity,ptr);ptr:free()
 end
 context.release_entity(handle,owner)
end
local function sweep()
 local now=util.get_tick_count()
 for index=#M.objects,1,-1 do local entry=M.objects[index]
  if not exists(entry.handle)or now-entry.created>=30000 then remove(entry.handle,entry);table.remove(M.objects,index)end
 end
 if #M.objects==0 and M.worker then local id=M.worker;M.worker=nil;threads.stop(id,"money_pickups_expired")end
end
local function target(expected)
 local p=expected and players.get(expected.id)
 if not p or p.connected==false or p.exists==false or p.rockstar_id~=expected.rockstar_id then return nil,"Selected player changed or left"end
 if not exists(p.ped)then return nil,"Selected player must be nearby and streamed in"end
 local c=p.coords;local local_player=players.me();local local_coords=local_player and local_player.coords
 if not c or not local_coords then return nil,"Player coordinates unavailable"end
 local x,y,z=tonumber(c.x),tonumber(c.y),tonumber(c.z)
 if not x or not y or not z or x~=x or y~=y or z~=z then return nil,"Invalid player coordinates"end
 if(x-local_coords.x)^2+(y-local_coords.y)^2+(z-local_coords.z)^2>40000 then return nil,"Selected player must be within 200 metres"end
 return p
end
