package.preload["MorpheusMouse.script_host_manager"]=function(...)
local catalog={"freemode"}
local jobs=require("MorpheusMouse.job_runtime")
local M={active=false,worker_running=false,generation=0,last_error=nil,status="Stopped",owned=0,rejected=0}
local excluded={social_controller=true}
local retries={}
local ready_at=nil
local session_host=nil
local worker_token=nil
local function now()return tonumber(util.get_tick_count())or 0 end
local function report(name,reason)
 M.last_error=tostring(name)..": "..tostring(reason)
 pcall(function()require("MorpheusMouse.diagnostics").event("script_host","request_rejected",{module=name,error=reason})end)
end
local function reset_session()
 ready_at=nil;session_host=nil;retries={};M.owned=0;M.rejected=0
end
local function ready()
 if game.is_session_free_roam()~=true then reset_session();M.status="Waiting for GTA Online Freemode";return false end
 local host=game.host();local host_id=host and tonumber(host.id)
 if not host_id then M.status="Waiting for session host";return false end
 local tick=now()
 if host_id~=session_host or not ready_at or tick<ready_at-750 then
  retries={};session_host=host_id;ready_at=tick+750
 end
 if tick<ready_at then M.status="Waiting for session to settle";return false end
 if not script.running("freemode")or not script.host("freemode")then M.status="Waiting for Freemode script";return false end
 return true
end
local function owns(name,player_id)
 local ok,host=pcall(script.host,name)
 return ok and host~=nil and tonumber(host.id)==player_id
end
function M.start()
 if M.active then return true end
 if type(script)~="table"or type(script.force_host)~="function"or type(script.host)~="function"then
  M.last_error="Lexis script host API is unavailable";return false,M.last_error
 end
 M.generation=M.generation+1;local token=M.generation
 reset_session();M.active=true;M.last_error=nil;M.status="Starting host maintenance"
 worker_token=token;M.worker_running=true
 local queued,queue_error=pcall(util.create_job,function()
  local ok,err=jobs.run(function()
   while M.active and M.generation==token do
    if ready()then
     local me=players.me();local player_id=me and tonumber(me.id)
     local owned,rejected=0,0
     if player_id then
      for index,name in ipairs(catalog)do
       if not M.active or M.generation~=token then break end
       if not excluded[string.lower(name)]then
        local running_ok,running=pcall(script.running,name)
        if running_ok and running==true then
         if owns(name,player_id)then owned=owned+1;retries[name]=nil
         else
          local tick=now();local retry=retries[name]
          if not retry or tick>=retry.next_tick or tick<retry.tick then
           local called,result=pcall(script.force_host,name)
           if not M.active or M.generation~=token then break end
           if owns(name,player_id)then owned=owned+1;retries[name]=nil
           else
            local attempts=math.min(4,(retry and retry.attempts or 0)+1)
            retries[name]={attempts=attempts,tick=now(),next_tick=now()+math.min(120000,15000*2^(attempts-1))}
            report(name,called and(result==true and"Host request accepted, but ownership was not granted"or"Lexis rejected host request")or tostring(result))
            rejected=rejected+1
           end
          else rejected=rejected+1 end
         end
        else retries[name]=nil end
       end
       if index%32==0 then jobs.yield();if not ready()then break end end
      end
      if M.active and M.generation==token then
       M.owned=owned;M.rejected=rejected
       M.status=tostring(owned).." script hosts held; "..tostring(rejected).." unavailable or waiting to retry"
       if rejected==0 then M.last_error=nil end
      end
     else M.status="Waiting for local player"end
    end
    jobs.yield(2000)
   end
  end)
  if worker_token==token then
   M.worker_running=false;worker_token=nil
   if not ok then M.active=false;M.last_error=tostring(err);M.status="Host maintenance stopped: "..tostring(err)end
  end
 end)
 if not queued then
  if worker_token==token then M.worker_running=false;worker_token=nil;M.active=false end
  M.last_error=tostring(queue_error);M.status="Host maintenance could not start"
  return false,M.last_error
 end
 return true
end
function M.stop()
 M.active=false;M.generation=M.generation+1;reset_session();M.status="Stopped"
 return true
end
function M.count()return #catalog end
return M
end


