package.preload["MorpheusMouse.nebula_toasts"]=function(...)
local M={}
local function clamp(v)return math.max(0,math.min(1,v))end
function M.draw(theme,pos,size,toast,now,motion)
 local x,y,w,h=pos.x,pos.y,size.x,size.y
 local scale=w/320
 local radius=math.max(4,8*scale)
 local accent=theme.colors.accent
 if require('MorpheusMouse.galaxy_background').draw(pos,size,radius)then
  theme.draw_rect(pos,size,color(5,7,12,145),radius)
 else theme.draw_rect(pos,size,color(18,18,18,255),radius)end
 -- Shared galaxy art and royal-blue detail; severity retains its side marker.
 theme.draw_rect(vec2(x+6*scale,y+31*scale),vec2(math.max(1,w-12*scale),math.max(1,h-38*scale)),color(5,7,12,65),4*scale)
 local sx,sy=x+25*scale,y+18*scale
 local white=color(240,244,255,235)
 gui.line(vec2(sx-6*scale,sy),vec2(sx+6*scale,sy),math.max(1,scale),white)
 gui.line(vec2(sx,sy-9*scale),vec2(sx,sy+9*scale),math.max(1,scale),white)
 gui.line(vec2(sx-3*scale,sy-4*scale),vec2(sx+3*scale,sy+4*scale),math.max(1,scale),white)
 local remaining=clamp((toast.expires_at_ms-now)/math.max(1,toast.duration_ms))
 local inset=8*scale
 local track=math.max(1,w-inset*2)
 theme.draw_rect(vec2(x+inset,y+h-4*scale),vec2(track,2*scale),color(82,119,239,35),scale)
 if remaining>0 then theme.draw_rect(vec2(x+inset,y+h-4*scale),vec2(track*remaining,2*scale),accent,scale)end
 theme.draw_rect(vec2(x,y+8*scale),vec2(2*scale,math.max(1,h-16*scale)),toast.accent,scale)
 theme.draw_outline(pos,size,math.max(1,scale),theme.colors.border_strong,radius)
end
return M
