  if wanted[op.receiver_name]then
   local ok,value=pcall(function()return account.stats(op.hash).bool end)
   if not ok or value~=true then return false,"Masterminds award not confirmed: "..op.receiver_name..". Complete the three award writes first."end
   wanted[op.receiver_name]=false;count=count+1
  end
 end
 if count~=3 then return false,"The three Masterminds receivers were not found."end
 local ok,result=pcall(function()
  if invoker.call(0x867365E111A3B6EB,77).bool then return "GTA already reports Masterminds as unlocked."end
  local accepted=invoker.call(0xBEC7076D64130195,77).bool
  if invoker.call(0x867365E111A3B6EB,77).bool then return "GTA confirms Masterminds is unlocked. Check your launcher achievement list."end
