function f.unlock_anniversary_finishes()
 return uc("10th Anniversary weapon finishes",function(profile)
  if profile.edition~="Enhanced"or profile.game_version~="1158.16"or profile.online_version~="1.73"then return nil,"Requires Enhanced 1158.16 / Online 1.73"end
  return yc({41657,41658,41659})
 end)
end
function f.unlock_bennys_access()
 return uc("Benny's conversion access",function(profile,character)
  local plan=bc()
  for _,op in ipairs(profile.lsc.standard_progress)do
   if op.kind==u and op.category==2 and op.index==174 and op.target==true then
    local ok,reason=jc(plan,op,character)
    if not ok then return nil,reason end
    return plan
   end
  end
  return nil,"The current Benny's conversion access receiver was not found"
 end,"vehicles")
end
function f.unlock_imported_awards(key)
 local spec=imported_awards[key]
 if not spec then return false,"Unknown imported award category"end
 return uc(spec.label,function(profile,character)
  if profile.edition~="Enhanced"then return nil,"These award shortcuts require the current Enhanced profile"end
  local valid,reason=Uc(profile)if not valid then return nil,reason end
  local plan=bc();plan.defer_receiver_verification=true;plan.stat_commit=true
  local thresholds={}
  for _,wanted in ipairs(spec.entries)do
   local found
   for _,entry in ipairs(profile.awards[wanted.group]or{})do
    if entry.mp0_hash==wanted.mp0 and entry.mp1_hash==wanted.mp1 and entry.kind==wanted.kind then
     if found then return nil,"Duplicate current award receiver: "..wanted.name end
     found=entry
    end
   end
   if not found then return nil,"Current award receiver missing: "..wanted.name end
   local hash=character==0 and found.mp0_hash or found.mp1_hash
   if found.kind=="bool"then
    cc(plan,{kind=w,hash=hash,verify_receiver=true,receiver_name=found.receiver_name})
   else
    local target=found.target
    if found.threshold_offset then target,reason=Vc(found.threshold_offset,thresholds);if not target then return nil,reason end end
    if found.receiver_name then
     local op;op,reason=Wc(found,character);if not op then return nil,reason end
     if target~=op.target then return nil,"Retained award threshold changed: "..wanted.name end
     cc(plan,op)
    else
     cc(plan,{kind=x,hash=hash,target=target,verify_receiver=true})
    end
   end
  end
  return plan
 end)
end
function f.unlock_bottom_dollar_rewards()
 if f.job or f.daily_busy then return false,"Wait for the current unlock category to finish"end
 local profile,character,reason=ab();if not profile then return false,reason end
 if profile.edition~="Enhanced"or profile.game_version~="1158.16"or profile.online_version~="1.73"then return false,"Requires Enhanced 1158.16 / Online 1.73"end
 if not game.in_game()or not game.is_session_free_roam()then return false,"Use this unlock in Online Freemode"end
 if not script or type(script.tunables)~="function"then return false,"Lexis tunables API is unavailable"end
 local objects,previous={},{}
 local ok,reason=pcall(function()
  for i,hash in ipairs({-1452302247,1061782255,-1512453020,487403442,300610467,1936578614,580337879,-1637028023,-953799766,2139299188,-376598480,1439394348,807736696,-767449433,-1561926114,-1936538377,-826757275,-1879560376,-1505253725,955673748,358648550,1394658025,-1477664969,501707951,2083260032,1395008153,57795340,1395848952,409746519,756332839,141612725,-1373380263,-546616250})do
   local object=script.tunables(hash)
   assert(object and type(object.bool)=="boolean","Cannot read Bottom Dollar reward toggle "..hash)
   objects[i]=object;previous[i]=object.bool
  end
  for i,object in ipairs(objects)do
   assert(account.character()==character and game.is_session_free_roam(),"Session or character changed")
   object.bool=true
   assert(object.bool==true,"Bottom Dollar reward toggle did not read back")
  end
 end)
 if not ok then
  local restored=true
  for i,object in ipairs(objects)do local success=pcall(function()object.bool=previous[i];assert(object.bool==previous[i])end);restored=restored and success end
  return false,tostring(reason)..(restored and "; previous reward toggles restored"or "; some reward toggles could not be restored")
 end
 local note="33 Bottom Dollar reward toggles enabled. Stay in freeroam while GTA grants the clothing and masks."
 require("MorpheusMouse.state").notify_info(note)
 return true,note
end
-- Enhanced 1158.16 / Online 1.73, traced from current freemode.c:
-- func_8595 enqueues an objective ID; func_17500 drains the queue;
-- func_17502 sets its live completion flag and character bool 169..171.
local daily_busy=false
local daily_base=2359296+1+681+4248+1
local daily_queue=1574746
local function daily_guard(character)
 local profile,slot,reason=ab()
 assert(profile,reason)
 assert(profile.edition=="Enhanced"and profile.game_version=="1158.16"and profile.online_version=="1.73","Daily completion requires Enhanced 1158.16 / Online 1.73")
 assert(slot==character,"Character changed during daily completion")
 assert(script.running("freemode")and game.in_game()and game.is_session_free_roam(),"Use daily completion in Online Freemode")
 assert(script.globals(262145+9177).int32==0,"Daily Objectives are disabled by the current game configuration")
end
local function daily_read(character)
 daily_guard(character)
 assert(script.globals(daily_base-1).int32==3 and script.globals(daily_queue+1).int32==3,"Daily objective array layout did not match")
 local snapshot={items={},confirmed=0,day=script.globals(daily_base-2).int32}
 assert(type(snapshot.day)=="number"and snapshot.day>0,"Daily objectives have not initialized")
 for i=0,2 do
  local id=script.globals(daily_base+i*3).int32
  local done=script.globals(daily_base+i*3+1).int32
  assert(type(id)=="number"and id==math.floor(id)and id>=0 and id<512,"Today's objective IDs have not initialized")
  assert(done==0 or done==1,"Daily objective completion flag is invalid")
  local hash=invoker.call(0xD69CE161FE614531,2,169+i,character).int
  assert(type(hash)=="number"and hash~=0,"Cannot resolve current daily completion stat")
  local persisted=account.stats(hash).bool
  assert(type(persisted)=="boolean","Cannot read current daily completion stat")
  snapshot.items[i+1]={id=id,done=done==1,persisted=persisted}
  if done==1 and persisted then snapshot.confirmed=snapshot.confirmed+1 end
 end
 return snapshot
end
local function daily_unchanged(before,after)
 if before.day~=after.day then return false end
 for i=1,3 do if before.items[i].id~=after.items[i].id then return false end end
 return true
end
function f.complete_todays_objectives()
 if f.job or daily_busy then return false,"Another unlock action is running"end
 local profile,character,reason=ab();if not profile then return false,reason end
 local ok,before=pcall(daily_read,character);if not ok then return false,tostring(before)end
 if before.confirmed==3 then return true,"GTA already confirms all three of today's objectives complete"end
 if script.globals(daily_queue).int32~=0 then return false,"GTA is processing an objective. Wait a moment and try again"end
 for i=0,2 do if script.globals(daily_queue+2+i).int32~=-1 then return false,"The game's daily objective queue is busy"end end
 daily_busy=true;f.daily_busy=true
 local queued,reason=pcall(util.create_job,function()
  local submitted={}
  local success,result=pcall(function()
   local current=daily_read(character)
   assert(daily_unchanged(before,current),"Today's objectives changed before submission")
   assert(script.globals(daily_queue).int32==0,"GTA's daily objective queue became busy")
   for i=0,2 do assert(script.globals(daily_queue+2+i).int32==-1,"GTA's daily objective queue became busy")end
   for i,item in ipairs(current.items)do
    if not item.done then
     local index=daily_queue+1+i
     submitted[index]=item.id
     script.globals(index).int32=item.id
     assert(script.globals(index).int32==item.id,"Objective request did not read back")
    end
   end
   assert(next(submitted)~=nil,"Live objective flags are complete but their saved flags disagree. Change sessions and check again")
   script.globals(daily_queue).int32=1
   assert(script.globals(daily_queue).int32==1,"Daily objective trigger did not read back")
   for attempt=1,40 do
    require("MorpheusMouse.job_runtime").yield(200)
    local after=daily_read(character)
    assert(daily_unchanged(before,after),"Today's objectives changed while waiting for GTA")
    if after.confirmed==3 then return "GTA confirms all three of today's objectives complete. Check the Daily Objectives list"end
   end
   local after=daily_read(character)
   error("GTA confirmed "..after.confirmed.."/3 objectives after 8 seconds; completion was not confirmed",0)
  end)
  if not success then
   -- Withdraw only requests still owned by this action. Never undo completed
   -- objectives or alter a new session/day's queue.
   pcall(function()
    local current=daily_read(character)
    if not daily_unchanged(before,current)then return end
    for index,id in pairs(submitted)do if script.globals(index).int32==id then script.globals(index).int32=-1 end end
    local empty=true
    for i=0,2 do if script.globals(daily_queue+2+i).int32~=-1 then empty=false end end
    if empty then script.globals(daily_queue).int32=0 end
   end)
  end
  daily_busy=false;f.daily_busy=false
  print("SPACEx daily objective verification | "..tostring(result))
  local state=require("MorpheusMouse.state")
  if success then state.notify_info(result)else state.notify_warning(tostring(result):gsub("^.-:%d+:%s*",""))end
 end)
 if not queued then daily_busy=false;f.daily_busy=false;return false,tostring(reason)end
 return true,"Today's objectives submitted to GTA; waiting for completion flags"
end

function f.verify_imported_unlocks()
 if f.job or daily_busy then return false,"Wait for the active unlock action to finish before verifying"end
 local profile,character,reason=ab();if not profile then return false,reason end
 if profile.edition~="Enhanced"then return false,"This verification requires the current Enhanced profile"end
 local valid,reason=Uc(profile);if not valid then return false,reason end
 local summary={}
 local totals={groups=0,passed=0,daily="unavailable"}
 local function record(label,passed,total)
  local line=label..": "..passed.."/"..total
  summary[#summary+1]=line
  if label=="Today's objectives"then totals.daily=passed.."/"..total
  else totals.groups=totals.groups+1;if passed==total then totals.passed=totals.passed+1 end end
  print("SPACEx unlock verification | "..line)
 end
 local function packed(indices)
  local count=0
  for _,index in ipairs(indices)do
   local value=invoker.call(0xDA7EBFC49AE3F1B0,index,character).bool
   assert(type(value)=="boolean","Cannot read packed flag "..index)
   if value then count=count+1 end
  end
  return count
 end
 local ok,reason=pcall(function()
  record("Anniversary flags",packed({41657,41658,41659}),3)
  record("Bottom Dollar grant flags",packed({51215,51216,51217,51218,51219,51220,51221,51222,51223,51225,51226,51227,51228,51229,51230,51231,51232,51233,51234,51235,51236,51237,51238,51239,51240,51241,51242,51243,51244,51245,51246,51247}),32)
  local bennys_hash=invoker.call(0xD69CE161FE614531,2,174,character).int
  assert(type(bennys_hash)=="number"and bennys_hash~=0,"Cannot resolve Benny's access flag")
  local bennys=account.stats(bennys_hash).bool
  assert(type(bennys)=="boolean","Cannot read Benny's access flag")
  record("Benny's access",bennys and 1 or 0,1)
  for _,key in ipairs({"contract","arena","arcade","drug_wars","daily"})do
   local spec=imported_awards[key]
   local passed,total=0,0
   for _,wanted in ipairs(spec.entries)do
    local found
    for _,entry in ipairs(profile.awards[wanted.group]or{})do
     if entry.mp0_hash==wanted.mp0 and entry.mp1_hash==wanted.mp1 then found=entry;break end
    end
    assert(found,"Current award receiver missing: "..wanted.name)
    local hash=character==0 and found.mp0_hash or found.mp1_hash
    local confirmed=false
    if found.kind=="bool"then
     local value=account.stats(hash).bool
     assert(type(value)=="boolean","Cannot read award "..wanted.name)
     confirmed=value
    else
     local target=found.target
     if found.threshold_offset then target,reason=Vc(found.threshold_offset,{});assert(target,reason)end
     local out=pointer_int()
     local read_ok,result=pcall(a.stat_get_int,hash,out,-1)
     local value=out.value;out:free()
     assert(read_ok and(result==true or result==1)and type(value)=="number","Cannot read award "..wanted.name)
     confirmed=value>=target
    end
    total=total+1
    if confirmed then passed=passed+1 else print("SPACEx unlock verification | pending receiver | "..wanted.name)end
   end
   record(spec.label,passed,total)
  end
  local daily_ok,daily=pcall(daily_read,character)
  if daily_ok then record("Today's objectives",daily.confirmed,3)else print("SPACEx unlock verification | Today's objectives unavailable | "..tostring(daily))end
 end)
 if not ok then return false,"Verification stopped: "..tostring(reason)end
 require("MorpheusMouse.state").notify_info(totals.passed.."/"..totals.groups.." unlock groups have matching flags/counters. Today's objectives: "..totals.daily..". Details in Lexis log.")
 return true,"Read-only verification finished; see Lexis log for missing flags. Shop inventory and trophy visuals still need checking in-game"
end

function f.imported_unlock_rows()
 local rows={
  {label="10th Anniversary Weapon Finishes",run=f.unlock_anniversary_finishes},
  {label="Bottom Dollar Clothing and Masks",run=f.unlock_bottom_dollar_rewards},
  {label="Benny's Conversion Access",run=f.unlock_bennys_access}
 }
 for _,key in ipairs({"contract","arena","arcade","drug_wars","daily"})do
  local selected=key
  rows[#rows+1]={label=imported_awards[key].label,run=function()return f.unlock_imported_awards(selected)end}
 end
 rows[#rows+1]={label="Complete Today's Daily Objectives",run=f.complete_todays_objectives}
 rows[#rows+1]={label="Verify New Unlock Status",run=f.verify_imported_unlocks}
