package.preload["MorpheusMouse.ui_motion"]=function(...)
local M={dt=1/60,last=nil}
function M.begin_frame()
 local now=util.get_tick_count()
 if M.last then M.dt=math.max(1/240,math.min(.05,(now-M.last)/1000))end
 M.last=now
end
function M.factor(rate)return 1-math.exp(-(rate or 26)*M.dt)end
function M.scroll(current,target,animated)
 if not animated or math.abs(target-current)<.25 then return target end
 return current+(target-current)*M.factor(32)
end
return M

end
