package.preload["MorpheusMouse.autoshop_preps"]=function(...)
local M={}
local function report(event,data)
 pcall(function()require("MorpheusMouse.diagnostics").event("autoshop",event,data)end)
end
local function apply(expected)
 local profile=require("MorpheusMouse.heist_profiles").current()
 if not profile or profile.edition~="Enhanced"then return false,"Unsupported Auto Shop game build"end
 local char=account.character()
 if char~=0 and char~=1 then return false,"Character is unavailable"end
 local prefix="MP"..char.."_"
 local named=account.stats(prefix.."TUNER_GEN_BS")
 local me=players.me()
 local pid=me and tonumber(me.id)
 if not pid or pid<0 or pid>31 or pid~=math.floor(pid)then return false,"Local player is unavailable"end
 -- Current tuner_planning.func_24/26 and freemode mirror from stat keys 9621/9618.
 local base=1985024+1+pid*149
 local current=script.globals(base+4).int32
 local before=script.globals(base+1).int32
 report("board_state",{player=pid,character=char,selected=expected,contract=current,flags=before,named_flags=named.int32})

 if type(before)~="number"or type(current)~="number"then return false,"Auto Shop progress could not be read"end
 -- Current tuner_planning: bit 1 = contract selected,
 -- bits 2 and 3 = the two prep completions. Preserve every other bit.
 if (before & 2)==0 or current~=expected then return false,"Select the same contract on the actual board first; no stats changed"end
 local native=require("natives")
 local lookup=native.get_stat_hash_for_character_stat or native._get_stat_hash_for_character_stat
 if type(lookup)~="function"then return false,"Indexed stat lookup is unavailable; no stats changed"end
 -- tuner_planning.func_451 and freemode.func_27083 resolve progress key 9618.
 local resolved,hash=pcall(lookup,0,9618,char)
 if not resolved or type(hash)~="number"or hash==0 then return false,"Auto Shop indexed stat could not be resolved; no stats changed"end
 local stat=account.stats(hash)
 local canonical=stat.int32
 report("indexed_stat",{key=9618,character=char,value=canonical,board=before})
 if canonical~=before then return false,"Indexed progress does not match the board; no stats changed; diagnostic recorded"end
 local desired=before | 12
 if desired==before then return true,"Both Auto Shop preps are already marked complete; reopen the board"end
 report("prep_snapshot",{character=char,contract=current,before=before,desired=desired})
 local ok,err=pcall(function()stat.int32=desired end)
 if not ok then report("prep_write_error",{reason=tostring(err)});return false,"Auto Shop stat write failed; diagnostic recorded"end
 for attempt=1,10 do
  if account.character()~=char then return false,"Character changed while verifying; no further writes made"end
  if script.globals(base+4).int32~=current then return false,"Active contract changed; no further writes made"end
  local actual=script.globals(base+1).int32
  if type(actual)=="number"and (actual & 12)==12 then
   if (actual & ~12)~=(before & ~12)then
    report("prep_concurrent_change",{before=before,actual=actual})
    return false,"Auto Shop progress changed during verification; reopen the board before retrying"
   end
   report("prep_verified",{contract=current,before=before,actual=actual})
   return true,"Both prep flags verified; close and reopen the contract board"
  end
  if type(util)=="table"and type(util.yield)=="function"then util.yield(100)end
 end
 report("prep_unconfirmed",{contract=current,before=before,actual=stat.int32})
 return false,"Auto Shop prep write was not retained; diagnostic recorded"
end
local busy=false
function M.complete(expected)
 if busy then return false,"Auto Shop prep verification is already running"end
 busy=true
 local queued,reason=pcall(util.create_job,function()
  local ran,ok,detail=pcall(apply,expected)
  busy=false
  if not ran then detail=tostring(ok);ok=false end
  report("prep_job_finished",{success=ok==true,reason=detail})
  local state=require("MorpheusMouse.state")
  if ok then state.notify_info(detail)else state.notify_error(detail or "Auto Shop prep verification failed")end
 end)
 if not queued then busy=false;return false,"Could not schedule Auto Shop prep verification: "..tostring(reason)end
 return true,"Auto Shop prep verification started"
end
return M

end

package.preload["MorpheusMouse.character_tools"]=function(...)
local M={enabled={},clear_immediately=false,controllable=true,worker=nil,stopped=false}
local native=require("natives")
local snapshots={}
local flags={oxygen={[3]=false,[4]=false},indoor_sprint={[427]=true},fall_ragdoll={[164]=true}}
local animations={
 {"Salute","anim@mp_player_intuppersalute","idle_a"},
 {"Wave","anim@mp_player_intcelebrationmale@wave","wave"},
 {"Push-ups","amb@world_human_push_ups@male@base","base"},
 {"Sit-ups","amb@world_human_sit_ups@male@base","base"}
}
local scenarios={
 {"Stand Guard","WORLD_HUMAN_GUARD_STAND"},
 {"Clipboard","WORLD_HUMAN_CLIPBOARD"},
 {"Binoculars","WORLD_HUMAN_BINOCULARS"},
 {"Musician","WORLD_HUMAN_MUSICIAN"},
 {"Picnic","WORLD_HUMAN_PICNIC"}
}
local function ped()
 local me=players.me();local p=me and me.ped
 if not p or p==0 or not native.does_entity_exist(p)then error("Local character is unavailable",0)end
 return p
end
local function model(p)
 if type(native.get_entity_model)=="function"then return native.get_entity_model(p)end
 return invoker.call(0x9F47B058362C84B5,p).int
end
local function living()
 if M.stopped then error("Character tools have been unloaded",0)end
 local p=ped()
 if native.is_entity_dead(p,false)then error("Wait until your character has respawned",0)end
 return p
end
local function restore(p,key)
 local saved=snapshots[p]and snapshots[p][key]
 if not saved then return end
 if native.does_entity_exist(p)then
  for flag,value in pairs(saved)do native.set_ped_config_flag(p,flag,value)end
 end
 snapshots[p][key]=nil
 if next(snapshots[p])==nil then snapshots[p]=nil end
end
local function apply_flags(p,key)
 snapshots[p]=snapshots[p]or{}
 if not snapshots[p][key]then
  local before={}
  for flag in pairs(flags[key])do before[flag]=native.get_ped_config_flag(p,flag,true)==true end
  snapshots[p][key]=before
 end
 for flag,value in pairs(flags[key])do native.set_ped_config_flag(p,flag,value)end
end
function M.tick()
 if M.stopped then M.worker=nil;return false end
 local any=false;for _,on in pairs(M.enabled)do if on then any=true end end
 if not any then M.worker=nil;return false end
 local me=players.me();local p=me and me.ped
 if not p or p==0 or not native.does_entity_exist(p)then return end
 local stale={};for old in pairs(snapshots)do if old~=p then stale[#stale+1]=old end end
 for _,old in ipairs(stale)do for key in pairs(flags)do restore(old,key)end end
 if native.is_entity_dead(p,false)then return end
 if M.enabled.semi_god then
  local health=native.get_entity_health(p);local maximum=native.get_entity_max_health(p)
  if health>0 and health<maximum then native.set_entity_health(p,maximum)end
 end
 for key in pairs(flags)do if M.enabled[key]then apply_flags(p,key)end end
end
function M.set_enabled(key,on)
 if M.stopped then return false,"Character tools have been unloaded"end
 if key~="semi_god"and not flags[key]then return false,"Unknown character option"end
 on=on==true
 if on then living()end
 M.enabled[key]=on
 if not on then local list={};for p in pairs(snapshots)do list[#list+1]=p end;for _,p in ipairs(list)do restore(p,key)end end
 if on and not M.worker then
  local worker=require("MorpheusMouse.runtime_threads").start("character_tools",M.tick,{interval_ms=100,on_error=function(reason)
   M.shutdown();require("MorpheusMouse.state").notify_error("Character tools stopped: "..tostring(reason))
  end})
  if not worker then M.enabled[key]=false;return false,"Could not start character tools worker"end
  M.worker=worker
 end
 return true
end
local function toggle(label,key,description)
 return{label=label,description=description,checked=function()return M.enabled[key]==true end,run=function()return M.set_enabled(key,not M.enabled[key])end}
end
local function option(label,key)
 return{label=label,checked=function()return M[key]end,run=function()M[key]=not M[key];return true end}
end
function M.stop_actions()
 local p=living()
 if M.crouched_ped and native.does_entity_exist(M.crouched_ped)then native.reset_ped_movement_clipset(M.crouched_ped,0.25)end
 M.crouched_ped=nil;M.active_scenario=nil
 if M.active_animation then native.remove_anim_dict(M.active_animation);M.active_animation=nil end
 if M.clear_immediately then native.clear_ped_tasks_immediately(p)else native.clear_ped_tasks(p)end
 return true
end
local function load_asset(request,loaded,name)
 request(name);local deadline=util.get_tick_count()+3000
 while not loaded(name)do
  if M.stopped then return false,"Character tools were unloaded"end
  if util.get_tick_count()>=deadline then return false,"Animation asset did not load"end
  require("MorpheusMouse.job_runtime").yield(0)
