  end)
  if not ok then
   M.movement=false;M.weapons=false
   state.notify_warning("Interior controls stopped: "..tostring(blocked))
   return hook.scripts.continue
  end
  if blocked and not state.is_open and not state.background_input_blocked()and(hash==0xFE99B66D079CF6BC or hash==0x5E6CC07646BBEAB8)then
   M.blocks=M.blocks+1
