  return hook.scripts.continue
 end
 for _,id in ipairs({hash,script_hashes[hash]})do
  local ok,handle=pcall(hook.native,id,0,{pre=function(call)trace_registration(hash,id);return callback(call)end,post=function(call)repair_after_native(hash,call)end})
