 end
end
local function install()
 if installed then return end
 if type(hook)~="table"or type(hook.native)~="function"then
  M.rejected=1;M.last_rejection="Lexis native hooks unavailable; per-frame controls only.";installed=true;return
 end
 add(0xFE99B66D079CF6BC,function(p)
  local group=p[0].int32;local control=p[1].int32
  return (group==0 or group==2)and p[2].bool and ((M.movement and movement_controls[control])or(M.weapons and weapon_controls[control]and(control<12 or control>17 or wheel_requested())))
 end)
 add(0xA01B8075D8B92DF4,function(p,ped,player)return M.movement and p[0].int32==player and not p[1].bool end)
 add(0x433083750C5E064A,function(p,ped)return M.movement and p[0].int32==ped and p[1].float<3.0 end)
 add(0xC1E8A365BF3B29F2,function(p,ped)
  local flag=p[1].int32
  return M.movement and p[0].int32==ped and p[2].bool and (flag==102 or flag==124 or flag==362)
 end)
 add(0x5E6CC07646BBEAB8,function(p,ped,player)return M.weapons and p[0].int32==player and p[1].bool end)
 add(0xED7F7EFE9FABF340,function(p,ped)return M.weapons and p[0].int32==ped and not p[1].bool end)
 -- Reject script-forced holstering, but leave manual weapon-wheel holstering available.
 add(0xADF692B254977C0C,function(p,ped)
  return M.weapons and p[0].int32==ped and (p[1].uint32 & 0xFFFFFFFF)==0xA2719263 and (not wheel_selection or (wheel_selection & 0xFFFFFFFF)~=0xA2719263)and not native.is_control_pressed(0,37)and not native.is_disabled_control_pressed(0,37)
 end)
 add(0x1913FE4CBF41C463,function(p,ped)local flag=p[1].int32;return M.weapons and p[0].int32==ped and p[2].bool and (flag==48 or flag==113)end)
 add(0xEB354E5376BC81A7,function(p)return M.weapons and wheel_requested()and not p[0].bool end)
 add(0xEFF296097FF1E509,function(p,ped)return M.weapons and p[0].int32==ped and not p[1].bool end)
 add(0xB4771B9AAF4E68E4,function(p,ped)return M.weapons and p[0].int32==ped and not p[2].bool and native.has_ped_got_weapon(ped,p[1].uint32,false)end)
 -- This native has no parameters to rewrite: block its result-suppression call.
 for _,id in ipairs({0x0AFC4AF510774B47,script_hashes[0x0AFC4AF510774B47]})do
 local ok,handle=pcall(hook.native,id,0,{pre=function(call)
  trace_call(0x0AFC4AF510774B47)
  trace_registration(0x0AFC4AF510774B47,id)
  if M.weapons and not state.is_open and context()then
   M.suppressed_calls=(M.suppressed_calls or 0)+1
   return hook.scripts.block
  end
  return hook.scripts.continue
 end})
 registration_results[string.format("%016X",id)]=ok and handle and "accepted"or("rejected: "..tostring(handle))
 if ok and handle then handles[#handles+1]=handle;handle.enabled=false
 else M.rejected=M.rejected+1;M.last_rejection="Wheel suppression hook rejected: "..tostring(id)end
 end
