function M.set(key,value)
 if key~="movement"and key~="weapons"then return false,"Unknown interior option."end
 value=value==true
 if value then
  local ok,reason=pcall(function()check_permissions();install()end)
  if not ok then
   M.cleanup();handles={};return false,tostring(reason)
  end
 end
 M[key]=value
 if key=="weapons"and not value then release_wheel();equip_check=nil;restore_weapon_flags()end
 local ok,reason=pcall(update_handles)
 if not ok then M.cleanup();return false,tostring(reason)end
 if value then
  local started,detail=start_worker()
  if not started then M.cleanup();return false,detail end
 end
 return true
end
function M.cleanup()
 M.weapons=false;release_wheel();equip_check=nil;restore_weapon_flags()
 generation=generation+1;worker=false;chosen_weapon=nil;wheel_selection=nil;wheel_was_open=false;observed_ped=nil
 M.movement=false;M.weapons=false
 M.status="Interior controls are off."
 for _,handle in ipairs(handles)do pcall(function()handle.enabled=false end)end
end
M.shutdown=M.cleanup
function M.equip_owned()
 local ped=context()
 if not ped or not M.weapons then return false,"Enable Weapons in Interiors and stand inside an interior on foot."end
 local weapon=native.get_selected_ped_weapon(ped)
 if not weapon or (weapon & 0xFFFFFFFF)==0xA2719263 then weapon=native.get_best_ped_weapon(ped,false)end
 if not weapon or weapon==0 or (weapon & 0xFFFFFFFF)==0xA2719263 or not native.has_ped_got_weapon(ped,weapon,false)then return false,"No owned weapon available. Equip one outside before entering."end
 check_permissions()
 unlock_weapon_flags(ped)
 allow_weapon_selection(ped,weapon)
 observed_ped=ped
 chosen_weapon=weapon;wheel_selection=nil;wheel_was_open=false
 native.set_ped_can_switch_weapon(ped,true)
 native.set_current_ped_weapon(ped,weapon,true)
 native.set_ped_current_weapon_visible(ped,true,false,false,false)
 equip_check={ped=ped,weapon=weapon & 0xFFFFFFFF,started=util.get_tick_count(),stable=0}
 M.equip_status="Checking whether GTA keeps the weapon equipped..."
 state.notify_info(M.equip_status)
 return true
end
function M.diagnose_wheel()
 if trace_busy then return false,"A wheel diagnostic is already running."end
 trace_busy=true;trace_sources={};detail_logs={};wheel_hook_hits={};wheel_log_at={}
 local token=generation
 trace_until=util.get_tick_count()+6000
 local ok,reason=pcall(util.create_job,function()
  local runtime=require("MorpheusMouse.job_runtime")
  local ran,detail=runtime.run(function()
   local samples=0;local disabled={};local last={}
   while generation==token and util.get_tick_count()<trace_until do
    if not state.is_open then
     local ped=native.player_ped_id()
     if ped~=0 and native.does_entity_exist(ped)then
      samples=samples+1
      for _,id in ipairs({12,13,14,15,16,17,24,25,37})do
       if not native.is_control_enabled(0,id)then disabled[id]=(disabled[id]or 0)+1 end
      end
      last.selected=native.get_selected_ped_weapon(ped) & 0xFFFFFFFF
      last.highlight=native.hud_get_weapon_wheel_currently_highlighted() & 0xFFFFFFFF
      last.switch=native.get_ped_config_flag(ped,48,true)
      last.holster=native.get_ped_config_flag(ped,113,true)
      last.melee=native.get_ped_config_flag(ped,122,true)
      last.armed=native.is_ped_armed(ped,4)
      last.ready=native.is_ped_weapon_ready_to_shoot(ped)
     end
    end
    runtime.yield(50)
   end
   if generation~=token then return end
   if samples==0 then state.notify_warning("No samples: run the diagnostic again and close SPACEx.");return end
   local controls={};for _,id in ipairs({12,13,14,15,16,17,24,25,37})do if disabled[id]then controls[#controls+1]=tostring(id).."="..tostring(disabled[id])end end
   local sources={};for key,count in pairs(trace_sources)do sources[#sources+1]={key=key,count=count}end
   table.sort(sources,function(a,b)return a.count>b.count end)
   local callers={};for i=1,math.min(4,#sources)do callers[#callers+1]=sources[i].key.." x"..tostring(sources[i].count)end
   M.lock_report=string.format("Wheel report: %d samples; disabled controls [%s]; selected %08X; highlighted %08X; switchBlocked=%s; holster=%s; meleeBlocked=%s; armed=%s; ready=%s; callers [%s]",samples,table.concat(controls,","),last.selected or 0,last.highlight or 0,tostring(last.switch),tostring(last.holster),tostring(last.melee),tostring(last.armed),tostring(last.ready),table.concat(callers,"; "))
   local registrations={}
   for hash,count in pairs(wheel_hook_hits)do registrations[#registrations+1]=hash.."="..tostring(count)end
   table.sort(registrations)
   M.lock_report=M.lock_report.."; weaponMode="..tostring(M.weapons).."; blocked="..tostring(M.blocks).."; wheelHooks["..table.concat(registrations,",").."]"
   print("[SPACEx interior diagnostic] "..M.lock_report)
   state.notify_info(M.lock_report)
  end)
  trace_busy=false;trace_until=0
  if not ran then state.notify_warning("Wheel diagnostic: "..tostring(detail))end
 end)
 if not ok then trace_busy=false;trace_until=0;return false,tostring(reason)end
 state.notify_info("Diagnostic started. Close SPACEx and hold LB/Tab for 6 seconds. A lock report will appear.")
 return true
end
function M.registration_report()
 local lines={}
 for _,id in ipairs({0xFE99B66D079CF6BC,0x66EFB3D6110055C4,0x5E6CC07646BBEAB8,0xEF387B90B8B97EDA,0x0AFC4AF510774B47,0xF25C7C5177203507,0xEB354E5376BC81A7,0x92D8C10950A06B6D})do
  local key=string.format("%016X",id)
  lines[#lines+1]=key..": "..tostring(registration_results[key]or "not attempted")
 end
 local report="Interior hook registration: "..table.concat(lines,"; ")
 print(report);state.notify_info(report);return true
end
local scoped_handles={}
local scoped_counts={}
local scoped_registrations={}
local scoped_until=0
local scoped_labels={
 {0xFE99B66D079CF6BC,"control"},{0x5E6CC07646BBEAB8,"firing"},
 {0xADF692B254977C0C,"weapon"},{0x0AFC4AF510774B47,"suppress"},
 {0xEB354E5376BC81A7,"wheel"},{0x5F4B6931816E599B,"allControls"},
 {0x14E56BC5B5DB6A19,"ammo"},{0xF25DF915FA38C5F3,"removeWeapons"}}
function M.trace_apartment()
 if scoped_until~=0 then return false,"Apartment trace already running."end
 if #scoped_handles==0 then
  for _,entry in ipairs(scoped_labels)do
   local hash,label=entry[1],entry[2]
   local ok,h=pcall(hook.native,hash,"am_mp_property_int",{pre=function(call)
    if scoped_until==0 or util.get_tick_count()>scoped_until then return hook.scripts.continue end
    scoped_counts[label]=(scoped_counts[label]or 0)+1
    local params=call.params
    if label=="control"then
     local id=params[1].int32
     if id==24 or id==25 or id==37 or id==257 then scoped_counts["control"..id]=(scoped_counts["control"..id]or 0)+1 end
    end
    return hook.scripts.continue
   end})
   scoped_registrations[label]=ok and h and "ok"or "rejected"
   if ok and h then h.enabled=false;scoped_handles[#scoped_handles+1]=h end
  end
 end
 scoped_counts={};scoped_until=util.get_tick_count()+7000
 for _,h in ipairs(scoped_handles)do h.enabled=true end
 local ok,reason=pcall(util.create_job,function()
  local runtime=require("MorpheusMouse.job_runtime")
  local ran,detail=runtime.run(function()
  while scoped_until~=0 and util.get_tick_count()<=scoped_until do runtime.yield(50)end
  scoped_until=0;for _,h in ipairs(scoped_handles)do h.enabled=false end
  local parts={}
  for _,entry in ipairs(scoped_labels)do local label=entry[2];parts[#parts+1]=label.."="..tostring(scoped_counts[label]or 0).."("..tostring(scoped_registrations[label])..")"end
  for _,id in ipairs({24,25,37,257})do parts[#parts+1]="control"..id.."="..tostring(scoped_counts["control"..id]or 0)end
  local ped=native.player_ped_id();local selected=native.get_selected_ped_weapon(ped)
  local ammo_ok,ammo=pcall(function()return invoker.call(0x015A522136D7F951,ped,selected).int end)
  parts[#parts+1]="selected="..string.format("%08X",selected & 0xFFFFFFFF).." ammo="..tostring(ammo_ok and ammo or "unavailable")
  local report="Apartment scoped trace: "..table.concat(parts,"; ")
  M.scoped_report=report;print(report);state.notify_info(report)
  end)
  if not ran then
   scoped_until=0;for _,h in ipairs(scoped_handles)do h.enabled=false end
   M.scoped_report="Apartment trace failed: "..tostring(detail);state.notify_warning(M.scoped_report)
  end
 end)
 if not ok then scoped_until=0;for _,h in ipairs(scoped_handles)do h.enabled=false end;return false,tostring(reason)end
 state.notify_info("Apartment trace started: close menu, choose a gun, aim and fire for 7 seconds.");return true
end
local original_cleanup=M.cleanup
function M.cleanup(...)scoped_until=0;for _,h in ipairs(scoped_handles)do h.enabled=false end;return original_cleanup(...)end
function M.rows()
 local rows={}
 for _,entry in ipairs({{"movement","Interior Movement"},{"weapons","Weapons in Interiors"}})do
  local key,label=entry[1],entry[2]
  rows[#rows+1]={label=label,value=function()return M[key]and"On"or"Off"end,run=function()return M.set(key,not M[key])end,adjust=function()return M.set(key,not M[key])end}
 end
 rows[#rows+1]={label="Equip Owned Weapon Indoors",run=M.equip_owned}
 rows[#rows+1]={label="Interior Status",value=function()return M.status end,run=function()state.notify_info(M.status.." | rejected "..tostring(M.rejected).." | "..tostring(M.last_rejection or "No registration rejection recorded")..(M.post_error and " | post error: "..M.post_error or "")..(M.wheel_status and " | "..M.wheel_status or "")..(M.equip_status and " | "..M.equip_status or "")..(M.permission_note and " | "..M.permission_note or ""));return true end}
 return rows
end
function M.draw(pos,width)
 local widgets=require("MorpheusMouse.widgets");local theme=require("MorpheusMouse.theme")
 local height=theme.control_height(32,26);local y=pos.y
 widgets.section(vec2(pos.x,y),"INTERIOR CONTROLS");y=y+28
 for _,entry in ipairs({{"movement","Interior Movement","Allow sprint and jump controls in interiors."},{"weapons","Weapons in Interiors","Allow weapon selection, aiming and firing in interiors. Some interiors may enforce additional restrictions."}})do
  local key,label,help=entry[1],entry[2],entry[3]
  if widgets.button(vec2(pos.x,y),vec2(width,height),label..": "..(M[key]and"ON"or"OFF"),help)then
   local ok,reason=M.set(key,not M[key]);if not ok then state.notify_warning(reason)end
  end
  y=y+height+6
 end
 if widgets.button(vec2(pos.x,y),vec2(width,height),"EQUIP OWNED WEAPON INDOORS","Uses an existing owned weapon; close the menu to test aiming and firing.")then
  local ok,reason=M.equip_owned();if not ok then state.notify_warning(reason)end
 end
 y=y+height+6
 y=y+widgets.status_card(vec2(pos.x,y),width,"Interior Status",M.status,true)
 return y-pos.y+10
end
return M

end

local started,detail=xpcall(function()
 local root=paths.game.."\\scripts\\MorpheusMouse\\"
 for _,suffix in ipairs({"","Diagnostics\\","PaintJobs\\","data\\","assets\\","builds\\","builds\\imports\\"}) do
  local path=root..suffix
  if not dirs.exists(path) then local result=dirs.create(path); if result==false then error("Could not create "..path) end end
 end
 print("Morpheus Standalone: starting unsigned test build; F7 opens the menu")
 print("Morpheus Mouse: automatic menu inventory skipped; loading app")
 local app=require("MorpheusMouse.app")
 print("Morpheus Mouse: app module loaded; starting runtime")
 util.create_job(function()
  local ran,reason=xpcall(function()
   print("Morpheus Mouse: startup job entered")
   local success,detail=app.start()
   if success==false then error(detail or "Startup failed")end
   local updater_ok,updater_error=pcall(function()require("MorpheusMouse.script_updater").start()end)
   if not updater_ok then print("[SPACEx updater] "..tostring(updater_error))end
   print("Morpheus Mouse: startup job returned")
  end,debug.traceback)
  if not ran then fail(reason)end
 end)
 print("Morpheus Mouse: automatic compatibility scans disabled for startup isolation")
end,debug.traceback)
if not started then fail(detail) end
